    if(s.path==='yes')for(let i=1;i<PD.door.displayFrames.length;i++)line(PM.pos(PD.door.displayFrames[i-1].tool),PM.pos(PD.door.displayFrames[i].tool),i<=s.frame?'#ffbc70aa':'#52647e66',1.3);
    dot(PM.pos(f.tool),C.gold,5);triad(PM.pos(f.tool),PM.rot(f.tool),.07,'记录·');
