    if(s.mode==='parallel'){normal=G.unit(G.cross(first.direction,Math.abs(first.direction[0])<.8?[1,0,0]:[0,1,0]));offset=-G.dot(normal,[0,0,0])}
    if(s.mode==='behind')offset=-G.dot(normal,G.sub(first.origin,first.direction));
    const hit=PM.rayPlane([s.u,s.v],normal,offset),Cw=hit.origin,Twc=PM.inverseAffine(PD.camera.view),basis=G.basis(normal),pc=G.scale(normal,-offset/G.dot(normal,normal));
