function animateProject(id,dt){
  if(animateHardwareLab(id,dt))return true;
  if(animateUrdfLab(id,dt))return true;
  if(animateExtraProject(id,dt))return true;
  if(!PROJECT_LESSONS.some(l=>l.id===id))return false;
  if(id==='replay'){state.frame=(state.frame+24*dt)%253}
  else if(id==='pipeline')state.stage=Math.floor(animTime/2)%8;
  else if(id==='frames'){state.x=Math.sin(animTime)*.2}
  else if(id==='alignment')state.step=Math.floor(animTime/1.4)%4;
  else if(id==='urdf')state.j0=35*Math.sin(animTime*.7);
  else if(id==='binding')state.pan=40*Math.sin(animTime*.7);
  else if(id==='retreat')state.angle=30+30*Math.sin(animTime*.7);
  else if(id==='rayplane')state.u=640+250*Math.sin(animTime*.7);
  return true;
}

// Rz(yaw) Ry(pitch) Rx(roll): extrinsic xyz = intrinsic ZYX.
const RotationMath = {
  vector:[.38,.18,.26],
  axes(pitch,yaw){
    const Z=G.rz(G.rad(yaw)),ZY=G.mm(Z,G.ry(G.rad(pitch)));
    return {Z,ZY,roll:G.mv(ZY,[1,0,0]),pitch:G.mv(Z,[0,1,0]),yaw:[0,0,1]};
  },
  compare(roll,pitch,yaw,delta){
    const axes=this.axes(pitch,yaw),sign=pitch<0?-1:1;
    const R=G.euler(roll,pitch,yaw),other=G.euler(roll+delta,pitch,yaw+sign*delta);
    const J=G.transpose([axes.roll,axes.pitch,axes.yaw]);
    const residual=Math.max(...R.flatMap((row,i)=>row.map((v,j)=>Math.abs(v-other[i][j]))));
    return {axes,R,other,J,residual,sign};
  }
};
function renderRotationLesson(s){
  renderRotationFoundations(s);
  const {axes,R,other,J,residual,sign}=RotationMath.compare(s.roll,s.pitch,s.yaw,s.delta);
  const c=[0,0,.6],at=v=>G.add(c,v),ex=[1,0,0],ey=[0,1,0],ez=[0,0,1];
  // Each ring lies in the plane perpendicular to its own rotation axis.
  circle(c,ex,ey,1.12,C.z);
  circle(c,G.mv(axes.Z,ex),G.mv(axes.Z,ez),.96,C.y);
  circle(c,G.mv(axes.ZY,ey),G.mv(axes.ZY,ez),.8,C.x);
  for(const [axis,color,size,name] of [[axes.yaw,C.z,1.38,'yaw · Z'],[axes.pitch,C.y,1.26,'pitch · Y′'],[axes.roll,C.x,1.18,'roll · X″']]){
    arrow(at(G.scale(axis,-size)),at(G.scale(axis,size)),color,2.5,name);
  }
  cube(c,other,.53,C.purple,true);cube(c,R,.53,C.gold);triad(c,R,.52,'B·');
  const p=RotationMath.vector;arrow(c,at(G.mv(R,p)),C.white,2,'Rp');
  matrix('R = Rz · Ry · Rx',R);
  stats([['det(R) / 正交误差',fmt(G.det(R),6)+' / '+G.orthoError(R).toExponential(1)],
    ['|a_roll · a_yaw|',fmt(Math.abs(G.dot(axes.roll,axes.yaw)),5)],
    ['det(J_Euler) = cos(pitch)',fmt(G.det(J),5)],
    ['虚线角 (r+Δ, p, y'+(sign>0?'+':'−')+'Δ)',vec([s.roll+s.delta,s.pitch,s.yaw+sign*s.delta],1)+'°'],
    ['两组 R 最大元素差',residual.toExponential(2)],
    ['欧拉角局部独立方向',Math.abs(Math.cos(G.rad(s.pitch)))<1e-10?'2 / 3 · 万向节锁':'3 / 3'+(Math.abs(s.pitch)>=85?' · 接近奇异':'')]]);
  const locked=Math.abs(Math.cos(G.rad(s.pitch)))<1e-10;
  live(locked?'万向节锁：红 / 蓝轴共线；非零 Δ 的虚线与实线姿态重合。两个角可相互抵消，物体仍能用其他旋转表示自由转动。':Math.abs(s.pitch)>=85?'接近锁定：红 / 蓝轴接近共线。把 pitch 设为 ±90°，观察非零 Δ 的对照姿态完全重合。':'红 / 绿 / 蓝是嵌套环的瞬时旋转轴，不是物体系三根轴。先选单轴预设播放，再对照 ±90° 锁定。',locked||Math.abs(s.pitch)>=85);
  legend([['roll 环 / 轴',C.x],['pitch 环 / 轴',C.y],['yaw 环 / 轴',C.z],['对照姿态（虚线）',C.purple]]);
  setCode(pythonBase+`r, p, y = ${JSON.stringify([s.roll,s.pitch,s.yaw])}  # degrees\ndelta = ${s.delta}\nrot = R.from_euler('xyz', [r, p, y], degrees=True)\n# 固定世界轴 xyz 等价于自身轴 ZYX，注意角度顺序\nassert np.allclose(rot.as_matrix(),\n    R.from_euler('ZYX', [y, p, r], degrees=True).as_matrix())\n\nsign = -1 if p < 0 else 1\nother = R.from_euler('xyz', [r+delta, p, y+sign*delta], degrees=True)\nprint('对照姿态矩阵差:', np.max(np.abs(rot.as_matrix()-other.as_matrix())))\n# p=+90: roll/yaw 同加 delta；p=-90: roll 加、yaw 减\n# 仅在锁定处（或 delta=0）这组对照才必然相同。\n\nRz = R.from_euler('z', y, degrees=True).as_matrix()\nRy = R.from_euler('y', p, degrees=True).as_matrix()\na_roll = Rz @ Ry @ np.array([1., 0., 0.])\na_pitch = Rz @ np.array([0., 1., 0.])\na_yaw = np.array([0., 0., 1.])\nJ_euler = np.column_stack([a_roll, a_pitch, a_yaw])\n# omega_world = J_euler @ [roll_rate, pitch_rate, yaw_rate]\nprint('det(J_euler):', np.linalg.det(J_euler))\nprint('rank(J_euler):', np.linalg.matrix_rank(J_euler))\nassert np.allclose(np.linalg.det(rot.as_matrix()), 1.)\n# 欧拉角表示奇异 ≠ 旋转矩阵奇异 ≠ 机器人运动学奇异`);
}
function animateRotationLesson(s,dt){
  const wrap=x=>((x+180)%360+360)%360-180,step=dt*32;
  if(s.motion==='locked'){
    s.pitch=s.pitch<0?-90:90;
    s.roll=wrap(s.roll+step);s.yaw=wrap(s.yaw+(s.pitch<0?-step:step));
  }else if(s.motion==='pitch'||s.motion==='all'){
    // Bounce at the displayed ±90° range instead of silently wrapping at a lock.
    let next=s.pitch+step*(s.pitchDirection||1);
    if(next>90){next=180-next;s.pitchDirection=-1}
    if(next<-90){next=-180-next;s.pitchDirection=1}
    s.pitch=next;
    if(s.motion==='all'){s.roll=wrap(s.roll+step*.7);s.yaw=wrap(s.yaw+step*.9)}
  }else{
    s[s.motion]=wrap(s[s.motion]+step);
  }
}

// Formula walkthrough uses the same angles and test vector as the 3D lesson.
const RotationFoundations = {
  sample(s){
    const Rx=G.rx(G.rad(s.roll)),Ry=G.ry(G.rad(s.pitch)),Rz=G.rz(G.rad(s.yaw));
    const R=G.mm(Rz,G.mm(Ry,Rx)),v0=RotationMath.vector.slice();
    const v1=G.mv(Rx,v0),v2=G.mv(Ry,v1),v3=G.mv(Rz,v2);
    const columns=G.transpose(R),recovered=G.mv(G.transpose(R),v3);
    const weighted=columns.reduce((sum,col,i)=>G.add(sum,G.scale(col,v0[i])),[0,0,0]);
    return {Rx,Ry,Rz,R,v0,v1,v2,v3,columns,recovered,weighted};
  }
};
let rotationFoundationStep='plane';
const foundationSteps=[['plane','1 · 二维推导'],['axes','2 · 三轴矩阵'],['multiply','3 · 逐行相乘'],['compose','4 · 复合顺序'],['inverse','5 · 逆与坐标系']];
function foundationMatrix(name,rows,symbolic=false){
  return '<div><div class="foundation-caption">'+esc(name)+'</div><div class="matrix"><table aria-label="'+esc(name)+'">'+rows.map(row=>'<tr>'+row.map(v=>'<td>'+esc(symbolic?v:fmt(v,3))+'</td>').join('')+'</tr>').join('')+'</table></div></div>';
}
function foundationPlane(yaw){
  const a=G.rad(yaw),c=Math.cos(a),s=Math.sin(a),cx=180,cy=142,r=87;
  const x=cx+r*c,y=cy-r*s,bx=cx-r*s,by=cy-r*c;
  return `<svg class="foundation-plot" viewBox="0 0 360 282" role="img" aria-label="二维单位圆：旋转后的 X 基向量为 cosθ、sinθ，Y 基向量为负 sinθ、cosθ">
    <circle cx="180" cy="142" r="87" fill="none" stroke="${C.dim}"/>
    <path d="M60 142H306M180 258V22" fill="none" stroke="${C.dim}"/>
    <text x="310" y="147">X</text><text x="187" y="25">Y</text><text x="164" y="158">O</text>
    <path d="M${x} ${cy}V${y}H${cx}" fill="none" stroke="${C.gold}" stroke-dasharray="4 4"/>
    <path d="M${cx} ${cy}L${x} ${y}" stroke="${C.x}" stroke-width="3"/>
    <path d="M${cx} ${cy}L${bx} ${by}" stroke="${C.y}" stroke-width="3"/>
    <circle cx="${x}" cy="${y}" r="4" fill="${C.x}"/><circle cx="${bx}" cy="${by}" r="4" fill="${C.y}"/>
    <text x="${x+(c>=0?8:-8)}" y="${y-8}" text-anchor="${c>=0?'start':'end'}">eₓ′</text>
    <text x="${bx+(-s>=0?8:-8)}" y="${by-8}" text-anchor="${-s>=0?'start':'end'}">eᵧ′</text>
    <path d="M204 142 A24 24 0 0 ${yaw<0?1:0} ${cx+24*c} ${cy-24*s}" fill="none" stroke="${C.gold}"/>
    <text x="20" y="278">θ = ${fmt(yaw,1)}° · 从 +Z 朝原点看</text>
  </svg>`;
}
function renderRotationFoundations(s){
  const steps=$('foundationSteps');
  if(!steps.children.length){
    steps.innerHTML=foundationSteps.map(([key,title])=>'<button type="button" data-step="'+key+'" aria-controls="foundationContent" aria-pressed="false">'+title+'</button>').join('');
    steps.addEventListener('click',event=>{
      const button=event.target.closest('button[data-step]');if(!button)return;
      rotationFoundationStep=button.dataset.step;renderRotationFoundations(state);
    });
  }
  for(const button of steps.children)button.setAttribute('aria-pressed',String(button.dataset.step===rotationFoundationStep));
  const d=RotationFoundations.sample(s),f=fmt,v=vec;
  let content='';
  if(rotationFoundationStep==='plane'){
    content='<div class="foundation-grid">'+foundationPlane(s.yaw)+'<div><p><strong>先从单位基向量出发。</strong>二维中 eₓ=[1,0]ᵀ、eᵧ=[0,1]ᵀ。绕 +Z 正转 θ 时，eₓ 的投影变成 [cosθ,sinθ]ᵀ；eᵧ 比它多 90°，所以变成 [−sinθ,cosθ]ᵀ。负号来自投影，不是记忆规则。</p><span class="formula">eₓ′ = [cosθ, sinθ]ᵀ\neᵧ′ = [cos(θ+90°), sin(θ+90°)]ᵀ\n     = [−sinθ, cosθ]ᵀ\nR₂D = [ eₓ′ | eᵧ′ ]</span>'+foundationMatrix('R₂D(θ) · 每一列是一根旋转后的基向量',[['cosθ','−sinθ'],['sinθ','cosθ']],true)+'<p>把任意向量拆开：v = x eₓ + y eᵧ，旋转后 v′ = x eₓ′ + y eᵧ′。</p><span class="formula">x′ = x cosθ − y sinθ\ny′ = x sinθ + y cosθ\nθ = '+f(s.yaw,1)+'° = '+f(G.rad(s.yaw),4)+' rad\ncosθ = '+f(Math.cos(G.rad(s.yaw)),4)+'\nsinθ = '+f(Math.sin(G.rad(s.yaw)),4)+'</span><p>看向原点的观察者位于 +Z 侧时，正转为逆时针。图中 θ 使用上方 yaw；它只演示二维基向量，不包含 roll / pitch。</p></div></div>';
  }else if(rotationFoundationStep==='axes'){
    content='<p><strong>把二维平面嵌进三维：</strong>绕 X 时 x 不变，旋转发生在 YZ 平面；绕 Y 时 y 不变，旋转发生在 ZX 平面；绕 Z 时 z 不变，旋转发生在 XY 平面。特别注意 Ry 的正负号顺序。</p><div class="foundation-matrices">'+
      foundationMatrix('Rx(r) · X 分量不变',[[1,0,0],[0,'cos r','−sin r'],[0,'sin r','cos r']],true)+
      foundationMatrix('Ry(p) · Y 分量不变',[['cos p',0,'sin p'],[0,1,0],['−sin p',0,'cos p']],true)+
      foundationMatrix('Rz(y) · Z 分量不变',[['cos y','−sin y',0],['sin y','cos y',0],[0,0,1]],true)+'</div><p>代入当前角度。度数先乘 π/180 再交给 sin / cos：</p><div class="foundation-matrices">'+
      foundationMatrix('Rx('+f(s.roll,1)+'°)',d.Rx)+foundationMatrix('Ry('+f(s.pitch,1)+'°)',d.Ry)+foundationMatrix('Rz('+f(s.yaw,1)+'°)',d.Rz)+'</div><span class="formula">Rx(+90°) eᵧ = e_z\nRy(+90°) e_z = eₓ\nRz(+90°) eₓ = eᵧ</span><p>右手拇指沿旋转轴正向，四指弯曲的方向是正转。上方“只看 X / Y / Z”可以分别核对。</p>';
  }else if(rotationFoundationStep==='multiply'){
    const rows=d.R.map((row,i)=>['x′','y′','z′'][i]+' = '+row.map((n,j)=>'('+f(n,5)+') × '+f(d.v0[j],2)).join(' + ')+' = '+f(d.v3[i],5));
    content='<p><strong>矩阵乘列向量，就是每一行做一次点积。</strong>这里的 v 是上方白色 Rp 箭头旋转前的局部向量；箭头起点是物体中心，不是世界原点。</p><span class="formula">v = '+v(d.v0,2)+'ᵀ\nx′ = R₁₁x + R₁₂y + R₁₃z\ny′ = R₂₁x + R₂₂y + R₂₃z\nz′ = R₃₁x + R₃₂y + R₃₃z</span><div class="foundation-matrices">'+foundationMatrix('当前 R',d.R)+'</div><span class="formula">'+rows.join('\n')+'</span><p>也可以按列理解：R v = x·第一列 + y·第二列 + z·第三列。两种算法结果相同。</p><span class="formula">按列加权 = '+v(d.weighted,5)+'ᵀ\n按行点积 = '+v(d.v3,5)+'ᵀ\n画面箭头端点 = 物体中心 + Rv</span><p>显示数值经过舍入，内部仍以完整精度计算。</p>';
  }else if(rotationFoundationStep==='compose'){
    content='<p><strong>嵌套函数从内往外算，因此最右边的矩阵先作用。</strong>这里逐步绕固定世界轴 X、Y、Z 旋转；不是绕每一步变化后的自身轴。</p><span class="formula">v₁ = Rx(r) v₀\nv₂ = Ry(p) v₁\nv₃ = Rz(y) v₂\n所以 v₃ = Rz(y) Ry(p) Rx(r) v₀</span><span class="formula">v₀          = '+v(d.v0,5)+'\nRx 后 v₁    = '+v(d.v1,5)+'\nRy 后 v₂    = '+v(d.v2,5)+'\nRz 后 v₃    = '+v(d.v3,5)+'\n一次算 Rv₀ = '+v(G.mv(d.R,d.v0),5)+'\n两条计算路线误差 = '+G.norm(G.sub(d.v3,G.mv(d.R,d.v0))).toExponential(2)+'</span><p>矩阵乘法满足结合律，所以可以先把三个矩阵乘起来；通常不满足交换律，所以不能任意调换 Rx、Ry、Rz。下一实验会专门比较世界增量与局部增量。</p>';
  }else{
    content='<p><strong>为什么用转置就能旋转回去？</strong>R 的三列是单位正交向量：每列长度 1，任意两列点积为 0，因此 RᵀR=I，故 R⁻¹=Rᵀ。还要 det(R)=+1，才能排除镜像反射。</p><span class="formula">eᵢ · eᵢ = 1，eᵢ · eⱼ = 0 (i≠j)\nRᵀR = I　→　R⁻¹ = Rᵀ\n‖Rv‖ = ‖v‖\n9 个矩阵元素受 6 个独立约束，朝向仍只有 3 个自由度。</span><div class="foundation-matrices">'+foundationMatrix('当前 RᵀR',G.mm(G.transpose(d.R),d.R))+'</div><span class="formula">det(R) = '+f(G.det(d.R),6)+'\n‖v‖ = '+f(G.norm(d.v0),6)+'\n‖Rv‖ = '+f(G.norm(d.v3),6)+'\nRᵀ(Rv) = '+v(d.recovered,5)+'\n回算误差 = '+G.norm(G.sub(d.recovered,d.v0)).toExponential(2)+'</span><p><strong>主动旋转与坐标换算：</strong>主动旋转 p′=Rp 是同一个坐标系里改变向量；p_W=R_WB p_B 是同一个向量换一套坐标描述，反向为 p_B=R_WBᵀp_W。数值形式相同，语义要看下标。</p><p class="caution">这里只讨论同原点的方向 / 向量。点坐标换系通常还需要平移：p_W=R_WB p_B+t_WB；完整 4×4 变换的逆不能直接用整个矩阵转置。URDF 的 origin rpy 是固定装配，joint angle q 是随后施加的运动，不要混为一谈。</p><p><a href="https://modernrobotics.northwestern.edu/nu-gm-book-resource/3-2-1-rotation-matrices-part-1-of-2/" target="_blank" rel="noopener">参考：Modern Robotics · 旋转矩阵</a></p>';
  }
  $('foundationContent').innerHTML=content;
}

// Same frame chain as the original transform lesson; points and directions differ in w.
const PointDirectionMath = {
  sample(s){
    const T_WB=G.T(G.rz(G.rad(s.yaw)),[s.tx,s.ty,.25]);
    const T_BG=G.T(G.ry(G.rad(s.tilt)),[.8,.1,.4]);
    const H=G.mm(T_WB,T_BG),R=H.slice(0,3).map(row=>row.slice(0,3));
    const pLocal=[.2,.2,.2],directionLocal=[0,0,1];
    const pointHomogeneous=G.mv(H,[...pLocal,1]);
    const directionHomogeneous=G.mv(H,[...directionLocal,0]);
    const pointWorld=pointHomogeneous.slice(0,3),directionWorld=directionHomogeneous.slice(0,3);
    const baseline=G.mm(G.T(G.rz(G.rad(s.yaw)),[0,0,.25]),T_BG);
    const baselinePoint=G.point(baseline,pLocal);
    const baselineDirection=G.mv(baseline,[...directionLocal,0]).slice(0,3);
    const inverse=G.inverse(H);
    return {T_WB,T_BG,H,R,pLocal,directionLocal,pointWorld,directionWorld,
      pointHomogeneous,directionHomogeneous,originBase:G.point(T_WB,[0,0,0]),
      originTool:G.point(H,[0,0,0]),translation:H.slice(0,3).map(row=>row[3]),
      recoveredPoint:G.point(inverse,pointWorld),
      recoveredDirection:G.mv(inverse,[...directionWorld,0]).slice(0,3),
      baselinePoint,baselineDirection,
      pointTranslationDelta:G.sub(pointWorld,baselinePoint),
      directionTranslationDelta:G.sub(directionWorld,baselineDirection)};
  }
};

function renderPointDirectionLesson(s){
  const d=PointDirectionMath.sample(s),O=[0,0,0],drawLength=.55;
  triad(d.originBase,d.T_WB.slice(0,3).map(row=>row.slice(0,3)),.5,'B·');
  triad(d.originTool,d.R,.42,'G·');
  line(O,d.originBase,C.purple,2,true);
  line(d.originBase,d.originTool,C.purple,2,true);
  cube(d.originTool,d.R,.2,C.purple);
  line(d.originTool,d.pointWorld,C.gold,2);
  dot(d.pointWorld,C.gold,6);label(d.pointWorld,'点 p · w=1',C.gold,8,18);
  const tipTool=G.add(d.originTool,G.scale(d.directionWorld,drawLength));
  arrow(d.originTool,tipTool,C.y,3,'d_W · 工具处');
  arrow(O,G.scale(d.directionWorld,drawLength),C.y,3,'同一方向 · 原点副本');
  dot(d.baselinePoint,C.gold,3);
  if(G.norm(d.pointTranslationDelta)>.001){
    line(d.baselinePoint,d.pointWorld,C.gold,1.5,true);
    label(d.baselinePoint,'tx=ty=0 时的点',C.gold,-115,17);
  }
  matrix('T_WG =',d.H);
  const pointError=G.norm(G.sub(d.recoveredPoint,d.pLocal));
  const directionError=G.norm(G.sub(d.recoveredDirection,d.directionLocal));
  stats([['点 p_G → p_W',vec(d.pLocal)+' → '+vec(d.pointWorld)+' m'],
    ['方向 d_G → d_W',vec(d.directionLocal)+' → '+vec(d.directionWorld)],
    ['仅 tx/ty 引起的点位移',vec(d.pointTranslationDelta)+' m'],
    ['仅 tx/ty 引起的方向变化',G.norm(d.directionTranslationDelta).toExponential(1)],
    ['逆变换回算误差',pointError.toExponential(1)+' m / '+directionError.toExponential(1)]]);
  live('只拖 tx / ty：橙色点随工具平移，两根绿色箭头始终平行且等长；改变 yaw / tilt，方向才旋转。箭头可换起点，方向分量不变。');
  legend([['点 · w=1',C.gold],['方向 · w=0',C.y],['W→B→G',C.purple]]);
  const details=$('pointDirectionDetails');
  if(details){
    details.innerHTML='<h3>点与方向：同一个变换，为什么结果不同？</h3>'+
      '<p>点 p 表示一个位置，方向 d 表示朝哪边。采用列向量，T_WG 把 G 系描述变成 W 系描述；它的旋转为 R，平移为 t。</p>'+
      '<span class="formula">T = [ R  t ]\n    [ 0  1 ]\n\n点：   T [p_G; 1] = [R p_G + t; 1]\n方向： T [d_G; 0] = [R d_G;     0]</span>'+
      '<p><strong>最后一列乘的是齐次分量 w：</strong>点的 w=1，所以加 t；方向的 w=0，所以平移项消失。d_G=[0,0,1] 是无量纲单位接近方向，p_G 的单位为米。绿色箭头为显示方便画成 0.55 m；这不是把方向当作位置。</p>'+
      '<span class="formula">当前 t_WG = '+vec(d.translation)+' m\n[p_W; 1] = '+vec(d.pointHomogeneous)+'\n[d_W; 0] = '+vec(d.directionHomogeneous)+'\n\n与 tx=ty=0、但 yaw/tilt 相同的基线相比：\nΔp_W = '+vec(d.pointTranslationDelta)+' m\nΔd_W = '+vec(d.directionTranslationDelta)+'</span>'+
      '<p><strong>为什么方向箭头可以移动？</strong>把两点 a、b 同时换系，再相减：平移抵消。图中两根绿色箭头的起点不同，但位移向量相同。它们是同一自由方向的两个画法，不是两条不同接近路径。</p>'+
      '<span class="formula">b_W − a_W = (R b_G + t) − (R a_G + t)\n          = R (b_G − a_G)\n\n坐标链：T_WG = T_WB T_BG\np_G = T_GW [p_W; 1] 的前三项\nd_G = R_WGᵀ d_W\nT_GW = [R_WGᵀ, −R_WGᵀ t_WG; 0, 1]</span>'+
      '<p class="caution">这里固定工具局部坐标，再调整工具在世界中的位姿，所以世界位置会变。不是在移动同一个静止世界点。Scene2 中 TCP 位置用点变换，夹爪接近方向用方向变换；法线在刚体旋转下也只乘 R，但一般含非均匀缩放的矩阵需要逆转置。</p>';
  }
  setCode(pythonBase+`def make_T(rot, translation):
    T = np.eye(4)
    T[:3, :3] = rot.as_matrix()
    T[:3, 3] = translation
    return T

T_WB = make_T(R.from_euler('z', ${s.yaw}, degrees=True), ${vec([s.tx,s.ty,.25])})
T_BG = make_T(R.from_euler('y', ${s.tilt}, degrees=True), [0.8, 0.1, 0.4])
T_WG = T_WB @ T_BG  # G -> B -> W
p_G = np.array([0.2, 0.2, 0.2, 1.0])  # point, w=1
d_G = np.array([0.0, 0.0, 1.0, 0.0])  # direction, w=0
p_W = T_WG @ p_G
d_W = T_WG @ d_G
print('point:', p_W[:3], 'm; direction:', d_W[:3])
assert np.allclose(p_W[:3], T_WG[:3, :3] @ p_G[:3] + T_WG[:3, 3])
assert np.allclose(d_W[:3], T_WG[:3, :3] @ d_G[:3])
assert np.allclose(np.linalg.inv(T_WG) @ p_W, p_G)
assert np.allclose(np.linalg.inv(T_WG) @ d_W, d_G)
# Translation changes only the point, not the direction:
shifted = T_WG.copy()
shifted[:3, 3] += [0.3, -0.2, 0.1]
assert np.allclose((shifted @ d_G), d_W)
assert np.allclose((shifted @ p_G)[:3] - p_W[:3], [0.3, -0.2, 0.1])`);
}

// Read notation against the CURRENT frame chain, not an unrelated demo pose.
const NotationGuide={selected:'R',lesson:null,
  sample(id,s){
    const source=id==='rotation'?{local:'B',H:G.T(G.euler(s.roll,s.pitch,s.yaw),[0,0,.6]),p:RotationMath.vector}:PointDirectionMath.sample(s);
    const local=source.local||'G',H=source.H,p=(source.p||source.pLocal).slice();
    const R=H.slice(0,3).map(row=>row.slice(0,3)),Rt=G.transpose(R),t=H.slice(0,3).map(row=>row[3]);
    const rotated=G.mv(R,p),pWorld=G.point(H,p),inverse=G.inverse(H);
    const rotationRecovered=G.mv(Rt,rotated),pointRecovered=G.point(inverse,pWorld);
    const angles=id==='rotation'?[['roll',s.roll],['pitch',s.pitch],['yaw',s.yaw]]:[['yaw',s.yaw],['tilt',s.tilt]];
    return {local,H,p,R,Rt,t,rotated,pWorld,inverse,rotationRecovered,pointRecovered,angles,
      rotationError:G.norm(G.sub(rotationRecovered,p)),pointError:G.norm(G.sub(pointRecovered,p))};
  },
  numeric(key,d){
    const f=x=>(Math.abs(x)<.0005?0:x).toFixed(3),v=a=>'['+a.map(f).join(', ')+']';
    const mat=(name,A)=>name+' ('+A.length+'×'+A[0].length+')\n'+A.map(row=>'[ '+row.map(x=>f(x).padStart(6)).join('  ')+' ]').join('\n');
    const local='p_'+d.local,rot='R_W'+d.local,back='T_'+d.local+'W';
    switch(key){
    case 'R':return mat(rot,d.R)+'\n\nr_W = '+rot+' '+local+'\n    = '+v(d.rotated)+' m\np_W = r_W + t = '+v(d.pWorld)+' m';
    case 'p':return local+' = '+v(d.p)+' m\nR '+local+' = '+v(d.rotated)+' m\n再加 t = '+v(d.t)+' m\np_W = '+v(d.pWorld)+' m';
    case 'world':return 'p_W = '+v(d.pWorld)+' m\n'+local+' = Rᵀ(p_W − t)\n    = '+v(d.pointRecovered)+' m\n往返误差 = '+d.pointError.toExponential(2)+' m';
    case 't':return 't_W'+d.local+' = '+v(d.t)+' m\n这是 T 的最后一列前三项。\n局部原点 [0,0,0,1]ᵀ →\n世界位置 '+v(d.t)+' m';
    case 'T':return mat('T_W'+d.local,d.H)+'\n\n['+local+';1] = '+v([...d.p,1])+'\n[p_W;1] = '+v([...d.pWorld,1]);
    case 'transpose':return mat('R_'+d.local+'W = '+rot+'ᵀ',d.Rt)+'\n\nr_W = p_W − t = '+v(d.rotated)+' m\nRᵀ r_W = '+v(d.rotationRecovered)+' m\n找回 '+local+'，误差 = '+d.rotationError.toExponential(2)+' m\n注意：没有把点 p_W 直接乘 Rᵀ。';
    case 'inverse':return mat(back+' = inverse(T_W'+d.local+')',d.inverse)+'\n\n正向：'+v(d.p)+' →\np_W = '+v(d.pWorld)+' m\n反向：'+back+' [p_W;1] →\n'+local+' = '+v(d.pointRecovered)+' m\n往返误差 = '+d.pointError.toExponential(2)+' m';
    case 'column':return mat(local+' 的列向量写法',d.p.map(x=>[x]))+'\n\nR (3×3) × '+local+' (3×1) → r_W (3×1)\n坐标长度单位 m；列不是三个不同的点。';
    case 'units':return d.angles.map(([name,value])=>name+': '+f(value)+'° = '+f(G.rad(value))+' rad').join('\n')+'\n位置 p_W = '+v(d.pWorld)+' m\n旋转矩阵 R 的元素无量纲。';
    }
  }
};
function renderNotationGuide(id,s){
  const panel=$('notationGuide'),supported=id==='rotation'||id==='transform';
  panel.classList.toggle('hidden',!supported);
  if(!supported){$('matrix').classList.remove('notation-focus');$('controlUnits').classList.remove('notation-focus');return}
  const d=NotationGuide.sample(id,s),b=d.local,t=d.t,pW=d.pWorld,key=NotationGuide.selected;
  const names={R:'R_W'+b,p:'p_'+b,world:'p_W',t:'t_W'+b,T:'T_W'+b,transpose:'Rᵀ',inverse:'T⁻¹',column:'列向量',units:'度 / rad / m'};
  if(NotationGuide.lesson!==id){
    NotationGuide.lesson=id;
    $('notationTokens').innerHTML='<span class="mono">p_W = </span>'+['R','p'].map(k=>'<button type="button" data-notation="'+k+'">'+names[k]+'</button>').join('<span> × </span>')+'<span> + </span><button type="button" data-notation="t">'+names.t+'</button><span class="notation-break"></span>'+['world','T','transpose','inverse','column','units'].map(k=>'<button type="button" data-notation="'+k+'">'+names[k]+'</button>').join('');
  }
  if(!panel.dataset.wired){
    panel.dataset.wired='yes';panel.addEventListener('click',event=>{
      const token=event.target.closest('button[data-notation]');if(!token)return;
      NotationGuide.selected=token.dataset.notation;render();
    });
  }
  for(const token of panel.querySelectorAll('button'))token.setAttribute('aria-pressed',String(token.dataset.notation===key));
  const descriptions={
    R:['读作“'+b+' 系到 W 系的旋转”。W 是目标，'+b+' 是来源；三列是 '+b+' 的 X/Y/Z 轴在 W 中的方向。', 'R_W'+b+' p_'+b+' = p_W − t_W'+b+'（位移）；再加平移才得到世界位置。'],
    p:['这是同一个点在 '+b+' 系中的三个坐标，不是世界坐标。图中高亮它从局部原点指向该点的箭头。','p_'+b+' = '+vec(d.p,3)+'ᵀ m'],
    world:['同一个点换到 W 系后的坐标；点的位置并没有因为“换坐标”而产生额外物理运动。','p_W = '+vec(pW,3)+'ᵀ m'],
    t:['局部 '+b+' 原点在 W 中的位置，用 W 的轴方向表达；不是把三个数写进任何坐标系都能通用。','t_W'+b+' = '+vec(t,3)+'ᵀ m'],
    T:['4×4 齐次变换同时包含 R 和 t。乘在右侧的来源坐标补 1，得到目标坐标。','[p_W;1] = T_W'+b+' [p_'+b+';1]，T = [R,t; 0,0,0,1]'],
    transpose:['转置：交换矩阵的行和列。合法旋转满足 RᵀR=I，所以 Rᵀ=R⁻¹；不能推广成 Tᵀ=T⁻¹。','R_'+b+'W = R_W'+b+'ᵀ；只换朝向分量时才可直接乘 Rᵀ。'],
    inverse:['逆变换交换来源和目标，包含旋转逆与平移逆。平移不只是取负，还要先转回局部方向。','T_'+b+'W = inverse(T_W'+b+') = [Rᵀ, −Rᵀt; 0,0,0,1]'],
    column:['[x,y,z]ᵀ 是 3×1 列向量；ᵀ 在这里把横向书写转成竖向。矩阵乘法的内侧维度必须匹配。','(3×3) · (3×1) = (3×1)；齐次式为 (4×4) · (4×1)。'],
    units:['界面角度显示为 °；sin/cos、URDF rpy 和转动关节 q 使用 rad，移动关节 q 与位置使用 m。旋转矩阵元素无量纲，平移列为 m。','θ_rad = θ_deg × π/180；90° = π/2 rad；1000 mm = 1 m。']
  };
  $('notationMeaning').textContent=names[key]+'：'+descriptions[key][0];
  $('notationFormula').textContent=descriptions[key][1];
  let numbers=$('notationNumbers');
  if(!numbers){numbers=document.createElement('pre');numbers.id='notationNumbers';numbers.className='formula';numbers.setAttribute('aria-label','所选符号的当前数值及验算');$('notationFormula').after(numbers)}
  numbers.textContent=NotationGuide.numeric(key,d);
  numbers.classList.toggle('notation-focus',key==='transpose'||key==='inverse');
  $('notationContext').textContent=id==='rotation'?'本区把白色箭头的端点写成换系公式：局部点加物体中心 t。上方 Rp 本身仍是旋转后的向量，箭头起点在物体中心。':'这里直接使用上方 W → B → G 坐标链；G 是工具局部系，两个中间 B 下标相接后相消。';
  $('matrix').classList.toggle('notation-focus',['R','T','column'].includes(key));
  $('controlUnits').classList.toggle('notation-focus',key==='units');
}
function drawNotationGuide(id,s){
  if(id!=='rotation'&&id!=='transform')return;
  const d=NotationGuide.sample(id,s),R=PM.rot(d.H),o=PM.pos(d.H),p=G.point(d.H,d.p),key=NotationGuide.selected;
  const highlightFrame=()=>{[C.x,C.y,C.z].forEach((color,i)=>arrow(o,G.add(o,G.scale(R.map(row=>row[i]),.72)),color,3.5));dot(o,C.gold,4)};
  if(key==='R'||key==='T')highlightFrame();
  else if(key==='p')arrow(o,p,C.gold,4,'p_'+d.local+' 的空间箭头');
  else if(key==='world'){dot(p,C.gold,7);line([0,0,0],p,C.gold,2,true);label(p,'p_W',C.gold,9,18)}
  else if(key==='t')arrow([0,0,0],o,C.purple,4,'t_W'+d.local);
  else if(key==='transpose'){highlightFrame();arrow(o,p,C.gold,4,'待回算的位移 p_W−t')}
  else if(key==='inverse'){highlightFrame();dot(p,C.gold,7);label(p,'p_W ↔ p_'+d.local+' · 同一点',C.gold,8,18)}
}

// Small deterministic exercises; their parameters never change the lesson controls.
const LearningPracticeMath = {
  questions(id){
    const axes=[[1,0,0],[0,1,0],[0,0,1]],directions=[axes[0],axes[1],axes[2],[-1,0,0],[0,-1,0],[0,0,-1]];
    if(id==='rotation')return [
      {name:'绕 Y 正转',axis:axes[1],angle:90,input:axes[2],kind:'direction',choices:[directions[2],directions[3],directions[0],directions[4]]},
      {name:'绕 X 正转',axis:axes[0],angle:90,input:axes[1],kind:'direction',choices:[directions[2],directions[1],directions[5],directions[0]]},
      {name:'绕 Z 正转',axis:axes[2],angle:90,input:axes[0],kind:'direction',choices:[directions[4],directions[0],directions[5],directions[1]]},
      {name:'绕 Y 负转',axis:axes[1],angle:-90,input:axes[2],kind:'direction',choices:[directions[0],directions[3],directions[2],directions[5]]}
    ];
    if(id==='transform')return ['point','direction'].map(kind=>({
      name:kind==='point'?'一个点换系':'一个方向换系',axis:axes[2],angle:90,input:[.4,.2,.1],translation:[.6,-.3,.4],kind,
      choices:kind==='point'?[[-.2,.4,.1],[.4,.1,.5],[1,-.1,.5],[.2,-.7,.5]]:[[-.2,.4,.1],[.4,.1,.5],[.4,.2,.1],[.2,-.4,.1]]
    }));
    return [];
  },
  sample(q,u=1){
    u=Math.max(0,Math.min(1,u));
    const R=G.rod(q.axis,G.rad(q.angle*u)),translation=q.translation||[0,0,0];
    return {R,result:G.add(G.mv(R,q.input),G.scale(translation,q.kind==='point'?u:0)),translation:G.scale(translation,u)};
  },
  answer(q){
    const result=this.sample(q).result;
    return q.choices.findIndex(choice=>G.norm(G.sub(choice,result))<1e-9);
  },
  feedback(q,choice){
    const d=this.sample(q),translation=q.translation||[0,0,0],rotated=G.mv(d.R,q.input);
    const contribution=q.kind==='point'?translation:[0,0,0],selected=q.choices[choice];
    const near=v=>selected&&G.norm(G.sub(selected,v))<1e-9;
    const candidates=[['unrotated',G.add(q.input,contribution)],
      ['reversed',G.add(G.mv(G.rod(q.axis,G.rad(-q.angle)),q.input),contribution)]];
    if(q.translation&&G.norm(translation)>1e-9)candidates.push(q.kind==='point'?['missing_translation',rotated]:['extra_translation',G.add(rotated,translation)]);
    const matches=candidates.filter(([,value])=>near(value)).map(([code])=>code),correct=!!near(d.result);
    return {correct,code:correct?'correct':matches.length===1?matches[0]:'decompose',matches,rotated,contribution,result:d.result};
  }
};
let learningPractice={id:null,index:0,choice:null,revealed:false,progress:0,playing:false,raf:0,lastTime:0,revision:0};
let learningPracticeDOMRevision=-1;
function stopLearningPractice(){
  cancelAnimationFrame(learningPractice.raf);learningPractice.raf=0;learningPractice.playing=false;
}
function resetLearningPractice(index=learningPractice.index){
  stopLearningPractice();Object.assign(learningPractice,{index,choice:null,revealed:false,progress:0});learningPractice.revision++;
}
function learningPracticeQuestion(){return LearningPracticeMath.questions(learningPractice.id)[learningPractice.index]}
function learningPracticeReason(q,choice){
  const d=LearningPracticeMath.feedback(q,choice);
  const reasons={
    correct:'计算符合题设。'+(q.translation?'先旋转，再按点 / 方向决定平移贡献。':'旋转方向符合右手定则。'),
    missing_translation:'该选项的数值等于 R p_B：只包含旋转项。点的齐次分量是 1，还要加 t。',
    extra_translation:'该选项的数值等于 R d_B + t。方向的齐次分量是 0，平移贡献应为 0·t，不能直接加 t。',
    unrotated:'该选项的数值等于'+(q.kind==='point'?'原坐标加 t':'原输入向量')+'，没有应用题设的旋转。请先算 R'+(q.kind==='point'?'p_B':q.translation?'d_B':'v')+'。',
    reversed:'该选项的数值等于把旋转角改成 '+(-q.angle)+'° 后的结果'+(q.kind==='point'?'（再加 t）':'')+'。请核对题设的正负号；正角遵循右手定则。',
    decompose:'仅凭这个选项不能唯一确定出错步骤。请按下方的旋转项与平移贡献重新计算。'
  };
  return reasons[d.code];
}
function learningPracticeFormula(q){
  const d=LearningPracticeMath.sample(q),axis=['X','Y','Z'][q.axis.findIndex(x=>x===1)];
  const matrix=d.R.map(row=>'[ '+row.map(n=>fmt(n,0)).join('  ')+' ]').join('\n');
  const rotated=G.mv(d.R,q.input),contribution=q.kind==='point'?(q.translation||[0,0,0]):[0,0,0];
  return 'R'+axis.toLowerCase()+'('+q.angle+'°) =\n'+matrix+'\n\n'+
    (q.translation?'T_WB = [R, t; 0, 1]，t = '+vec(q.translation,1)+' m\n'+
      (q.kind==='point'?'[p_W; 1] = T_WB [p_B; 1]\nR p_B = '+vec(rotated,3)+' m\n平移贡献 = 1·t = '+vec(contribution,3)+' m\np_W = R p_B + 1·t':
        '[d_W; 0] = T_WB [d_B; 0]\nR d_B = '+vec(rotated,3)+'\n平移贡献 = 0·t = '+vec(contribution,3)+'\nd_W = R d_B + 0·t'):
      'v′ = R v')+'\n= '+vec(d.result,3)+(q.kind==='point'?' m':'')+'\n\n右手拇指沿 +'+axis+'，四指弯曲为正转；负角反向。';
}
function renderLearningPractice(id){
  const root=$('learningPractice');if(!root)return;
  if(id!==learningPractice.id){learningPractice.id=id;resetLearningPractice(0)}
  const questions=LearningPracticeMath.questions(id);root.classList.toggle('hidden',!questions.length);
  if(!questions.length)return;
  const q=learningPracticeQuestion(),s=learningPractice;
  if(learningPracticeDOMRevision!==s.revision){
    learningPracticeDOMRevision=s.revision;
    const symbol=q.kind==='point'?'p_B':q.translation?'d_B':'v',axis=['X','Y','Z'][q.axis.findIndex(x=>x===1)];
    root.innerHTML='<h3>先预测，再揭晓 · '+(s.index+1)+' / '+questions.length+'</h3>'+
      '<p>右手系、列向量。练习使用下方独立参数，不修改上方实验。'+(q.translation?'点位置和平移用 m；方向坐标不带长度单位。':'这里是主动旋转；坐标系保持不动。')+'</p>'+
      '<p><strong>'+esc(q.name)+'</strong>：'+esc(symbol)+' = '+esc(vec(q.input,1))+'；绕 +'+axis+' 轴转 '+q.angle+'°'+
      (q.translation?'，t = '+esc(vec(q.translation,1))+'。求 '+(q.kind==='point'?'p_W':'d_W')+'。':'，结果指向哪里？')+'</p>'+
      '<div class="foundation-steps" id="practiceChoices" aria-label="选择预测答案">'+q.choices.map((choice,i)=>
        '<button type="button" data-choice="'+i+'" aria-pressed="'+(s.choice===i)+'" '+(s.revealed?'disabled':'')+'>'+String.fromCharCode(65+i)+' · '+esc(vec(choice,1))+'</button>').join('')+'</div>'+
      '<div class="presets"><button type="button" class="primary" id="practiceReveal" '+(s.choice===null||s.revealed?'disabled':'')+'>揭晓并验算</button>'+
      '<button type="button" id="practiceReset">本题重答</button><button type="button" id="practiceNext">下一题 →</button></div>'+
      '<div id="practiceFeedback" aria-live="polite">'+(s.revealed?
        (s.choice===LearningPracticeMath.answer(q)?'预测正确。':'这次预测需要调整。')+' 你的选择：'+String.fromCharCode(65+s.choice)+'；正确答案：'+String.fromCharCode(65+LearningPracticeMath.answer(q))+' · '+esc(vec(LearningPracticeMath.sample(q).result,3))+'<p id="practiceReason">'+esc(learningPracticeReason(q,s.choice))+'</p>':'先选择一个答案，再揭晓；未作答时不会展示结果。')+'</div>'+
      (s.revealed?'<pre class="formula">'+esc(learningPracticeFormula(q))+'</pre><div class="control"><label for="practiceProgress">练习动画进度 <output id="practiceProgressValue"></output></label><input type="range" id="practiceProgress" min="0" max="1" step="0.01" value="'+s.progress+'"></div>'+
        '<div class="presets"><button type="button" id="practicePlay">▶ 播放练习</button></div><canvas id="practiceCanvas" role="img" aria-label="独立练习三维示意：初始向量、当前结果和固定世界坐标轴" style="display:block;width:100%;height:250px;max-width:100%;touch-action:pan-y"></canvas>'+
        '<p>虚线：初始'+(q.kind==='point'?'位置':'方向')+'；实线：当前'+(q.kind==='point'?'位置':'方向')+'。拖动进度可逐步检查。'+(q.translation?'这是从单位变换到题设变换的教学插值，不是机器人的执行轨迹。':'正转遵循右手定则。')+'</p>':'');
    $('practiceChoices').onclick=event=>{
      const button=event.target.closest('button[data-choice]');if(!button||s.revealed)return;
      const focused=document.activeElement===button;
      s.choice=Number(button.dataset.choice);s.revision++;renderLearningPractice(id);
      if(focused)$('practiceChoices').querySelector('[data-choice="'+s.choice+'"]').focus({preventScroll:true});
    };
    $('practiceReveal').onclick=()=>{
      if(s.choice===null)return;
      const focused=document.activeElement===$('practiceReveal');
      s.revealed=true;s.revision++;renderLearningPractice(id);
      if(focused)$('practiceProgress').focus({preventScroll:true});
    };
    $('practiceReset').onclick=()=>{
      const focused=document.activeElement===$('practiceReset');
      resetLearningPractice();renderLearningPractice(id);
      if(focused)$('practiceChoices').querySelector('button').focus({preventScroll:true});
    };
    $('practiceNext').onclick=()=>{
      const focused=document.activeElement===$('practiceNext');
      resetLearningPractice((s.index+1)%questions.length);renderLearningPractice(id);
      if(focused)$('practiceChoices').querySelector('button').focus({preventScroll:true});
    };
    if(s.revealed){
      pairVisualControls($('practiceCanvas'),$('practiceProgress').closest('.control'),$('practicePlay').closest('.presets'));
      $('practiceProgress').oninput=event=>{stopLearningPractice();s.progress=Number(event.target.value);paintLearningPractice()};
      $('practicePlay').onclick=()=>{
        if(s.playing){stopLearningPractice();paintLearningPractice();return}
        if(s.progress>=1)s.progress=0;
        if(window.matchMedia('(prefers-reduced-motion: reduce)').matches){s.progress=1;paintLearningPractice();return}
        s.playing=true;s.lastTime=0;s.raf=requestAnimationFrame(advanceLearningPractice);paintLearningPractice();
      };
    }
  }
  if(s.revealed)paintLearningPractice();
}
function advanceLearningPractice(now){
  const s=learningPractice;if(!s.playing)return;
  if(current===LESSONS.length||LESSONS[current].id!==s.id){stopLearningPractice();return}
  const dt=s.lastTime?Math.min((now-s.lastTime)/1000,.05):0;s.lastTime=now;s.progress=Math.min(1,s.progress+dt*.4);
  if(s.progress>=1)stopLearningPractice();paintLearningPractice();
  if(s.playing)s.raf=requestAnimationFrame(advanceLearningPractice);
}
function paintLearningPractice(){
  const canvas=$('practiceCanvas');if(!canvas)return;
  const s=learningPractice,q=learningPracticeQuestion(),d=LearningPracticeMath.sample(q,s.progress),g=canvas.getContext('2d');
  $('practiceProgress').value=s.progress;$('practiceProgressValue').textContent=Math.round(s.progress*100)+'%';
  $('practicePlay').textContent=s.playing?'⏸ 暂停练习':s.progress>=1?'↻ 重播练习':'▶ 播放练习';
  const w=canvas.clientWidth,h=250;if(!w)return;const ratio=Math.min(window.devicePixelRatio||1,2);
  if(canvas.width!==Math.round(w*ratio)||canvas.height!==h*ratio){canvas.width=Math.round(w*ratio);canvas.height=h*ratio}
  g.setTransform(ratio,0,0,ratio,0,0);g.clearRect(0,0,w,h);g.font='12px Consolas,"Microsoft YaHei",sans-serif';
  const yaw=-.9,pitch=.5,k=Math.min(w/3.1,h/2.25),center=[.15,0,.4];
  const project=p=>{const a=G.sub(p,center);return [w*.5+k*G.dot(a,[-Math.sin(yaw),Math.cos(yaw),0]),h*.55-k*G.dot(a,[-Math.sin(pitch)*Math.cos(yaw),-Math.sin(pitch)*Math.sin(yaw),Math.cos(pitch)])]};
  const arrow=(a,b,color,text,dashed=false)=>{
    a=project(a);b=project(b);g.strokeStyle=color;g.fillStyle=color;g.lineWidth=2;g.setLineDash(dashed?[4,4]:[]);
    g.beginPath();g.moveTo(...a);g.lineTo(...b);g.stroke();g.setLineDash([]);
    if(Math.hypot(b[0]-a[0],b[1]-a[1])>4){const angle=Math.atan2(b[1]-a[1],b[0]-a[0]);g.beginPath();g.moveTo(b[0]-7*Math.cos(angle-.4),b[1]-7*Math.sin(angle-.4));g.lineTo(...b);g.lineTo(b[0]-7*Math.cos(angle+.4),b[1]-7*Math.sin(angle+.4));g.stroke()}
    if(text){const x=Math.max(4,Math.min(w-g.measureText(text).width-4,b[0]+6)),y=Math.max(16,Math.min(h-8,b[1]-5));g.fillText(text,x,y)}
  };
  [[.62,0,0],[0,.62,0],[0,0,.62]].forEach((v,i)=>arrow([0,0,0],v,[C.x,C.y,C.z][i],['W·X','W·Y','W·Z'][i]));
  arrow([0,0,0],q.input,C.dim,'',true);
  if(q.translation)arrow([0,0,0],d.translation,C.purple,'t(u)',true);
  let previous=q.input;for(let i=1;i<=36;i++){const p=LearningPracticeMath.sample(q,s.progress*i/36).result,a=project(previous),b=project(p);g.strokeStyle=C.gold;g.lineWidth=1;g.beginPath();g.moveTo(...a);g.lineTo(...b);g.stroke();previous=p}
  arrow([0,0,0],d.result,C.gold,q.kind==='point'?'p(u)':'d(u)');
  if(q.kind==='point'){const p=project(d.result);g.fillStyle=C.gold;g.beginPath();g.arc(...p,4,0,Math.PI*2);g.fill()}
  g.fillStyle=C.white;g.fillText((q.kind==='point'?'p(u)':'d(u)')+' = '+vec(d.result,2),8,h-10);
}

// Screen-space annotation placement only; never changes a 3D point or axis.
const CanvasLabelLayout={
  place(items,width,height,reserved=[]){
    const placed=[],seen=new Set();let hidden=0,duplicates=0,offscreen=0;
    const hits=(a,b)=>a.x<b.x+b.w+2&&a.x+a.w+2>b.x&&a.y<b.y+b.h+2&&a.y+a.h+2>b.y;
    const sorted=items.map((item,index)=>({...item,index})).sort((a,b)=>(b.priority||0)-(a.priority||0)||(a.text<b.text?-1:a.text>b.text?1:a.index-b.index));
    for(const item of sorted){
      if(!Number.isFinite(item.x)||!Number.isFinite(item.y)||item.x<0||item.x>width||item.y<0||item.y>height){offscreen++;continue}
      const key=item.text+'|'+Math.round(item.x*2)+'|'+Math.round(item.y*2);
      if(seen.has(key)){duplicates++;continue}seen.add(key);
      const w=item.w+6,h=18,offsets=[[item.dx??5,item.dy??-7]];
      for(const y of [-7,17,-27,37,-47,57,-67,77])offsets.push([6,y],[-w-6,y]);
      let box=null;
      if(w<=width-8&&height>=106)for(const [dx,dy]of offsets){
        const candidate={x:Math.max(4,Math.min(width-w-4,item.x+dx-3)),y:Math.max(40,Math.min(height-h-48,item.y+dy-13)),w,h};
        if(!placed.some(p=>hits(candidate,p.box))&&!reserved.some(r=>hits(candidate,r))){box=candidate;break}
      }
      if(!box){hidden++;continue}
      const end=[Math.max(box.x,Math.min(box.x+box.w,item.x)),Math.max(box.y,Math.min(box.y+box.h,item.y))];
      placed.push({...item,x:box.x+3,y:box.y+13,box,anchor:[item.x,item.y],leader:Math.hypot(end[0]-item.x,end[1]-item.y)>10?end:null});
    }
    return {placed,hidden,duplicates,offscreen};
  }
};

// Pure teaching math. No DOM, renderer, simulator, or project entrypoint calls.
const ExtraMath = (() => {
  const rot = T => T.slice(0, 3).map(row => row.slice(0, 3));
  const pos = T => T.slice(0, 3).map(row => row[3]);
  function relative(T0, T1, mode = 'world') {
    if (mode === 'world') return G.mm(T1, ProjectMath.inverseAffine(T0));
    if (mode === 'body') return G.mm(ProjectMath.inverseAffine(T0), T1);
    throw Error('relative mode must be world or body');
  }
  function adjointTwist(T, v, w) {
    const R = rot(T), rotatedW = G.mv(R, w);
    return {v:G.add(G.mv(R, v), G.cross(pos(T), rotatedW)), w:rotatedW};
  }
  function covariance(R, scales) {
    const diagonal = scales.map((sigma, i) => scales.map((_, j) => i === j ? sigma*sigma : 0));
    return G.mm(G.mm(R, diagonal), G.transpose(R));
  }
  function jacobian(q, link = 'tool0', eps = 1e-5) {
    if (!Number.isFinite(eps) || eps <= 0) throw Error('Jacobian eps must be positive and finite');
    const reference = ProjectMath.fk(q)[link];
    if (!reference) throw Error('Unknown Jacobian link: ' + link);
    const Rtranspose = G.transpose(rot(reference));
    const columns = Object.keys(PD.robot.q_ref).map(name => {
      const angle = q[name] ?? 0;
      if (!Number.isFinite(angle)) throw Error('Nonfinite joint angle: ' + name);
      const plus = ProjectMath.fk({...q, [name]:angle+eps})[link];
      const minus = ProjectMath.fk({...q, [name]:angle-eps})[link];
      const v = G.scale(G.sub(pos(plus), pos(minus)), 1/(2*eps));
      const dR = rot(plus).map((row, i) => row.map((value, j) => (value-minus[i][j])/(2*eps)));
      const W = G.mm(dR, Rtranspose);
      const w = [(W[2][1]-W[1][2])/2, (W[0][2]-W[2][0])/2, (W[1][0]-W[0][1])/2];
      return [...v, ...w];
    });
    // World-expressed geometric Jacobian [p_dot; omega], NOT [v_spatial; omega].
    // The twist used by Ad_T has v_spatial = p_dot - omega cross p.
    return G.transpose(columns);
  }
  return {relative, adjointTwist, covariance, jacobian};
})();

// Additional teaching experiments: explicit separation from saved measured parameters.
const EXTRA_LESSONS=[
  {id:'delta',name:'进阶 · 世界/局部相对位姿',en:'RELATIVE POSE / LEFT vs RIGHT',title:'“从旧姿态到新姿态”，增量应该乘在哪？',sub:'取原包两个记录帧。世界增量左乘，局部增量右乘；两条路线应得到同一个新姿态。',controls:[slider('a','起始记录帧',0,252,1,93,''),slider('b','目标记录帧',0,252,1,172,''),select('mode','增量表达坐标',[['world','世界增量 · 左乘'],['body','旧工具系增量 · 右乘']],'world')],presets:[['开门起止',{a:93,b:172}],['没有变化',{a:132,b:132}]],note:'位姿来自真实记录；工具局部测试点 [0.04,0.02,0] m 是教学构造，不是选定的真实接触点。',theory:projectTheory('ΔT_world = T₁ inverse(T₀)　→　T₁ = ΔT_world T₀\nΔT_body = inverse(T₀) T₁　→　T₁ = T₀ ΔT_body\nΔt_world = t₁ − ΔR_world t₀ ≠ t₁ − t₀','旋转增量与平移增量要作为同一个刚体变换计算。简单相减只能得到两个原点的位移，不一定是世界左乘变换的平移列。','这里的 body 指旧工具坐标，不是世界系。不要把一个在世界表达的增量放到右侧。')},
  {id:'transfer',name:'进阶 · 抓取位姿迁移',en:'POSE TRANSFER / KEEP METRIC OFFSET',title:'换一个资产，为什么不能连手一起缩放？',sub:'复算真实 transfer_pose 逻辑。目标资产的大小和朝向可变，但工具到把手的米制偏置不缩放。',controls:[slider('ratio','新资产 / 原资产尺度',.6,1.5,.01,1.25,''),slider('yaw','新资产相对绕世界 Z',-90,90,1,25),slider('angle','两扇门的对应门角',0,60,1,35)],presets:[['同尺度对照',{ratio:1,yaw:25}],['放大资产',{ratio:1.5}],['闭门阶段',{angle:0}]],note:'源抓取参数来自原包；目标资产是交互构造的教学变体，不是原项目另一个已筛查成功的样例。',evidence:'synthetic',theory:projectTheory('T_rest = undo_hinge(T_source, −θ)\nΔR = R_asset_new R_asset_oldᵀ\np_rest_new = handle_new + ΔR(p_rest − handle_old)\nR_rest_new = ΔR R_rest\nT_new = apply_new_hinge(T_rest_new, θ)','先取消原资产开门角，迁移闭门把手系中的工具偏置，再按新资产的门轴恢复相同门角。源函数注释明确：never scale the hand。','目标资产的 pivot / handle 会随资产尺度改变，但工具的米制尺寸和偏置不乘 new_scale/old_scale。几何迁移不保证 IK 或物理成功。')},
  {id:'covariance',name:'进阶 · Gaussian 椭球',en:'GAUSSIAN / COVARIANCE ROTATION',title:'中心动了，Gaussian 椭球的朝向也要动。',sub:'用明确标注的教学 σ 构造各向异性 Gaussian，观察刚体旋转前后的协方差。',controls:[slider('sx','局部 σx',.03,.3,.005,.22,' m'),slider('sy','局部 σy',.03,.3,.005,.09,' m'),slider('sz','局部 σz',.03,.3,.005,.05,' m'),slider('yaw','绕世界 Z',-180,180,1,45),slider('pitch','绕世界 Y',-90,90,1,30),select('ghost','参考椭球',[['yes','叠加未旋转的椭球'],['no','只看旋转后']],'yes')],presets:[['各向同性',{sx:.12,sy:.12,sz:.12}],['细长 Gaussian',{sx:.25,sy:.06,sz:.035}],['无旋转',{yaw:0,pitch:0}]],note:'σ、椭球、颜色都是教学参数；真实 binding.npz 没有提供这些量。曲线是 1σ 等值面截线，不表示实体碰撞边界。',evidence:'synthetic',theory:projectTheory('Σ_local = diag(σx², σy², σz²)\nΣ_world = R Σ_local Rᵀ\n(p−μ)ᵀ inverse(Σ_world) (p−μ) = 1\n刚体旋转：trace(Σ)、det(Σ)、σ 均不变','刚体运动更新中心 μ 和椭球朝向，不改变局部主轴尺度。平移不进入协方差；一般仿射缩放才用 AΣAᵀ。','画面不是实测 Gaussian。各向同性时旋转不改变椭球形状，但旋转矩阵仍然变化；不要用协方差当完整碰撞证书。')},
  {id:'jacobian',name:'进阶 · URDF 几何雅可比',en:'GEOMETRIC JACOBIAN / DIFFERENTIAL FK',title:'一个关节微动，TCP 会往哪走？',sub:'对真实 URDF 的 FK 做中央差分；比较 J·Δq 的一阶预测和重新计算的 FK。不是 IK 求解器。',controls:[select('pose','起始姿态',[['home','记录 home'],['open','记录开门终点']],'home'),select('joint','施加增量的关节',armNames.map((n,i)=>[String(i),n]),'0'),slider('dq','关节增量 Δq',-.2,.2,.001,.04,' rad'),slider('wrist2','额外 wrist_2 扰动',-70,70,1,0)],presets:[['小增量',{dq:.01}],['较大增量',{dq:.2}],['清零增量',{dq:0}]],note:'J 输出 [TCP 原点线速度; 世界角速度]。它不是 twist 中的 [v;ω]；有限差分不提供碰撞、限位或可解性保证。',theory:projectTheory('Jp[:,i] ≈ (p(q+εei)−p(q−εei))/(2ε)\nJω[:,i] = vee((∂R/∂qi)Rᵀ)\n[Δp; Δφ_world] ≈ J(q) Δq\n转动关节解析列：[a×(p_TCP−o); a]','雅可比是局部线性近似。Δq 变大时，线性预测与非线性 FK 的位置差通常增大；J 本身不能判断运动是否无碰撞。','这里线性部分是 ṗ_TCP，不是 spatial twist 的 v_s=ṗ_TCP−ω×p_TCP。不能直接把这个六维向量套进 Ad_T。')},
  {id:'twist',name:'进阶 · 速度的坐标变换',en:'SE(3) ADJOINT / TWIST',title:'变换速度时，为什么不能只旋转两个三维向量？',sub:'用教学刚体 twist [v;ω] 演示 Ad_T。平移会通过叉乘耦合进线性分量。',controls:[slider('yaw','B 系绕世界 Z',-180,180,1,35),slider('tx','B 原点世界 X',-.6,.6,.01,.3,' m'),slider('ty','B 原点世界 Y',-.6,.6,.01,.3,' m'),slider('tz','B 原点世界 Z',-.6,.6,.01,.2,' m'),slider('speed','v_B 的局部 X 分量',-.3,.3,.01,.1,' m/s'),slider('omega','ω_B 的局部 Z 分量',-2,2,.05,1,' rad/s')],presets:[['纯平移 twist',{omega:0}],['纯转动 twist',{speed:0,omega:1}],['两系同原点',{tx:0,ty:0,tz:0}]],note:'本页 v 是 twist 平移部分，不是任意空间点的线速度。箭头表示该测试点速度×1秒的位移示意，不是执行轨迹。',evidence:'synthetic',theory:projectTheory('ξ = [v;ω]，ξ̂_s = Ṫ inverse(T)\nξ_W = Ad_TWB ξ_B\nω_W = Rω_B　　v_W = Rv_B + t×Rω_B\nu_W(p) = v_W + ω_W×p\nu_W(Tp_B) = R(v_B + ω_B×p_B)','换参考原点后，刚体速度场中的 twist 平移部分会改变。真正的物理点速度要在该点位置求 v+ω×p，不能把 v_W 当成每个点的速度。','几何雅可比页给 ṗ_TCP；本页给 twist。排列采用 [v;ω]，不是一些库使用的 [ω;v]。')},
  {id:'cameraaxes',name:'进阶 · CV / GL 相机轴',en:'CAMERA BASIS vs MATRIX STORAGE',title:'翻转相机轴，和转置矩阵不是同一件事。',sub:'真实 camera_front 的 CV/GL 坐标系叠加。一个世界点在 CV 前方时，在 GL 中 Z 通常为负。',controls:[slider('x','测试点相机 CV X',-.5,.5,.01,.1,' m'),slider('y','测试点相机 CV Y',-.5,.5,.01,.08,' m'),slider('z','测试点相机 CV Z',-.5,1.5,.01,.6,' m'),select('layout','查看矩阵',[['cv','CV world → camera'],['gl','GL world → camera'],['stored','Legacy GS：view.T 存储']],'cv')],presets:[['光轴上的前方点',{x:0,y:0,z:.6}],['相机身后点',{z:-.3}]],note:'相机 K/view 来自原包；测试点是教学输入。矩阵列主序序列化、存储转置和几何坐标轴翻转需分清。',theory:projectTheory('D = diag(1,−1,−1,1)\np_CV = view p_W\np_GL = D p_CV　　view_GL = D view\nLegacy GS stored = viewᵀ（存储布局）\nC_world = inverse(view)[:3,3]','CV 是右、下、前；GL 是右、上、后。D 是一次真实的坐标基变换；把矩阵按列主序展开只是内存序列化，不会自动完成这次翻轴。','不要把外参的平移列当成相机位置。旧 GS 从 inverse(stored)[3,:3] 取相机中心，是因为它存的是转置后的 view。')}
];
PROJECT_LESSONS.push(...EXTRA_LESSONS);LESSONS.push(...EXTRA_LESSONS);
function extraEllipsoid(mu,R,sigma,color){
  for(const [i,j] of [[0,1],[0,2],[1,2]]){let previous;for(let k=0;k<=72;k++){const a=k*Math.PI/36,v=[0,0,0];v[i]=sigma[i]*Math.cos(a);v[j]=sigma[j]*Math.sin(a);const p=G.add(mu,G.mv(R,v));if(previous)line(previous,p,color,1.5);previous=p}}
}
