async function loadMujocoModel(sample,xml,files={},label='本地 MJCF',request=++MJLab.request){
  if(request!==MJLab.request)return;
  stopPlay();MJLab.pending=true;MJLab.error='';$('mjStatus').textContent='正在初始化本地引擎 / 编译模型…';$('mjError').textContent='';
  let session;
  try{
    session=await MJEngine.load(xml,files,label);
    const renderer=MJLab.renderer||await MJRenderer.ready($('mujocoCanvas'));
    if(request!==MJLab.request){session.dispose();return}
    mjInitialPose(session,sample);
    session.smoothCadNormals=sample==='ur5e'||sample==='tianyi';
    session.tianyiAppearance=sample==='tianyi';
    renderer.setModel(session);MJLab.session?.dispose();
    Object.assign(MJLab,{session,renderer,sample,raw:xml,label,pending:false,accumulator:0,sourceKey:''});
    $('mjSample').querySelector('[value=import]').disabled=sample!=='import';$('mjSample').value=sample;MJLab.lastJoint=null;mjSyncModelControls();
  }catch(error){session?.dispose();if(request===MJLab.request){MJLab.pending=false;MJLab.error='加载失败，保留上一模型：'+error.message;$('mjError').textContent=MJLab.error;if(LESSONS[current]?.id==='mujoco')render()}}
}
function mjInitialPose(session,sample){
  if(sample==='arm'){session.setJoint(0,.4);session.setJoint(1,-.6);session.setControl(0,.4);session.setControl(1,-.6)}
  if(sample==='ur5e'){session.module.mj_resetDataKeyframe(session.model,session.data,0);session.forward()}
}
async function loadMujocoSample(sample){
  const request=++MJLab.request;
  if(sample==='arm')return loadMujocoModel('arm',MJ_ARM_XML,{},'教学 2R 机械臂＋自由落球（教学构造）',request);
  stopPlay();MJLab.pending=true;MJLab.error='';$('mjStatus').textContent='正在解包本地真实模型与资源…';
  try{
    let data;
    if(typeof LAB_WEB_ASSETS!=='undefined')data=await loadWebModel(sample);
    else{
    data=MJ_OVEN_DATA;
    if(sample==='ur5e'){
      if(!mjRobotPayload)mjRobotPayload=(async()=>{const bytes=Uint8Array.from(atob(MJ_ROBOT_GZIP),c=>c.charCodeAt(0));return new Response(new Blob([bytes]).stream().pipeThrough(new DecompressionStream('gzip'))).json()})().catch(error=>{mjRobotPayload=undefined;throw error});
      data=await mjRobotPayload;
    }
    if(sample==='tianyi'){
      if(!mjTianyiPayload)mjTianyiPayload=(async()=>{const bytes=Uint8Array.from(atob(MJ_TIANYI_GZIP),c=>c.charCodeAt(0));return new Response(new Blob([bytes]).stream().pipeThrough(new DecompressionStream('gzip'))).json()})().catch(error=>{mjTianyiPayload=undefined;throw error});
      data=await mjTianyiPayload;
    }
    }
    if(request!==MJLab.request)return;
    const files=Object.fromEntries(Object.entries(data.files).map(([p,b])=>[p,Uint8Array.from(atob(b),c=>c.charCodeAt(0))]));
    if(sample==='ur5e')MJLab.robotData=data;
    return loadMujocoModel(sample,data.xml,files,data.label,request);
  }catch(error){if(request===MJLab.request){MJLab.pending=false;MJLab.error='本地模型解包失败：'+error.message;$('mjError').textContent=MJLab.error}}
}
