function animateMujocoLab(id,dt){
  if(id!=='mujoco')return false;
  if(!MJLab.session||MJLab.pending){stopPlay();return true}
  const session=MJLab.session;MJLab.accumulator+=dt*state.speed;const timestep=session.model.opt.timestep,count=Math.min(100,Math.floor(MJLab.accumulator/timestep));
  if(count){try{session.step(count);MJLab.accumulator-=count*timestep;if(+state.joint>=0){state.q=session.data.qpos[session.model.jnt_qposadr[+state.joint]];MJLab.lastQ=state.q}}catch(e){stopPlay();MJLab.error='仿真已暂停：'+e.message}}
  return true;
}
function resetMujocoExperiment(){if(!MJLab.session)return;const s=MJLab.session;s.reset();mjInitialPose(s,MJLab.sample);MJLab.accumulator=0;MJLab.sourceKey=''}
async function importMujocoFiles(files){
  if(!files.length)return;stopPlay();const request=++MJLab.request;MJLab.pending=true;MJLab.error='';$('mjStatus').textContent='正在读取本地模型与资源…';$('mjError').textContent='';
  try{
    let total=0;const paths=files.map(f=>f.webkitRelativePath||f.name);
    const xmls=paths.filter(p=>/\.xml$/i.test(p));if(!xmls.length)throw Error('没有 XML 文件');
    const common=files[0].webkitRelativePath?paths[0].split('/')[0]+'/':'';
    const relative=paths.map(p=>common&&p.startsWith(common)?p.slice(common.length):p),assets={};
    if(files.length>1000)throw Error('最多 1000 个文件');
    for(let i=0;i<files.length;i++){total+=files[i].size;if(total>64*1024*1024)throw Error('模型资源合计不能超过 64 MiB');if(Object.hasOwn(assets,relative[i]))throw Error('文件名冲突，请改用选择文件夹');const bytes=await files[i].arrayBuffer();if(request!==MJLab.request)return;assets[relative[i]]=new Uint8Array(bytes)}
    const entries=[];for(const p of relative.filter(p=>/\.xml$/i.test(p))){const xml=new TextDecoder().decode(assets[p]);if(new DOMParser().parseFromString(xml,'application/xml').documentElement?.tagName==='mujoco')entries.push(p)}
    if(!entries.length)throw Error('没有以 <mujoco> 为根的 MJCF');
    MJLab.imported={assets,entries};$('mjEntry').innerHTML=entries.map(p=>'<option value="'+esc(p)+'">'+esc(p)+'</option>').join('');$('mjEntry').classList.remove('hidden');$('mjLoadEntry').classList.remove('hidden');
    const entry=entries.includes('model.xml')?'model.xml':entries[0];$('mjEntry').value=entry;await mjLoadImportedEntry(request);
  }catch(error){if(request===MJLab.request){MJLab.pending=false;MJLab.error='导入失败，保留上一模型：'+error.message;$('mjError').textContent=MJLab.error;if(LESSONS[current]?.id==='mujoco')render()}}
}
function mjLoadImportedEntry(request){
  const entry=$('mjEntry').value,all=MJLab.imported.assets,dir=entry.includes('/')?entry.slice(0,entry.lastIndexOf('/')+1):'',files={};
  // Only the selected entry's subtree is exposed; ../ dependencies are intentionally not resolved.
  for(const [path,bytes]of Object.entries(all))if(path.startsWith(dir))files[path.slice(dir.length)]=bytes;
  return loadMujocoModel('import',new TextDecoder().decode(all[entry]),files,'本地 · '+entry,request);
}
$('mjSample').addEventListener('change',e=>{if(e.target.value!=='import')loadMujocoSample(e.target.value)});
$('mjLoad').addEventListener('click',()=>loadMujocoSample($('mjSample').value==='import'?'ur5e':$('mjSample').value));
$('mjFiles').addEventListener('change',async e=>{await importMujocoFiles([...e.target.files]);e.target.value=''});
$('mjFolder').addEventListener('change',async e=>{await importMujocoFiles([...e.target.files]);e.target.value=''});
$('mjLoadEntry').addEventListener('click',()=>mjLoadImportedEntry());
$('mjForward').addEventListener('click',()=>{stopPlay();MJLab.session?.forward();render()});
$('mjStep').addEventListener('click',()=>{stopPlay();if(!MJLab.session||MJLab.pending)return;try{MJLab.session.step();if(+state.joint>=0){state.q=MJLab.session.data.qpos[MJLab.session.model.jnt_qposadr[+state.joint]];MJLab.lastQ=state.q}render()}catch(error){MJLab.error='已暂停：'+error.message;render()}});

// Conceptual hardware lessons only: no device access or Tianyi pin assignments.
const HardwareMath={
  encoder(count,zero,cpr,gear,sign,bias=0){
    if(![count,zero,cpr,gear,sign,bias].every(Number.isFinite)||cpr<=0||gear<=0||![-1,1].includes(sign))throw Error('计数分辨率、减速比或方向无效');
    return sign*2*Math.PI*(count-zero)/(cpr*gear)+bias;
  },
  endpoint(q,length=.55){return [length*Math.cos(q),length*Math.sin(q),.32]}
};
