  const q=HardwareMath.encoder(s.count,s.zero,4096,Number(s.gear),Number(s.sign),G.rad(s.bias)),ref=G.rad(s.target),o=[0,0,.32],p=HardwareMath.endpoint(q),target=HardwareMath.endpoint(ref),R=G.rz(q);
  line([0,0,0],o,C.dim,5);circle(o,[1,0,0],[0,1,0],.55,'#405575',true);
