const BasicGuideMath={
  rotation(axis,angle){
    const i={x:0,y:1,z:2}[axis],a=[0,0,0],v=[0,0,0];a[i]=1;v[(i+1)%3]=1;
    const R=G.rod(a,G.rad(angle));return {axis:a,input:v,R,result:G.mv(R,v)};
  },
  point(){
    const R=G.rz(Math.PI/2),t=[1,0,0],world=[1,1,0],local=G.mv(G.transpose(R),G.sub(world,t));
    return {R,t,world,local,H:G.T(R,t),rotated:G.mv(R,local)};
  }
};
