function basicFrame(p,R,size,name,world=false,skipAxis=-1){
  for(let i=0;i<3;i++){
    if(i===skipAxis)continue;
    const end=G.add(p,G.scale(R.map(r=>r[i]),size)),color=world?'#7a91ad':[C.x,C.y,C.z][i];
    line(p,end,color,world?1.5:3,world);drawList.push({kind:'arrow',points:[p,end],color,w:world?1.5:3});
    label(end,['X','Y','Z'][i]+'_'+name,color,6,-8);
  }
  dot(p,world?C.dim:C.gold,4);
}
