function basicAlignedAxis(axis){return sceneOrientationBasis(view.yaw,view.pitch).eye[{x:0,y:1,z:2}[axis]]}
function basicGuideRotationMatrix(axis,angle,R){
  const m=MN;
  return mathEquation(m.row(m.call(m.sub(m.i('R'),m.i(axis)),m.row(m.n(angle),m.o('°'))),m.o('='),m.matrix(R.map(row=>row.map(x=>m.n(Number(fmt(x,5))))))),'三列依次对应原X、Y、Z基方向旋转后的世界分量。');
}
function basicGuideEquation(id,step,d){
  const m=MN,r=m.row,i=m.i,o=m.o,n=x=>m.n(Number(fmt(x,5))),V=v=>m.matrix(v.map(x=>[n(x)])),S=(a,b)=>m.sub(i(a),i(b));
  if(id==='rotation'){
    const angle=step<2?0:BasicWalkthrough.angle,R=m.call(S('R','WB'),r(m.n(angle),o('°')));
    return mathEquation(r(S('p','W'),o('='),R,S('p','B'),o('='),V(d.result)),'P贴在B上，R的列是B三轴在W中的方向。两系原点重合：无需平移。拖动视角不改变p_B或p_W。')+(step===3?basicGuideRotationMatrix(BasicWalkthrough.axis,angle,d.R):'');
  }
  return mathEquation(r(S('p','W'),o('='),S('R','WB'),S('p','B'),o('+'),S('t','WB'),...(step===3?[o('='),V(d.rotated),o('+'),V(d.t)]:[]),o('='),V(d.world)),'当前选点不移动：R把B的分量换成W方向，再补B原点的位置。')+mathEquation(r(S('p','B'),o('='),m.T(S('R','WB')),o('('),S('p','W'),o('−'),S('t','WB'),o(')'),o('='),V(d.local)),'逆向先减平移，再撤销旋转；仅对合法旋转矩阵用转置作逆。');
}
function basicGuideCode(id){
  const b=BasicWalkthrough;
  if(id==='rotation'){
    const axis=b.axis,matrices={x:'[[1, 0, 0], [0, c, -s], [0, s, c]]',y:'[[c, 0, s], [0, 1, 0], [-s, 0, c]]',z:'[[c, -s, 0], [s, c, 0], [0, 0, 1]]'},d=BasicGuideMath.rotation(axis,b.angle);
    return 'import numpy as np\n\n# 同步当前单轴教学状态；不是完整实验的roll/pitch/yaw。\nangle_deg = '+b.angle+'\ntheta = np.deg2rad(angle_deg)  # 三角函数接收rad\nc, s = np.cos(theta), np.sin(theta)\nR = np.array('+matrices[axis]+', dtype=float)\np_B = np.array('+JSON.stringify(d.input)+', dtype=float)\n# R: (3,3)；v: (3,)；@是矩阵乘，不是逐元素乘。\np_W = R @ p_B\n# P固定在B上，R将局部分量映射到W；两系原点重合，无平移。\nnp.testing.assert_allclose(p_W, '+JSON.stringify(d.result)+', atol=1e-12, rtol=0)\nprint("p_W:", p_W)\nprint("R shape:", R.shape, "v shape:", p_W.shape)\n';
  }
  const d=transformSampleValues();
  return 'import numpy as np\n\n# R_WB把B的分量换成W方向；列依次为B的X/Y/Z轴。\nR_WB = np.array('+JSON.stringify(d.R)+')\nt_WB = np.array([1., 0., 0.])  # B原点在W中的位置，m\np_B = np.array('+JSON.stringify(d.local)+')   # 当前选点在B中的分量，m\nrotated = R_WB @ p_B          # 位移换成W方向，还不是最终位置\np_W = rotated + t_WB          # 补上原点，得到点的位置\np_B_back = R_WB.T @ (p_W - t_WB)  # 先减平移，再乘旋转逆\nnp.testing.assert_allclose(p_W, '+JSON.stringify(d.world)+', atol=1e-12, rtol=0)\nnp.testing.assert_allclose(p_B_back, p_B, atol=1e-12, rtol=0)\nprint("rotated / m:", rotated)\nprint("p_W / m:", p_W)\nprint("p_B_back / m:", p_B_back)\n# 仅对合法旋转矩阵有R^{-1}=R.T；一般矩阵不能这样求逆。\n';
}
function basicGuideCodeHTML(id){
  return '<details id="basicGuideCode" '+(BasicWalkthrough.codeOpen[id]?'open':'')+'><summary>把这张图的数值写成NumPy，再反算核对</summary><p>数学向量写成列；这里NumPy用shape (3,)的一维数组。保留坐标系后缀、单位和乘法顺序，@会返回同样shape的向量。只需NumPy，浏览器不执行Python。</p><pre class="research-code" tabindex="0">'+esc(basicGuideCode(id))+'</pre><button type="button" id="basicGuideCopy">复制这一步代码</button><p class="research-note">与库对应：<a href="https://github.com/NxRLab/ModernRobotics/blob/master/packages/Python/modern_robotics/core.py" target="_blank" rel="noopener">Modern Robotics的RpToTrans / TransInv</a>把R和p组织成齐次变换，并用旋转转置及平移补偿求逆。本段是自行编写的固定例子，不依赖该库；执行断言才算核对了数值。</p></details>';
}
