  if(!focused)stopBasicRotation();
  const compact=active&&supported;
  if(compact&&b.compactId!==l.id){b.readerWasOpen=$('robotBasics').open;$('robotBasics').open=false;}
  if(!compact&&b.compact)$('robotBasics').open=b.readerWasOpen;
  b.compact=compact;b.compactId=compact?l.id:null;document.body.classList.toggle('rotation-sample',compact&&l.id==='rotation');document.body.classList.toggle('transform-sample',compact&&l.id==='transform');
  rotationPrerequisites.hidden=!compact;
  if(compact){if($('courseContext').parentElement!==rotationPrerequisites)rotationPrerequisites.append($('courseContext'),$('lessonOutline'));}
