  if(compact){if($('spaceExperiment').nextElementSibling!==$('courseReader'))$('courseReader').before($('basicWalkthrough'),$('spaceExperiment'));}
  else if(!['interpolation','quintic'].includes(l.id)){if($('spaceExperiment').previousSibling!==basicExperimentHome)basicExperimentHome.after($('spaceExperiment'));if($('basicWalkthrough').previousElementSibling!==$('rigidMathIntro'))$('rigidMathIntro').after($('basicWalkthrough'));}
  $('lab').classList.toggle('basic-focus',focused);$('basicRotationFocus').classList.toggle('hidden',!focused);
  if(!focused)$('basicRotationFocus').innerHTML='';
  $('walkthroughSide').classList.toggle('hidden',!active);
  const transform=active&&l.id==='transform',practice=transform&&productPractice(),reveal=!practice||ProductLearning.check?.passed===true,transformWhyContent=$('transformWhyContent');
  $('transformWhy').classList.toggle('hidden',!transform||!reveal);
