// Pure math uses the same column-vector convention as the existing lessons.
const RigidMath={
  finiteMatrix(A,n){return Array.isArray(A)&&A.length===n&&A.every(r=>Array.isArray(r)&&r.length===n&&r.every(Number.isFinite))},
  rotationCheck(A){
    if(!this.finiteMatrix(A,3))return {valid:false,error:Infinity,det:NaN};
    const error=G.orthoError(A),det=G.det(A);return {valid:error<1e-9&&Math.abs(det-1)<1e-9,error,det};
  },
  poseCheck(T){return this.finiteMatrix(T,4)&&T[3].every((x,i)=>Math.abs(x-(i===3?1:0))<1e-9)&&this.rotationCheck(T.slice(0,3).map(r=>r.slice(0,3))).valid},
  pose(angle,tx){
    const R=G.rz(G.rad(angle)),t=[tx,0,0],p=[1,0,0],T=G.T(R,t);
    return {R,t,T,inverse:G.inverse(T),point:G.point(T,p),direction:G.mv(R,p)};
  },
  factors(u,v,reflection){
    const U=G.mm(G.rz(G.rad(u)),[[1,0,0],[0,1,0],[0,0,reflection?-1:1]]),Vt=G.transpose(G.ry(G.rad(v))),S=[[1.6,0,0],[0,.7,0],[0,0,.4]];
    const A=G.mm(G.mm(U,S),Vt),naive=G.mm(U,Vt),D=[[1,0,0],[0,1,0],[0,0,G.det(naive)<0?-1:1]],Q=G.mm(G.mm(U,D),Vt);
    const stages=[G.I(),Vt,G.mm(S,Vt),A],distance=Math.hypot(...A.flatMap((r,i)=>r.map((x,j)=>x-Q[i][j])));
    return {U,Vt,S,A,Q,naive,D,stages,distance};
  }
};

// Optional lesson UI. Constructed factors illustrate SVD, not a general SVD solver.
const RigidMathLab={topic:0,angle:30,tx:1,kind:'rotation',u:30,v:-25,reflection:false,stage:0,key:''};
const RIGID_TOPICS=['SO(3) · 只旋转','SE(3) · 再加平移','SVD · 拆成三步','SVD · 拟合旋转'];
LESSONS.push({id:'rigidmath',name:'数学 · SO / SE / SVD',en:'OPTIONAL MATH / SO(3) / SE(3) / SVD',title:'旋转、位姿和 SVD，不是同一种东西。',sub:'可选数学入口。先观察一次变化，再展开公式；灰色是输入，彩色是当前结果。教学构造，不改原项目配准。',controls:[],presets:[],theory:'',note:''});
$('rigidMathIntro').innerHTML='<p>不用先背定义。按 1 → 4 看，每一步只解决一个问题；基础引导和完整实验均保留。</p><div class="rigid-topics">'+RIGID_TOPICS.map((x,i)=>'<button type="button" data-rigid-topic="'+i+'">'+(i+1)+' · '+x+'</button>').join('')+'</div>';
$('rigidMathPanel').innerHTML='<div id="rigidQuestions" class="rigid-questions"></div><div id="rigidControls" class="rigid-controls"></div><div id="rigidNumbers" class="rigid-numbers" aria-live="polite"></div><details id="rigidMathDetails"><summary>再看公式、矩阵和 Python 对照</summary><div id="rigidFormula"></div><div id="rigidMatrices" class="rigid-matrices"></div><pre id="rigidPython"></pre><p id="rigidBoundary" class="caution"></p><p class="rigid-references">核对资料：<a href="https://modernrobotics.northwestern.edu/nu-gm-book-resource/3-2-1-rotation-matrices-part-1-of-2/" target="_blank" rel="noopener">Modern Robotics · SO(3)</a> · <a href="https://modernrobotics.northwestern.edu/nu-gm-book-resource/3-3-1-homogeneous-transformation-matrices/" target="_blank" rel="noopener">SE(3)</a> · <a href="https://numpy.org/doc/stable/reference/generated/numpy.linalg.svd.html" target="_blank" rel="noopener">NumPy SVD</a> · <a href="https://nvlpubs.nist.gov/nistpubs/jres/124/jres.124.028.pdf" target="_blank" rel="noopener">NIST · proper rotation</a>。链接仅在点击时联网，演示本身离线。</p></details>';
