function rigidMatrix(name,M){return '<div><p class="mono">'+name+'</p><div class="matrix"><table aria-label="'+name+'">'+M.map(r=>'<tr>'+r.map(x=>'<td>'+fmt(x,2)+'</td>').join('')+'</tr>').join('')+'</table></div></div>'}
