function openMathLearning(id='matmul',trigger=document.activeElement){initMathLearning();MathLearning.trigger=trigger;selectMathTopic(id);if(!$('mathLearning').open)$('mathLearning').showModal()}
function selectMathTopic(id){MathLearning.topic=id;MathLearning.step=0;MathLearning.line=0;MathLearning.answer=false;MathLearning.tab='intuition';renderMathLearning();$('mathLearning').scrollTop=0}
function mathRecordRows(r){const labels={dot:'点积 a·b',norm_a:'向量长度 ||a||',projection:'投影向量',shape:'一维数组shape',column_shape:'列数组shape',transpose_shape:'一维.T后的shape',A:'矩阵A',x:'未知或输入x',y:'输出y',by_columns:'按列组合的结果',row_terms:'逐行乘积项（还没求和）',elementwise:'逐元素乘积 A*x',RS_p:'先S后R的结果',SR_p:'先R后S的结果',transpose:'A.T',inverse:'A⁻¹',transpose_inverse_error:'||A.T−A⁻¹||',orthogonality_error:'||R.T@R−I||',determinant:'行列式det(A)',perturbed_b:'仅扰动后的b',perturbed_x:'扰动后的解',unique:'基准解是否唯一',coefficient:'最优系数x',fitted:'拟合值A@x',residual:'残差actual−target',orthogonality:'a·残差',loss:'½残差平方和',singular_values:'奇异值',rank:'按当前规则的秩',condition:'2-范数条件数',rank_tolerance:'数值秩容差',reconstruction_error:'构造/重建误差',J:'Jacobian，m/rad',dq_rad:'δq，rad',actual:'实际f(q+δq)，m',linear:'一阶预测，m',linear_error_m:'预测误差，m',gradient:'损失对q的梯度',finite_difference:'中心差分梯度',next_loss:'本例小步更新后的损失',covariance:'协方差，m²',eigenvalues:'特征值=主轴方差，m²',principal_std_m:'主轴标准差，m',symmetry_error:'对称误差',eigen_equation_error:'构造/特征方程误差'};
if('quadratic' in r)labels.eigenvalues='对称A的特征值（无量纲）';
if('epsilon' in r)labels.J='归一化教学映射 J（无量纲）';
return Object.entries(r).map(([k,v])=>[labels[k]||MATRIX_LABELS[k]||k,v===null?(k==='condition'?'∞':'无唯一精确解'):Array.isArray(v)&&Array.isArray(v[0])?v.map(researchValue).join('；'):researchValue(v)]);}
function mathCurrentSummary(id,r){
  const v=researchValue;
  return {vectors:()=> 'a·b='+v(r.dot)+'；||a||='+v(r.norm_a)+'；投影='+v(r.projection),matmul:()=> 'x='+v(r.x)+' → A@x='+v(r.y),compose:()=> '先S后R：'+v(r.RS_p)+'；先R后S：'+v(r.SR_p),solve:()=>r.unique?'基准解='+v(r.x)+'；仅扰动0.001后的解='+v(r.perturbed_x):'ε=0：基准方程无穷多解；扰动后的精确方程不一致。',lstsq:()=> '最优x='+v(r.coefficient)+'；残差='+v(r.residual)+'；a·残差='+v(r.orthogonality),svd:()=> '奇异值='+v(r.singular_values)+'；数值秩='+r.rank+'；κ₂='+(r.condition===null?'∞':v(r.condition)),jacobian:()=> 'δq='+v(r.dq_rad)+' rad；一阶预测误差='+v(r.linear_error_m*1000)+' mm；梯度='+v(r.gradient),covariance:()=> '主轴方差='+v(r.eigenvalues)+' m²；主轴标准差='+v(r.principal_std_m)+' m'}[id]();
}
