function mathSimpleTable(rows){return '<div class="math-table-wrap"><table class="math-result"><tbody>'+rows.map(r=>'<tr>'+r.map(x=>'<td>'+esc(String(x))+'</td>').join('')+'</tr>').join('')+'</tbody></table></div>'}
function mathResultTable(r){return mathSimpleTable(mathRecordRows(r))}
function showMathLine(i){
  MathLearning.line=i;const line=MathLearning.code().split('\n')[i].trim();
  const rules=[['import ','导入当前独立代码需要的库；np是NumPy别名，不是一个数学变量。'],['def ','定义可调用函数。函数体由缩进决定，定义本身不等于已经执行。'],['check_value(','校验输入范围与有限性；避免NaN或无穷值让后续结论失去意义。'],['value =','把当前控件值写成明确的Python输入；后续代码都以这个数计算。'],['a =','建立向量a；核对各分量顺序、单位和shape。'],['A =','建立矩阵或组合映射；按本主题说明核对行列和顺序。'],['x =','建立输入或解变量；此处名字的含义由本主题规定。'],['b =','建立目标、方向或方程右端；不要仅凭同名就跨例子复用。'],['J =','Jacobian：输出为行、参数为列；这里shape为(2,1)。'],['residual =','定义actual−target残差；符号约定会影响梯度，平方损失仍需保持一致。'],['gradient =','J.T@residual应用链式法则，把损失敏感性传回参数。'],['coefficient,','lstsq返回系数、残差统计、秩、奇异值；这里下划线表示未使用的返回值。'],['U, singular','NumPy实际计算SVD，Vt已经是转置后的右奇异向量矩阵。'],['eigenvalues,','对称矩阵用eigh；特征向量按列存储，默认特征值递增，后面显式重排。'],['inverse =','用solve解A@X=I得到逆；若只求一个x，应直接solve(A,b)。'],['result =','组织可核对的输出；把数值数组转成可写JSON的列表，不代表改变数学含义。'],['print(','输出当前计算结果；ensure_ascii=False保留中文，禁止NaN写入标准JSON。']];
  const explanation=(MatrixAnalysisMath.has(MathLearning.topic)?MATRIX_CODE_HINTS.find(([prefix])=>line.startsWith(prefix))?.[1]:null)||rules.find(([p])=>line.startsWith(p))?.[1]||(!line?'空行用于分段，没有计算。':line.startsWith('#')?'注释说明假设或读法，不执行。':'沿本主题推导核对这行的输入、运算和输出；@是矩阵乘法，*是逐元素乘法，单位也必须一致。');
  $('mathLineHelp').textContent='第'+(i+1)+'行：'+explanation;
  $('mathCodeLines').querySelectorAll('button').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.mathLine)===i)));
}
function mathDiagram(id,r,value){
  if(MatrixAnalysisMath.has(id))return matrixDiagram(id,r,value);
  const scale=({vectors:65,matmul:25,compose:50,lstsq:35,svd:105,covariance:105,jacobian:300})[id]||42,center=id==='jacobian'?r.p:[0,0];
  const project=p=>[205+scale*(p[0]-center[0]),160-scale*(p[1]-center[1])],point=(p,color)=>'<circle cx="'+project(p)[0]+'" cy="'+project(p)[1]+'" r="4" fill="'+color+'"/>',poly=(pts,color)=>'<polyline points="'+pts.map(p=>project(p).join(',')).join(' ')+'" fill="none" stroke="'+color+'" stroke-width="2.5"/>';
  const line=(a,b,color,dash=false)=>{const p=project(a),q=project(b),dx=q[0]-p[0],dy=q[1]-p[1],length=Math.hypot(dx,dy),tip=Math.min(8,length/2),u=length?dx/length:0,v=length?dy/length:0,points=[q,[q[0]-tip*u+tip*.4*v,q[1]-tip*v-tip*.4*u],[q[0]-tip*u-tip*.4*v,q[1]-tip*v+tip*.4*u]];return '<path d="M'+p.join(' ')+' L'+q.join(' ')+'" fill="none" stroke="'+color+'" stroke-width="2.5"'+(dash?' stroke-dasharray="5 4"':'')+'/><polygon points="'+points.map(x=>x.join(',')).join(' ')+'" fill="'+color+'"/>'};
  const gold='#ffbc70',blue='#87adff',green='#8ae1bb',purple='#c6a5ff';let body='',legend='';
  if(id==='vectors'){body=line([0,0],r.a,gold)+line([0,0],r.b,blue)+line([0,0],r.projection,green)+line(r.a,r.projection,'#91a1b7',true);legend='橙a · 蓝单位方向b · 绿投影 · 虚线为剩余分量'}
  if(id==='matmul'){const A=r.A;for(let i=-2;i<=2;i++){body+=poly([MathBasics.mv(A,[i,-2]),MathBasics.mv(A,[i,2])],'#32455f')+poly([MathBasics.mv(A,[-2,i]),MathBasics.mv(A,[2,i])],'#32455f')}body+=line([0,0],[2,0],blue)+line([0,0],[1,1],green)+line([0,0],r.y,gold);legend='蓝A第一列 · 绿A第二列 · 橙y=A@x · 网格随A变换'}
  if(id==='compose'){body=line([0,0],r.p,'#91a1b7')+line([0,0],r.RS_p,gold)+line([0,0],r.SR_p,blue);legend='灰输入p · 橙先S后R · 蓝先R后S'}
  if(id==='solve'){const x1=[-3,5],x2=[5,-3],eps=value;body=poly([x1,x2],blue)+poly([[-3,(5+eps)/(1+eps)],[5,(-3+eps)/(1+eps)]],gold);if(r.x)body+=point(r.x,green);if(r.perturbed_x)body+=point(r.perturbed_x,purple);legend='蓝/橙两条约束 · 绿基准解 · 紫扰动解；超出图幅请看数值'}
  if(id==='lstsq'){body=line([-2,-4],[2,4],'#52647e')+line([0,0],r.b,gold)+line([0,0],r.fitted,green)+line(r.b,r.fitted,blue,true);legend='灰可产生的直线 · 橙目标b · 绿拟合 · 蓝残差方向'}
  if(id==='svd'||id==='covariance'){const samples=Array.from({length:121},(_,i)=>[Math.cos(i*2*Math.PI/120),Math.sin(i*2*Math.PI/120)]);body=poly(samples,'#52647e');const A=id==='svd'?r.A:MathBasics.mm(MathBasics.rot(value),[[1,0],[0,.3]]);body+=poly(samples.map(p=>MathBasics.mv(A,p)),gold);legend=id==='svd'?'灰单位圆 · 橙A作用后的图形；最小奇异值为0时压成线':'灰单位圆 · 橙协方差主轴椭圆；不表示95%概率范围'}
  if(id==='jacobian'){const arc=Array.from({length:81},(_,i)=>{const a=(20+i*60/80)*Math.PI/180;return [Math.cos(a),Math.sin(a)]});body=poly(arc,'#52647e')+point(r.p,blue)+line(r.p,r.linear,gold)+point(r.linear,gold)+point(r.actual,green)+line(r.linear,r.actual,purple,true);legend='蓝当前点 · 橙切线预测 · 绿实际圆弧终点 · 紫近似误差'}
  return '<svg viewBox="0 0 410 345" role="img" aria-label="'+esc(legend)+'"><defs><clipPath id="mathPlotClip"><rect x="12" y="12" width="386" height="285"/></clipPath></defs><rect width="410" height="345" rx="10" fill="#101b2a"/><g clip-path="url(#mathPlotClip)"><path d="M12 160H398 M205 12V297" stroke="#52647e"/>'+body+'</g><text x="375" y="150" fill="#b6c6da">'+(id==='jacobian'?'ΔX':'X')+'</text><text x="215" y="28" fill="#b6c6da">'+(id==='jacobian'?'ΔY':'Y')+'</text><text x="12" y="320" fill="#b6c6da" font-size="11">等比例二维图 · 1数值单位='+scale+'图内单位</text></svg><p class="math-caption">'+esc(legend)+(id==='jacobian'?'；图以当前点为增量原点，ΔX/ΔY仍沿原XY方向。':'')+'</p>';
}

// Small position-only 2R optimizer. Independent from URDF/SciPy and original data.
const OptimMath={
  methods:['gd','gn','dls'],
  config(x={}){const c={...OPTIM_DATA.default_settings,...x};for(const [k,lo,hi]of [['eta',.05,2],['damping',0,.5],['noise_bound_mm',0,2]])if(typeof c[k]!=='number'||!Number.isFinite(c[k])||c[k]<lo||c[k]>hi)throw Error('无效参数：'+k);return c},
  dot(a,b){return a.reduce((s,v,i)=>s+v*b[i],0)},
  fk(q){if(!Array.isArray(q)||q.length!==2||!q.every(Number.isFinite))throw Error('q需为两个有限rad');const [a,b]=q,[L1,L2]=OPTIM_DATA.fixed.lengths_m;return {p:[L1*Math.cos(a)+L2*Math.cos(a+b),L1*Math.sin(a)+L2*Math.sin(a+b)],J:[[-L1*Math.sin(a)-L2*Math.sin(a+b),-L2*Math.sin(a+b)],[L1*Math.cos(a)+L2*Math.cos(a+b),L2*Math.cos(a+b)]]}},
  cases(config){let state=OPTIM_DATA.fixed.noise_seed;return OPTIM_DATA.baseline.cases.map(c=>{const noise=Array.from({length:2},()=>{state=(Math.imul(1664525,state)+1013904223)>>>0;return (2*state/4294967296-1)*config.noise_bound_mm/1000});return {id:c.id,name:c.name,kind:c.kind,clean_target_m:[...c.clean_target_m],noise_m:noise,observed_target_m:c.clean_target_m.map((x,i)=>x+noise[i])}})},
  spectrum(J){const h00=J[0][0]**2+J[1][0]**2,h11=J[0][1]**2+J[1][1]**2,h01=J[0][0]*J[0][1]+J[1][0]*J[1][1],a=.5*Math.atan2(2*h01,h00-h11),vectors=[[Math.cos(a),Math.sin(a)],[-Math.sin(a),Math.cos(a)]],images=vectors.map(v=>J.map(row=>this.dot(row,v))),singular=images.map(v=>Math.hypot(...v));return {vectors,images,singular}},
  direction(J,r,method,c){
    if(!this.methods.includes(method))throw Error('未知方法');
    const gradient=[J[0][0]*r[0]+J[1][0]*r[1],J[0][1]*r[0]+J[1][1]*r[1]],s=this.spectrum(J);
    if(method==='gd')return gradient.map(v=>-c.eta*v);
    const lam=method==='dls'?c.damping:0,step=[0,0];
    for(let k=0;k<2;k++){if(lam===0&&s.singular[k]<=s.singular[0]*OPTIM_DATA.fixed.rank_rcond)continue;const coefficient=-this.dot(s.images[k],r)/(s.singular[k]**2+lam**2);step.forEach((_,i)=>step[i]+=coefficient*s.vectors[k][i])}
    return step;
  },
  solve(caseIndex=0,seedIndex=0,method='dls',config={},keepTrace=true){
    const c=this.config(config),f=OPTIM_DATA.fixed;
    if(!Number.isInteger(caseIndex)||caseIndex<0||caseIndex>=8||!Number.isInteger(seedIndex)||seedIndex<0||seedIndex>=4||!this.methods.includes(method))throw Error('目标、初值或方法无效');
    const item=this.cases(c)[caseIndex],observed=item.observed_target_m,clean=item.clean_target_m,limit=f.limit_deg*Math.PI/180;
    let q=OPTIM_DATA.seeds_deg[seedIndex].map(v=>v*Math.PI/180),updates=0,evaluations=0,peak=0,status='budget',observedMM=0,cleanMM=0;const trace=[];
    for(let iteration=0;iteration<=f.max_updates;iteration++){
      const {p,J}=this.fk(q);evaluations++;
      const r=p.map((v,i)=>v-observed[i]),cost=.5*this.dot(r,r),gradient=[J[0][0]*r[0]+J[1][0]*r[1],J[0][1]*r[0]+J[1][1]*r[1]];
      observedMM=Math.hypot(...r)*1000;cleanMM=Math.hypot(...p.map((v,i)=>v-clean[i]))*1000;
      const row={iteration,q_rad:[...q],point_m:p,residual_m:r,jacobian:J,gradient,cost,observed_mm:observedMM,clean_mm:cleanMM,singular_values:this.spectrum(J).singular,raw_step_rad:[0,0],limited_step_rad:[0,0],accepted_step_rad:[0,0],backtracks:0};trace.push(row);
      if(observedMM<=f.fit_threshold_mm){status='fit';break}
      if(iteration===f.max_updates){status='budget';break}
      if(Math.max(...gradient.map(Math.abs))<=1e-12){status='stationary';break}
      const raw=this.direction(J,r,method,c),rawNorm=Math.max(...raw.map(Math.abs)),scale=Math.min(1,f.step_cap_rad/Math.max(rawNorm,1e-300)),limited=raw.map(v=>v*scale);peak=Math.max(peak,rawNorm);row.raw_step_rad=raw;row.limited_step_rad=limited;
      let accepted=false;
      for(let backtracks=0;backtracks<=f.max_backtracks;backtracks++){
        const trial=q.map((v,i)=>Math.max(-limit,Math.min(limit,v+2**(-backtracks)*limited[i]))),actualStep=trial.map((v,i)=>v-q[i]);
        if(Math.max(...actualStep.map(Math.abs))<1e-12)continue;
        const tp=this.fk(trial).p;evaluations++;const tr=tp.map((v,i)=>v-observed[i]),slope=this.dot(gradient,actualStep),trialCost=.5*this.dot(tr,tr);
        if(slope<0&&trialCost<=cost+f.armijo*slope){row.accepted_step_rad=actualStep;row.backtracks=backtracks;q=trial;updates++;accepted=true;break}
      }
      if(!accepted){status='line_search_failed';break}
    }
    const result={case_id:item.id,case_index:caseIndex,seed_index:seedIndex,method,kind:item.kind,q_rad:q,status,updates,fk_evaluations:evaluations,peak_raw_step_rad:peak,observed_mm:observedMM,clean_mm:cleanMM,clean_success:cleanMM<=f.fit_threshold_mm};if(keepTrace)result.trace=trace;return result;
  },
  batch(config={}){const c=this.config(config),records=[];for(const m of this.methods)for(let i=0;i<8;i++)for(let j=0;j<4;j++)records.push(this.solve(i,j,m,c,false));return {schema:'geometry-lab-position-optimization/v1',runtime:{backend:'browser',algorithm:'analytic-2R/JS'},settings:c,fixed:JSON.parse(JSON.stringify(OPTIM_DATA.fixed)),cases:this.cases(c),seeds_deg:OPTIM_DATA.seeds_deg,records,scope:'Synthetic position-only 2R; no orientation, full-path, collision, dynamics or real-robot validation.'}},
  summary(records){const median=a=>{const b=[...a].sort((x,y)=>x-y),n=b.length;return n%2?b[(n-1)/2]:(b[n/2-1]+b[n/2])/2};return this.methods.map(method=>{const r=records.filter(x=>x.method===method),known=r.filter(x=>x.kind==='constructed'),bins=[0,0,0,0,0,0],edges=[.1,.5,2,10,100];r.forEach(x=>{let i=edges.findIndex(v=>x.clean_mm<=v);bins[i<0?5:i]++});return {method,count:r.length,success:r.filter(x=>x.clean_success).length,known_count:known.length,known_success:known.filter(x=>x.clean_success).length,known_median_mm:median(known.map(x=>x.clean_mm)),median_updates:median(r.map(x=>x.updates)),mean_fk:r.reduce((s,x)=>s+x.fk_evaluations,0)/r.length,worst_mm:Math.max(...r.map(x=>x.clean_mm)),bins,stops:Object.fromEntries(['fit','budget','stationary','line_search_failed'].map(s=>[s,r.filter(x=>x.status===s).length]))}})}
};
function validateOptimBatch(x){
  const fail=message=>{throw Error(message)},near=(a,b,label)=>{if(typeof a!=='number'||!Number.isFinite(a)||Math.abs(a-b)>1e-6+Math.abs(b)*1e-8)fail(label+'与独立重算不一致')};
  if(x?.schema!=='geometry-lab-position-optimization/v1')fail('需要本模块的批量结果格式');
  if(!x.settings||['eta','damping','noise_bound_mm'].some(k=>typeof x.settings[k]!=='number'))fail('缺少完整实验参数');
  const c=OptimMath.config(x.settings),expectedCases=OptimMath.cases(c);
  if(!x.fixed||Object.keys(x.fixed).length!==Object.keys(OPTIM_DATA.fixed).length||Object.keys(OPTIM_DATA.fixed).some(k=>JSON.stringify(x.fixed[k])!==JSON.stringify(OPTIM_DATA.fixed[k]))||JSON.stringify(x.seeds_deg)!==JSON.stringify(OPTIM_DATA.seeds_deg))fail('固定评价、守护参数或初值集合不同，不能作为同一协议');
  if(!Array.isArray(x.cases)||x.cases.length!==8||!Array.isArray(x.records)||x.records.length!==96)fail('必须保留8目标×4初值×3方法的全部96条记录');
  x.cases.forEach((row,i)=>{const e=expectedCases[i];if(row.id!==e.id||row.kind!==e.kind)fail('目标编号/类型不同');for(const k of ['clean_target_m','observed_target_m','noise_m']){if(!Array.isArray(row[k])||row[k].length!==2)fail('目标shape错误');row[k].forEach((v,j)=>near(v,e[k][j],k))}});
  if(!x.runtime||typeof x.runtime.backend!=='string'||x.runtime.backend.length>100)fail('缺少运行环境声明');
  const seen=new Set();
  for(const r of x.records){
    if(!Number.isInteger(r.case_index)||r.case_index<0||r.case_index>=8||!Number.isInteger(r.seed_index)||r.seed_index<0||r.seed_index>=4||!OptimMath.methods.includes(r.method))fail('记录索引/方法错误');
    const key=[r.case_index,r.seed_index,r.method].join('/');if(seen.has(key))fail('记录重复，存在遗漏');seen.add(key);
    const item=expectedCases[r.case_index];if(r.case_id!==item.id||r.kind!==item.kind)fail('记录目标类型错误');
    const p=OptimMath.fk(r.q_rad).p;if(r.q_rad.some(v=>Math.abs(v)>OPTIM_DATA.fixed.limit_deg*Math.PI/180+1e-9))fail('q超出限位');
    const clean=Math.hypot(...p.map((v,i)=>v-item.clean_target_m[i]))*1000,observed=Math.hypot(...p.map((v,i)=>v-item.observed_target_m[i]))*1000;
    near(r.clean_mm,clean,'clean_mm');near(r.observed_mm,observed,'observed_mm');
    if(r.clean_success!==(clean<=.1)||!['fit','budget','stationary','line_search_failed'].includes(r.status)||(r.status==='fit')!==(observed<=.1))fail('停止状态/固定门槛布尔值不一致');
    if(!Number.isInteger(r.updates)||r.updates<0||r.updates>80||!Number.isInteger(r.fk_evaluations)||r.fk_evaluations<2*r.updates+1||r.fk_evaluations>1134||typeof r.peak_raw_step_rad!=='number'||!Number.isFinite(r.peak_raw_step_rad)||r.peak_raw_step_rad<0||r.status==='budget'&&r.updates!==80)fail('迭代/计数字段不合法');
  }
  return JSON.parse(JSON.stringify(x));
}

const OPTIM_METHOD_NAMES={gd:'梯度下降 GD',gn:'Gauss–Newton GN',dls:'固定阻尼 DLS'};
const OPTIM_STOP_NAMES={fit:'观测位置达标',budget:'用完80次更新预算',stationary:'梯度很小但残差未达标',line_search_failed:'回溯未找到可接受步'};
const OptimizationLab={ready:false,tab:'single',caseIndex:0,seedIndex:0,method:'dls',settings:{...OPTIM_DATA.default_settings},iteration:0,results:[],batch:null,imported:null,importStatus:'尚未导入。'};
function syncOptimizationLab(id){
  const panel=$('optimizationLab');panel.classList.toggle('hidden',!['ik','damping','singularity'].includes(id));
  if(!['ik','damping','singularity'].includes(id))panel.open=false;
  if(!panel.dataset.wired){panel.dataset.wired='yes';panel.addEventListener('toggle',()=>{if(panel.open)initOptimizationLab()})}
}
function openOptimizationLab(){if(!['ik','damping','singularity'].includes(GeometryLab.getState().lesson))GeometryLab.goTo('ik');initOptimizationLab();$('optimizationLab').open=true;$('optimizationLab').scrollIntoView({block:'start'})}
function initOptimizationLab(){if(OptimizationLab.ready)return;OptimizationLab.ready=true;recomputeOptimization()}
function recomputeOptimization(){const s=OptimizationLab;s.results=OptimMath.methods.map(m=>OptimMath.solve(s.caseIndex,s.seedIndex,m,s.settings));s.iteration=0;s.batch=null;renderOptimizationLab()}
function optimizationPython(){const s=OptimizationLab,defaults={method:s.method,case_index:s.caseIndex,seed_index:s.seedIndex,...s.settings};return OPTIM_DATA.python.replace(/^DEFAULTS = .*$/m,'DEFAULTS = '+JSON.stringify(defaults))}
function optimizationTable(headers,rows){return (headers.length>4?'<p class="optim-scroll-hint">宽表可横向滑动查看全部指标。</p>':'')+'<div class="optim-table-wrap"><table class="optim-table"><thead><tr>'+headers.map(x=>'<th>'+esc(String(x))+'</th>').join('')+'</tr></thead><tbody>'+rows.map(r=>'<tr>'+r.map(x=>'<td>'+esc(String(x))+'</td>').join('')+'</tr>').join('')+'</tbody></table></div>'}
function optimizationNumber(v){return researchNumber(v)}
function renderOptimizationLab(){
 const s=OptimizationLab,cases=OptimMath.cases(s.settings);
 $('optimizationBody').innerHTML='<p>位置2R教学模型，长度[1,0.6]m。只求末端XY，不包含朝向或原UR5e。三种方法共用±150°限位、最大单关节更新0.25rad、Armijo回溯（最多12次减半）、80次更新预算和0.1mm观测停止门槛。这里的优化迭代步不是轨迹相邻状态的步长。</p><div class="research-tabs">'+[['single','看一次迭代'],['theory','公式与手算'],['batch','批量对照与失败'],['code','自己运行与导入'],['analysis','实验观察与分析']].map(([k,n])=>'<button type="button" data-optim-tab="'+k+'" aria-pressed="'+(s.tab===k)+'">'+n+'</button>').join('')+'</div><div class="optim-controls"><label>目标 <select id="optimCase">'+cases.map((r,i)=>'<option value="'+i+'"'+(i===s.caseIndex?' selected':'')+'>'+r.name+'</option>').join('')+'</select></label><label>初值q / deg <select id="optimSeed">'+OPTIM_DATA.seeds_deg.map((r,i)=>'<option value="'+i+'"'+(i===s.seedIndex?' selected':'')+'>'+researchValue(r)+'</option>').join('')+'</select></label><label>逐步观察 <select id="optimMethod">'+Object.entries(OPTIM_METHOD_NAMES).map(([k,n])=>'<option value="'+k+'"'+(k===s.method?' selected':'')+'>'+n+'</option>').join('')+'</select></label>'+optimSlider('eta','仅GD的学习率η',.05,2,.05,s.settings.eta)+optimSlider('damping','仅DLS的λ',0,.5,.01,s.settings.damping)+'<label>教学噪声每轴上界 / mm <select id="optimNoise">'+[0,.5,1,2].map(v=>'<option value="'+v+'"'+(v===s.settings.noise_bound_mm?' selected':'')+'>'+v+'</option>').join('')+'</select></label></div><div id="optimizationContent"></div>';
 $('optimizationBody').querySelectorAll('[data-optim-tab]').forEach(b=>b.addEventListener('click',()=>{s.tab=b.dataset.optimTab;renderOptimizationLab();$('optimizationBody').querySelector('[data-optim-tab="'+s.tab+'"]').focus({preventScroll:true})}));
 $('optimCase').addEventListener('change',e=>{s.caseIndex=Number(e.target.value);recomputeOptimization()});
 $('optimSeed').addEventListener('change',e=>{s.seedIndex=Number(e.target.value);recomputeOptimization()});
 $('optimMethod').addEventListener('change',e=>{s.method=e.target.value;s.iteration=0;renderOptimizationLab()});
 $('optimNoise').addEventListener('change',e=>{s.settings.noise_bound_mm=Number(e.target.value);recomputeOptimization()});
 $('optimizationBody').querySelectorAll('[data-optim-param]').forEach(el=>{el.addEventListener('input',()=>{s.settings[el.dataset.optimParam]=Number(el.value);el.closest('label').querySelector('output').textContent=el.value});el.addEventListener('change',()=>{const id=el.id;recomputeOptimization();$(id).focus({preventScroll:true})})});
 if(s.tab==='analysis'){$('optimizationBody').querySelector('.optim-controls').classList.add('hidden');$('optimizationBody').querySelector('p').textContent='实验观察分析：固定DLS候选、调参A组与留出B组。先声明问题与评价规则，再观察结果和限制结论。';renderObservationAnalysis()}else if(s.tab==='single')renderOptimSingle();else if(s.tab==='theory')renderOptimTheory();else if(s.tab==='batch')renderOptimBatch();else renderOptimCode();
}
function optimSlider(key,label,min,max,step,value){return '<label>'+label+' <output>'+value+'</output><input id="optim-'+key+'" data-optim-param="'+key+'" type="range" min="'+min+'" max="'+max+'" step="'+step+'" value="'+value+'"></label>'}
function renderOptimSingle(){
 const s=OptimizationLab,result=s.results.find(x=>x.method===s.method),i=Math.min(s.iteration,result.trace.length-1),row=result.trace[i],item=OptimMath.cases(s.settings)[s.caseIndex];
 const content=$('optimizationContent'),controls=$('optimizationBody').querySelector('.optim-controls');
 if(content.contains(controls))content.before(controls);
 $('optimizationContent').innerHTML='<h4>同一问题，先比较三种方法</h4>'+optimizationTable(['方法','停止原因','更新次数','原始目标误差 mm','带噪目标误差 mm'],s.results.map(r=>[OPTIM_METHOD_NAMES[r.method],OPTIM_STOP_NAMES[r.status],r.updates,optimizationNumber(r.clean_mm),optimizationNumber(r.observed_mm)]))+'<p>原始目标：'+researchValue(item.clean_target_m)+'m；求解时看到的带噪目标：'+researchValue(item.observed_target_m)+'m。clean_success固定按原始目标误差≤0.1mm计算；与观测停止条件分开。</p><div class="research-actions"><button type="button" id="optimPrev">上一步</button><button type="button" id="optimNext">下一步</button><button type="button" id="optimExportSingle">导出当前方法完整迭代.json</button></div><label>查看状态 <output id="optimIterationLabel">'+i+' / '+(result.trace.length-1)+'</output><input id="optimIteration" type="range" min="0" max="'+(result.trace.length-1)+'" step="1" value="'+i+'"></label><div class="optim-figures">'+optimArmFigure(result,i,item)+optimLossFigure(s.results)+'</div><p id="optimStepMeaning">当前展示第'+i+'次更新前的状态。raw是公式提出的步，limited是共同步长上限处理后的步，accepted是回溯及限位处理后实际采取的步。最后状态没有下一步，步向量记0。</p>'+optimizationTable(['当前量','具体数值'],[['q / rad',researchValue(row.q_rad)],['J / m per rad',row.jacobian.map(researchValue).join('；')],['残差 actual−observed / m',researchValue(row.residual_m)],['梯度 J.T@r',researchValue(row.gradient)],['J的奇异值',researchValue(row.singular_values)],['raw步 / rad',researchValue(row.raw_step_rad)],['limited步 / rad',researchValue(row.limited_step_rad)],['accepted步 / rad',researchValue(row.accepted_step_rad)],['回溯减半次数',row.backtracks],['½残差平方和',optimizationNumber(row.cost)]])+'<p>损失曲线显示求解目标的误差范数，使用log10(mm+0.001)纵轴。误差下降不证明原始目标、姿态、碰撞或任务已经达标。</p>';
 const figures=content.querySelector('.optim-figures');
 pairVisualControls(figures,controls,$('optimIteration').closest('label'),$('optimPrev').closest('.research-actions'));
 $('optimPrev').disabled=i===0;$('optimNext').disabled=i===result.trace.length-1;
 const set=k=>{s.iteration=k;renderOptimSingle()};
 $('optimPrev').addEventListener('click',()=>set(Math.max(0,i-1)));$('optimNext').addEventListener('click',()=>set(Math.min(result.trace.length-1,i+1)));
 $('optimIteration').addEventListener('input',e=>{
   $('optimIterationLabel').textContent=e.target.value+' / '+(result.trace.length-1);
   figures.firstElementChild.outerHTML=optimArmFigure(result,Number(e.target.value),item);
 });
 $('optimIteration').addEventListener('change',e=>{set(Number(e.target.value));$('optimIteration').focus({preventScroll:true})});
 $('optimExportSingle').addEventListener('click',()=>researchDownload('optimization_trace.json',JSON.stringify({schema:'geometry-lab-position-trace/v1',runtime:{backend:'browser',reference_python_sha256:OPTIM_DATA.python_sha256},settings:s.settings,fixed:OPTIM_DATA.fixed,case:item,seed_deg:OPTIM_DATA.seeds_deg[s.seedIndex],result,scope:OPTIM_DATA.baseline.scope},null,2),'application/json;charset=utf-8'));
}
function renderOptimTheory(){
 const s=OptimizationLab,lam=s.settings.damping,J=[[1,0],[0,.01]],r=[.01,.01],gn=OptimMath.direction(J,r,'gn',s.settings),dls=OptimMath.direction(J,r,'dls',s.settings);
 $('optimizationContent').innerHTML='<h4>从残差走到三种更新</h4>'+mathOptimEquations()+'<p>Python使用增广最小二乘求更新，不显式求逆；网页用二维奇异方向的解析滤波计算。λ=0退回GN。这里λ固定，不是自适应Levenberg–Marquardt或SciPy trf。λ是本次更新的惩罚强度，与原项目旋转残差的0.1权重、0.1mm停止门槛不同。</p><h4>一组可手算的小奇异值反例</h4><p>设J=diag(1,0.01)，r=[0.01,0.01]。GN分别除以奇异值，第二方向会放大100倍。DLS缩小弱奇异方向的更新放大，当前固定λ='+lam+'。</p>'+optimizationTable(['量','GN','DLS'],[['未裁剪原始步 / rad',researchValue(gn),researchValue(dls)],['线性化后的残差 / m',researchValue([.01+gn[0],.01+.01*gn[1]]),researchValue([.01+dls[0],.01+.01*dls[1]])]])+'<p>这里显示未经共享步长上限处理的原始公式，便于手算。减小更新放大可能留下更多残差，不能只说“阻尼越大越好”。λ与J的尺度有关；混合位置/朝向时需先声明权重和单位。</p><button type="button" id="optimMathBefore">补读SVD与相关数学基础</button><h4>Armijo回溯是什么</h4>'+mathArmijoEquation()+'<p>本例关节角用rad、位置残差用m。η与λ都依赖变量尺度，换单位后不能直接照搬数值。</p><h4>共用守护为什么要讲清楚</h4><ol><li>先对原始步按最大分量统一缩放至≤0.25rad。</li><li>试步后夹到关节限位；用实际位移计算下降方向与Armijo条件。</li><li>不满足就减半，最多12次；失败要记录，不能静默当成功。</li><li>梯度小、预算耗尽、回溯失败都与0.1mm位置门槛分别报告。</li></ol><p>例：径向目标配完全伸直初值[0,0]时，梯度可以为0而位置仍差约200mm。固定阻尼也不能创造丢失的一阶方向；换初值或更合适的搜索策略需另做对照。</p>';
 $('optimMathBefore').addEventListener('click',()=>openMathLearning('svd',$('optimMathBefore')));
}
function renderOptimBatch(){
 const s=OptimizationLab;if(!s.batch)s.batch=OptimMath.batch(s.settings);
 const summaries=OptimMath.summary(s.batch.records);
 s.batch.runtime.reference_python_sha256=OPTIM_DATA.python_sha256;
 $('optimizationContent').innerHTML='<h4>固定8个目标 × 4个初值 × 3种方法</h4><p>每种方法32条记录。其中6个由限位内q的FK构造，共24个配对情景；另外2个目标各4初值有半径/关节限位不可达证据，仍保留在全部记录中。构造可达指无噪声原始目标；加噪后的观测目标仍可能不可达。各方法看到相同的每目标噪声，不按方法重抽样。</p>'+optimizationTable(['方法','全部达标 / 32','构造可达组达标 / 24','构造可达组中位误差 mm','更新次数中位数','平均FK评估次数'],summaries.map(r=>[OPTIM_METHOD_NAMES[r.method],r.success+'/32',r.known_success+'/24',optimizationNumber(r.known_median_mm),r.median_updates,optimizationNumber(r.mean_fk)]))+optimHistogram(summaries)+optimizationTable(['停止原因','GD','GN','DLS'],Object.keys(OPTIM_STOP_NAMES).map(k=>[OPTIM_STOP_NAMES[k],...summaries.map(r=>r.stops[k])]))+'<p>固定门槛：原始目标误差≤0.1mm。误差分箱对全部32条记录使用同一组边界；FK评估次数统计工作量，不等于跨硬件速度排名。8目标的4个初值彼此相关，不把96条结果当96个独立随机样本计算置信区间。</p><p>教学噪声为每轴[-上界,+上界)的均匀扰动，固定LCG种子17；上界不是标准差。λ、η、噪声上界可分别改变，比较时声明变化了哪些因素。有限小目标集不能证明普遍最优。</p><div class="research-actions"><button type="button" id="optimExportBatch">导出全部96条对照.json</button><button type="button" id="optimExportCSV">导出逐条指标.csv</button></div><details><summary>查看全部结果和失败原因，点击一条回到迭代</summary><div class="optim-run-list">'+s.batch.records.map((r,i)=>'<button type="button" data-optim-run="'+i+'">'+OPTIM_METHOD_NAMES[r.method]+' · '+r.case_id+' · 初值'+r.seed_index+' · '+optimizationNumber(r.clean_mm)+'mm · '+OPTIM_STOP_NAMES[r.status]+'</button>').join('')+'</div></details>';
 pairVisualControls($('optimizationContent').querySelector('.optim-histogram'),$('optimizationBody').querySelector('.optim-controls'));
 $('optimExportBatch').addEventListener('click',()=>researchDownload('optimization_batch.json',JSON.stringify(s.batch,null,2),'application/json;charset=utf-8'));
 $('optimExportCSV').addEventListener('click',()=>{const head=['method','case_id','seed_index','kind','clean_mm','observed_mm','clean_success','status','updates','fk_evaluations'],text=[head.join(','),...s.batch.records.map(r=>head.map(k=>r[k]).join(','))].join('\n')+'\n';researchDownload('optimization_batch.csv',text,'text/csv;charset=utf-8')});
 $('optimizationContent').querySelectorAll('[data-optim-run]').forEach(b=>b.addEventListener('click',()=>{const r=s.batch.records[Number(b.dataset.optimRun)];s.caseIndex=r.case_index;s.seedIndex=r.seed_index;s.method=r.method;s.tab='single';recomputeOptimization();$('optimizationLab').scrollIntoView({block:'start'})}));
}
function renderOptimCode(){
 const s=OptimizationLab;
 $('optimizationContent').innerHTML='<h4>本地运行同一实验，再把结果带回来</h4><p>完整脚本只需要NumPy。下载默认值继承当前方法、目标、初值、η、λ和噪声设置；运行默认输出96条批量记录。</p><pre class="research-code">python optimization_basics.py --mode batch --output my_batch.json\npython optimization_basics.py --mode single --method '+s.method+' --case-index '+s.caseIndex+' --seed-index '+s.seedIndex+'</pre><p>--output直接写UTF-8文件，避免终端重定向编码差异。本模块是位置2R的新协议，文件应在下方导入；不交给之前的六维SciPy结果导入器。</p><div class="research-actions"><button type="button" id="optimDownload">下载完整优化/评价.py</button><button type="button" id="optimCopy">复制完整脚本</button></div><details><summary>查看求解与批量评价的完整代码</summary><pre id="optimPython" class="research-code"></pre></details><label>导入本模块的96条批量JSON <input id="optimImport" type="file" accept=".json"></label><p id="optimImportStatus" role="status"></p><div id="optimImportComparison"></div><details><summary>Scene2原文与资料来源</summary><pre class="research-code">'+esc(OPTIM_DATA.project_source.code)+'</pre><p>'+esc(OPTIM_DATA.project_source.file)+':'+OPTIM_DATA.project_source.start+'；SHA256 '+OPTIM_DATA.project_source.sha256+'</p>'+OPTIM_DATA.sources.sources.map(r=>'<p><a href="'+esc(r.url)+'" target="_blank" rel="noopener">'+esc(r.title)+'</a> · blob '+r.blobSha+'</p>').join('')+'<p>原项目按位置/朝向/相邻状态门槛验收，本教学实验只做位置目标优化。实现本地编写，未复制上游算法。</p></details><p>导入只检查协议与独立几何，不证明文件确实由声明后端运行。NumPy/JS的浮点舍入在接近停滞时可能改变回溯、预算停止和评估次数；应同时看位置误差和逐步记录，不要求跨后端逐位相同。</p>';
 $('optimPython').textContent=optimizationPython();$('optimImportStatus').textContent=s.importStatus;
 const readingButton=document.createElement('button');readingButton.type='button';readingButton.id='optimReadingLink';readingButton.textContent='先逐行读懂这份脚本，再做补代码练习';readingButton.addEventListener('click',()=>openResearchReading());$('optimPython').closest('details').before(readingButton);
 $('optimDownload').addEventListener('click',()=>researchDownload('optimization_basics.py',optimizationPython(),'text/x-python;charset=utf-8'));
 $('optimCopy').addEventListener('click',async()=>{try{await navigator.clipboard.writeText(optimizationPython());toast('已复制完整优化小实验')}catch{toast('可下载完整脚本')}});
 $('optimImport').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>2*1024*1024)throw Error('文件超过2MB');const data=validateOptimBatch(await readResearchJSONFile(file));s.imported=data;s.importStatus='已导入96条，协议、完整覆盖与最终位置指标已核对。'}catch(error){s.importStatus='导入失败：'+error.message+'；原有导入保留。'}renderOptimCode()});
 if(s.imported){
  const own=OptimMath.batch(s.settings),a=OptimMath.summary(own.records),b=OptimMath.summary(s.imported.records),changed=Object.keys(s.settings).filter(k=>s.settings[k]!==s.imported.settings[k]);
  $('optimImportComparison').innerHTML='<p>当前浏览器 vs 导入文件（'+esc(s.imported.runtime.backend)+'）。不同设置：'+esc(changed.join('、')||'无')+'。'+(changed.length>1?'多项改动，不作单因素归因。':'')+'</p>'+optimizationTable(['方法','浏览器全部达标 / 32','导入全部达标 / 32','浏览器可达组中位 mm','导入可达组中位 mm'],a.map((r,i)=>[OPTIM_METHOD_NAMES[r.method],r.success+'/32',b[i].success+'/32',optimizationNumber(r.known_median_mm),optimizationNumber(b[i].known_median_mm)]))+'<p>导入后的汇总重新由96条记录计算，忽略文件自带的汇总结论。仅当前会话展示，请保留原JSON。</p>';
 }
}
function optimArmFigure(result,index,item){
 const q=result.trace[index].q_rad,[L1,L2]=OPTIM_DATA.fixed.lengths_m,e=[L1*Math.cos(q[0]),L1*Math.sin(q[0])],p=OptimMath.fk(q).p,xy=v=>[170+75*v[0],165-75*v[1]],a=xy(item.clean_target_m),b=xy(item.observed_target_m);
 return '<svg viewBox="0 0 400 320" role="img" aria-label="当前2R姿态与原始和带噪目标"><rect width="400" height="320" rx="10" fill="#101b2a"/><path d="M15 165H385 M170 15V290" stroke="#52647e" fill="none"/><polyline points="'+[[0,0],e,p].map(x=>xy(x).join(',')).join(' ')+'" stroke="#ffbc70" stroke-width="5" fill="none"/><circle cx="'+a[0]+'" cy="'+a[1]+'" r="5" fill="#8ae1bb"/><circle cx="'+b[0]+'" cy="'+b[1]+'" r="8" stroke="#87adff" fill="none"/><text x="12" y="309" fill="#b6c6da" font-size="11">世界XY · 1m=75图内单位 · 绿原始目标 / 蓝观测目标</text></svg>';
}
function optimLossFigure(results){
 const colors={gd:'#87adff',gn:'#c6a5ff',dls:'#ffbc70'},all=results.flatMap(r=>r.trace.map(x=>Math.log10(x.observed_mm+.001))),lo=Math.floor(Math.min(...all)),hi=Math.max(lo+1,Math.ceil(Math.max(...all))),height=210,x=i=>42+310*i/80,y=err=>250-height*(Math.log10(err+.001)-lo)/(hi-lo);
 return '<svg viewBox="0 0 400 320" role="img" aria-label="三种方法的观测误差log10曲线"><rect width="400" height="320" rx="10" fill="#101b2a"/><path d="M42 20V250H365" stroke="#52647e" fill="none"/>'+'<path d="M42 '+y(.1)+'H365" stroke="#8ae1bb" stroke-dasharray="4 4"/><text x="300" y="'+(y(.1)-5)+'" fill="#8ae1bb" font-size="10">0.1mm</text>'+results.map(r=>'<polyline points="'+r.trace.map((row,i)=>[x(i),y(row.observed_mm)].join(',')).join(' ')+'" stroke="'+colors[r.method]+'" fill="none" stroke-width="2"/>').join('')+'<text x="4" y="30" fill="#b6c6da" font-size="10">'+hi+'</text><text x="4" y="250" fill="#b6c6da" font-size="10">'+lo+'</text><text x="42" y="270" fill="#b6c6da" font-size="11">0 → 80次更新 · 纵轴log10(误差mm+0.001)</text><text x="42" y="303" fill="#b6c6da" font-size="11">蓝GD · 紫GN · 橙DLS；曲线在各自停止处结束</text></svg>';
}
function optimHistogram(summaries){
 const colors=['#87adff','#c6a5ff','#ffbc70'],labels=['≤0.1','0.1–0.5','0.5–2','2–10','10–100','>100'];let body='';
 summaries.forEach((s,j)=>s.bins.forEach((n,i)=>{const x=38+i*58+j*13,y=225-n*5;body+='<rect x="'+x+'" y="'+y+'" width="11" height="'+n*5+'" fill="'+colors[j]+'"/><text x="'+x+'" y="'+(y-5)+'" fill="'+colors[j]+'" font-size="9">'+n+'</text>'}));
 return '<svg class="optim-histogram" viewBox="0 0 420 300" role="img" aria-label="三种方法原始目标误差的统一分箱计数"><rect width="420" height="300" rx="10" fill="#101b2a"/><path d="M28 35V225H403" stroke="#52647e" fill="none"/>'+body+labels.map((v,i)=>'<text x="'+(32+i*58)+'" y="248" fill="#b6c6da" font-size="10">'+v+'</text>').join('')+'<text x="30" y="277" fill="#b6c6da" font-size="11">误差mm · 纵轴样本计数 · 蓝GD / 紫GN / 橙DLS</text></svg>';
}

// Analysis of executed NumPy records. No new optimizer runs or hidden retuning in the browser.
const ObservationLab={selected:'lambda_010',hypothesis:'在A组选择的阻尼，能否提高B组相对于固定基线的达标数？',prediction:'',exposed:false,exploratory:false,lock:null,notes:{observation:'',explanation:'',next_test:''},imported:null,status:''};
function observationData(){return ObservationLab.imported||OBSERVATION_DATA.experiment}
function observationScore(records,group,id){
 const rows=records.filter(r=>r.group===group&&r.candidate_id===id),p=rows.filter(r=>r.kind==='constructed'),s=rows.filter(r=>r.kind!=='constructed'),sorted=p.map(r=>r.clean_mm).sort((a,b)=>a-b);
 return {candidate_id:id,n:p.length,success:p.filter(r=>r.clean_success).length,median_mm:(sorted[11]+sorted[12])/2,mean_fk:p.reduce((sum,r)=>sum+r.fk_evaluations,0)/p.length,max_mm:Math.max(...p.map(r=>r.clean_mm)),stress_n:s.length,stress_success:s.filter(r=>r.clean_success).length};
}
function observationRank(data){return data.candidates.map(c=>observationScore(data.records,'A',c.id)).sort((a,b)=>b.success-a.success||a.median_mm-b.median_mm||a.mean_fk-b.mean_fk||a.candidate_id.localeCompare(b.candidate_id))}
function observationPairs(data,id){
 const a=data.records.filter(r=>r.group==='B'&&r.candidate_id===id&&r.kind==='constructed'),base=data.records.filter(r=>r.group==='B'&&r.candidate_id===data.baseline&&r.kind==='constructed');
 return a.map(r=>{const b=base.find(x=>x.case_id===r.case_id&&x.seed_index===r.seed_index);return {case_id:r.case_id,seed_index:r.seed_index,selected_mm:r.clean_mm,baseline_mm:b.clean_mm,outcome:r.clean_success&&!b.clean_success?'win':b.clean_success&&!r.clean_success?'loss':'tie'}});
}
function validateObservationReport(x){
 const expected=OBSERVATION_DATA.experiment,fail=m=>{throw Error(m)},near=(a,b,label)=>{if(typeof a!=='number'||!Number.isFinite(a)||Math.abs(a-b)>1e-6+Math.abs(b)*1e-8)fail(label+'与独立重算不一致')};
 if(x?.schema!=='geometry-lab-heldout-dls/v1'||!x.runtime||typeof x.runtime.backend!=='string'||x.runtime.backend.length>100)fail('报告格式或运行环境声明不支持');
 if(!x.fixed||Object.keys(x.fixed).length!==Object.keys(expected.fixed).length||Object.keys(expected.fixed).some(k=>JSON.stringify(x.fixed[k])!==JSON.stringify(expected.fixed[k])))fail('固定评价或守护参数改变');
 if(!Array.isArray(x.candidates)||x.candidates.length!==4||new Set(x.candidates.map(c=>c.id)).size!==4||x.candidates.some(c=>!expected.candidates.some(e=>e.id===c.id&&e.damping===c.damping))||x.baseline!==expected.baseline||JSON.stringify(x.seeds_deg)!==JSON.stringify(expected.seeds_deg))fail('候选网格、基线或初值集合不同');
 if(!x.cases||!Array.isArray(x.records)||x.records.length!==256)fail('需保留完整256条配对运行');
 for(const group of ['A','B']){
  if(!Array.isArray(x.cases[group])||x.cases[group].length!==8)fail('A/B均需8个目标');
  x.cases[group].forEach((c,i)=>{const e=expected.cases[group][i];if(c.id!==e.id||c.kind!==e.kind||c.index!==i||c.group!==group)fail('目标编号或组别错误');for(const k of ['clean_target_m','observed_target_m']){if(!Array.isArray(c[k])||c[k].length!==2)fail('目标shape错误');c[k].forEach((v,j)=>near(v,e[k][j],k))}});
 }
 const seen=new Set();
 for(const r of x.records){
  if(!['A','B'].includes(r.group)||!Number.isInteger(r.case_index)||r.case_index<0||r.case_index>=8||!Number.isInteger(r.seed_index)||r.seed_index<0||r.seed_index>=4||!expected.candidates.some(c=>c.id===r.candidate_id)||r.method!=='dls')fail('结果索引错误');
  const key=[r.group,r.candidate_id,r.case_index,r.seed_index].join('/');if(seen.has(key))fail('结果重复，覆盖不完整');seen.add(key);
  const c=expected.cases[r.group][r.case_index];if(r.case_id!==c.id||r.kind!==c.kind)fail('结果目标不匹配');
  const p=OptimMath.fk(r.q_rad).p;if(r.q_rad.some(v=>Math.abs(v)>150*Math.PI/180+1e-9))fail('关节超限');
  const mm=Math.hypot(...p.map((v,i)=>v-c.clean_target_m[i]))*1000;near(r.clean_mm,mm,'原始误差');near(r.observed_mm,mm,'观测误差');
  if(r.clean_success!==(mm<=.1)||!Object.keys(OPTIM_STOP_NAMES).includes(r.status)||(r.status==='fit')!==(mm<=.1))fail('门槛或停止布尔值不符');
  if(!Number.isInteger(r.updates)||r.updates<0||r.updates>80||!Number.isInteger(r.fk_evaluations)||r.fk_evaluations<2*r.updates+1||r.fk_evaluations>1134)fail('计数字段不合法');
 }
 return JSON.parse(JSON.stringify(x));
}
function observationRecord(){const s=ObservationLab;return {schema:'geometry-lab-observation-notes/v1',dataset_reference_sha256:OBSERVATION_DATA.experiment.runtime.script_sha256,report:s.imported&&s.exposed?s.imported:null,selected:s.selected,hypothesis:s.hypothesis,prediction:s.prediction,lock:s.lock,notes:s.notes,exposed:s.exposed,exploratory:s.exploratory}}
function validateObservationRecord(x){
 if(x?.schema!=='geometry-lab-observation-notes/v1')throw Error('不是本模块学习记录');
 if(x.dataset_reference_sha256!==OBSERVATION_DATA.experiment.runtime.script_sha256)throw Error('实验快照不同');
 const report=x.report?validateObservationReport(x.report):OBSERVATION_DATA.experiment;
 if(!report.candidates.some(c=>c.id===x.selected)||typeof x.hypothesis!=='string'||x.hypothesis.length>4000||!['','better','same','worse'].includes(x.prediction))throw Error('方案或问题字段无效');
 if(!x.notes||['observation','explanation','next_test'].some(k=>typeof x.notes[k]!=='string'||x.notes[k].length>10000))throw Error('分析记录字段无效');
 if(x.lock&&(!report.candidates.some(c=>c.id===x.lock.selected)||typeof x.lock.hypothesis!=='string'||x.lock.hypothesis.length>4000||!['','better','same','worse'].includes(x.lock.prediction)||typeof x.lock.at!=='string'||!Number.isFinite(Date.parse(x.lock.at))))throw Error('冻结记录无效');
 return {report,selected:x.selected,hypothesis:x.hypothesis,prediction:x.prediction,lock:x.lock?{selected:x.lock.selected,hypothesis:x.lock.hypothesis,prediction:x.lock.prediction,at:x.lock.at}:null,notes:{...x.notes}};
}
function openObservationAnalysis(){openOptimizationLab();OptimizationLab.tab='analysis';renderOptimizationLab();$('optimizationLab').scrollIntoView({block:'start'})}
function renderObservationAnalysis(){
 const s=ObservationLab,data=observationData(),ranked=observationRank(data),label=id=>'λ='+data.candidates.find(c=>c.id===id).damping,table=optimizationTable;
 $('optimizationContent').innerHTML='<h4>提出问题 → 用A选方案 → 冻结 → 查看B → 写有限结论</h4><p>这里回放NumPy实际计算的256条记录，不在浏览器运行新目标优化。A与B各8个手工设计目标，每个4初值；每组6个无噪声构造可达目标作主要评价（24条），另2个不可达压力目标（8条）单列。4个候选固定DLS阻尼λ，λ=0退回GN。η=0.8、其他守护及0.1mm门槛固定。</p><p>这是留出评价的教学模拟，网页不能证明你此前从未见过B。关闭前可导出学习记录；原实验数据与研究笔记不变。</p>'+observationPrimer()+'<label class="observation-field">1 · 我的研究问题 <textarea id="observationQuestion" rows="2" maxlength="4000"></textarea></label><h4>2 · 只依据A组观察和选方案</h4>'+table(['候选','A达标 / 24','A中位误差 mm','A平均FK评估','A压力组达标 / 8'],ranked.map(r=>[label(r.candidate_id),r.success+'/24',optimizationNumber(r.median_mm),optimizationNumber(r.mean_fk),r.stress_success+'/8']))+'<p>预先声明的推荐规则：先最大化A达标数，再最小化A中位误差，再最小化平均FK评估，最后按候选id稳定破同分。仅用A计算的推荐为<b id="observationRecommendation">'+label(ranked[0].candidate_id)+'</b>。没有在这里读取B分数来选参数。</p><div class="observation-pick"><label>选择方案 <select id="observationCandidate">'+data.candidates.map(c=>'<option value="'+c.id+'"'+(c.id===s.selected?' selected':'')+'>λ='+c.damping+'</option>').join('')+'</select></label><label>预测：B相对固定基线λ=0.1的达标数 <select id="observationPrediction"><option value="">尚未预测</option>'+[['better','更多'],['same','相同'],['worse','更少']].map(([k,v])=>'<option value="'+k+'"'+(k===s.prediction?' selected':'')+'>'+v+'</option>').join('')+'</select></label></div><div class="research-actions"><button type="button" id="observationUseRecommended">采用A组推荐</button><button type="button" id="observationFreeze">'+(s.lock?'查看当前方案的B组分析':'冻结方案并展开B组')+'</button></div><p id="observationPhase" class="reading-contract">'+observationPhase()+'</p><div id="observationB"></div><h4>4 · 把观察、解释与反驳办法分开</h4>'+[['observation','观察：哪些具体数字发生了什么变化？'],['explanation','解释假设：你认为原因是什么？还有别的解释吗？'],['next_test','下一步：用什么新目标或单因素实验反驳/支持它？']].map(([k,n])=>'<label class="observation-field">'+n+'<textarea rows="3" maxlength="10000" data-observation-note="'+k+'"></textarea></label>').join('')+'<details><summary>提示：怎样写一条证据支持的结论</summary><p>先写固定B组上达标数、误差和失败发生了什么，再写原因假设。例如“达标数相同，但中位误差更小”与“成功率提高”是不同结论。一次固定小集合不能证明所有机器人、噪声和目标都更好；同一目标的4初值相关，不当独立总体样本做显著性推断。</p></details><details><summary>独立Python复现、结果导入与学习记录</summary><p>只需NumPy；下载是完整独立脚本，256条结果和源码指纹会写入UTF-8 JSON。主评分与基线在脚本里显式声明，不训练模型。</p><pre class="research-code">python observation_basics.py --output observation_results.json</pre><div class="research-actions"><button type="button" id="observationDownload">下载完整A/B实验.py</button><button type="button" id="observationExport">导出本轮分析记录.json</button></div><label>导入完整Python结果 <input type="file" id="observationImport" accept=".json"></label><br><label>合并恢复学习记录 <input type="file" id="observationRestore" accept=".json"></label><p>导入/恢复会保守标记已接触B，只能作为探索或过程记录，不恢复为“从未看B”。已有非空分析文字保留；结果文件的自报推荐与总结不会作为评分依据。</p><p id="observationStatus" role="status"></p>'+OBSERVATION_DATA.sources.sources.filter(r=>r.url.includes('scikit-learn')).map(r=>'<p><a href="'+esc(r.url)+'" target="_blank" rel="noopener">'+esc(r.role)+'</a> · blob '+r.blobSha+'</p>').join('')+'<p>留出思路参考scikit-learn官方方法论；本练习实际运行NumPy，不包含模型训练、PyTorch自动求导或实机验证。导入只核对当前固定协议，修改目标集或门槛后的新实验需在Python单独分析。</p></details>';
 $('observationQuestion').value=s.hypothesis;$('observationQuestion').addEventListener('input',e=>{s.hypothesis=e.target.value;if(s.exposed&&s.lock?.hypothesis!==s.hypothesis){s.exploratory=true;updateObservationPhase()}});
 $('observationCandidate').addEventListener('change',e=>observationSelect(e.target.value));
 $('observationPrediction').addEventListener('change',e=>{s.prediction=e.target.value;if(s.exposed){s.exploratory=true;updateObservationPhase()}});
 $('observationUseRecommended').addEventListener('click',()=>observationSelect(ranked[0].candidate_id));
 $('observationFreeze').addEventListener('click',()=>{if(!s.lock){if(!s.hypothesis.trim()||!s.prediction){$('observationPhase').textContent='请先填写研究问题，并选择对B组的预测，再冻结。';return}s.lock={selected:s.selected,hypothesis:s.hypothesis,prediction:s.prediction,at:new Date().toISOString()}}s.exposed=true;updateObservationPhase();renderObservationB()});
 $('optimizationContent').querySelectorAll('[data-observation-note]').forEach(el=>{el.value=s.notes[el.dataset.observationNote];el.addEventListener('input',()=>{s.notes[el.dataset.observationNote]=el.value})});
 $('observationDownload').addEventListener('click',()=>researchDownload('observation_basics.py',OBSERVATION_DATA.python,'text/x-python;charset=utf-8'));
 $('observationExport').addEventListener('click',()=>researchDownload('observation_notes.json',JSON.stringify(observationRecord(),null,2),'application/json;charset=utf-8'));
 $('observationStatus').textContent=s.status;
 $('observationImport').addEventListener('change',async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>2*1024*1024)throw Error('文件超过2MB');const report=validateObservationReport(await readResearchJSONFile(f));s.imported=report;s.exposed=true;s.exploratory=true;s.status='已核对完整256条最终几何与协议，重新汇总；标记为已接触B的探索。'}catch(error){s.status='导入失败，原数据与分析保留：'+error.message}renderObservationAnalysis()});
 $('observationRestore').addEventListener('change',async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>2*1024*1024)throw Error('文件超过2MB');const x=validateObservationRecord(await readResearchJSONFile(f)),conflicts=[];s.imported=x.report;if(!s.lock){s.selected=x.selected;s.lock=x.lock}else conflicts.push('当前冻结方案');for(const k of ['hypothesis','prediction']){if(!s[k])s[k]=x[k];else if(x[k]&&s[k]!==x[k])conflicts.push(k)}for(const k of Object.keys(s.notes)){if(!s.notes[k])s.notes[k]=x.notes[k];else if(x.notes[k]&&s.notes[k]!==x.notes[k])conflicts.push(k)}s.exposed=true;s.exploratory=true;s.status='已恢复过程记录，保留当前非空冲突：'+(conflicts.join('、')||'无')+'；B已接触，不恢复为未查看。'}catch(error){s.status='恢复失败，当前记录保留：'+error.message}renderObservationAnalysis()});
 if(s.exposed)renderObservationB();
}
function observationPrimer(){return '<details><summary>先读懂这次实验：A/B、初值、指标和代码分别是什么？</summary><p><b>A/B不是两个算法，也不是同时换很多条件。</b>A组用来观察4个固定阻尼并选择方案；B组使用不同目标检查这个选择。两组保留相同机械臂长度、初值集合、限位、更新预算和评价门槛。若反复看B再调参数，B就参与了选择，应记录为探索，并另找新目标检验。</p><p><b>初值 seed：</b>这里指求解开始时的两个关节角，不是随机数种子。4组角度为[15,35]、[-60,60]、[70,-50]、[0,0]度；计算转成rad。目标由正向运动学FK得到位置p，Jacobian描述角度小变化如何影响位置。相同目标与初值配对，才能比较换λ后的影响。</p><p><b>λ与控制变量：</b>DLS固定阻尼用增广最小二乘求更新；λ=0是GN。这里只改变λ，不改变误差达标门槛。学习率η只影响GD，本实验不运行GD，因此固定η并不参与DLS更新。前面的“公式与手算”可逐行看J.T@r与np.linalg.lstsq。</p><p><b>达标与中位数：</b>原始目标距离≤0.1mm算达标。每组6目标×4初值=24条是预先固定的主要分母；另外2个不可达目标×4初值=8条压力测试，失败仍保留。中位误差对全部24条排序，取中间两条平均，包含失败，不只统计成功记录。达标数相同也可能有不同误差，二者要分别写。</p><p><b>工作量和失败：</b>平均FK评估次数包括回溯试探，不能当作不同电脑上的运行秒数。零梯度但残差很大、预算耗尽、回溯失败都应查原因；不可达压力目标是有意设置的负面对照，不能通过删失败或改门槛让结果好看。表中的4初值来自同一目标，不当作独立人群抽样。</p><p><b>从表格回到Python：</b>make_cases构造目标 → run_group逐目标/初值调用solve_target → run_experiment保存256条 → select_on_A只用A选择 → paired_on_B按目标id和seed_index配对。q_rad是shape(2,)的弧度角；FK位置shape(2,)、单位m；np.linalg.norm(p-target)*1000得到mm。np.median计算中位数，sum(r["clean_success"] for r in rows)统计达标条数。脚本是可直接下载阅读的完整代码。</p><p><b>怎样继续：</b>先写一个可被数字推翻的预测，再比较达标数、误差与失败。若想研究噪声，下一次只改变噪声，保持同一组噪声用于所有候选；若想检验能否推广，换一组预先固定的新目标。当前无噪声、二维位置实验不能解释朝向、碰撞、受力或真实UR5e表现。</p></details>'}
function observationPhase(){const s=ObservationLab;return s.exploratory?'探索状态：已经接触B后修改方案/问题/预测，或导入过记录。原冻结决策保留，不把新选择称为独立检验。':s.exposed?'已冻结的教学留出记录。继续改参数会保留B暴露标记并转为探索；重开页面也不产生真正新的未见数据。':'B尚未在界面展开。先依据A选方案并记录预测，再冻结。'}
function updateObservationPhase(){$('observationPhase').textContent=observationPhase()}
function observationSelect(id){const s=ObservationLab;if(s.exposed&&id!==s.selected)s.exploratory=true;s.selected=id;$('observationCandidate').value=id;updateObservationPhase();if(s.exposed)renderObservationB()}
function renderObservationB(){
 const s=ObservationLab,data=observationData(),selected=observationScore(data.records,'B',s.selected),base=observationScore(data.records,'B',data.baseline),pairs=observationPairs(data,s.selected),counts={win:0,loss:0,tie:0};pairs.forEach(p=>counts[p.outcome]++);
 const actual=selected.success>base.success?'better':selected.success<base.success?'worse':'same',prediction=s.lock?.prediction;
 const table=optimizationTable;
 $('observationB').innerHTML='<h4>3 · B组结果：当前所选λ='+data.candidates.find(c=>c.id===s.selected).damping+'</h4>'+table(['方案','B达标 / 24','中位误差 mm','最大误差 mm','压力组达标 / 8'],[['当前方案',selected.success+'/24',optimizationNumber(selected.median_mm),optimizationNumber(selected.max_mm),selected.stress_success+'/8'],['固定基线 λ=0.1',base.success+'/24',optimizationNumber(base.median_mm),optimizationNumber(base.max_mm),base.stress_success+'/8']])+observationBars(selected,base)+'<p id="observationEvidence">相同目标/初值配对：只选中方案达标'+counts.win+'条，只基线达标'+counts.loss+'条，二者达标布尔相同'+counts.tie+'条。“相同”不表示误差数值完全相同。</p><p>冻结时预测：'+(prediction?({better:'更多',same:'相同',worse:'更少'}[prediction]):'未填写')+'；当前方案达标数相对基线：'+({better:'更多',same:'相同',worse:'更少'}[actual])+'。'+(s.lock&&s.lock.selected!==s.selected?'当前方案已不同于冻结方案，不能用原预测为新方案背书。':'')+'</p><details><summary>逐目标查看（每个目标4个相关初值）</summary>'+table(['目标','只方案达标','只基线达标','布尔相同'],data.cases.B.filter(c=>c.kind==='constructed').map(c=>{const p=pairs.filter(r=>r.case_id===c.id);return [c.id,p.filter(r=>r.outcome==='win').length,p.filter(r=>r.outcome==='loss').length,p.filter(r=>r.outcome==='tie').length]}))+'</details><details><summary>展开B上所有候选（探索性比较）与完整256条</summary>'+table(['候选','B达标 / 24','中位误差 mm'],data.candidates.map(c=>{const r=observationScore(data.records,'B',c.id);return ['λ='+c.damping,r.success+'/24',optimizationNumber(r.median_mm)]}))+'<div class="observation-record-list">'+table(['组/候选/目标/初值','误差 mm','停止/达标'],data.records.map(r=>[r.group+' / '+r.candidate_id+' / '+r.case_id+' / '+r.seed_index,optimizationNumber(r.clean_mm),OPTIM_STOP_NAMES[r.status]+' / '+r.clean_success]))+'</div></details><p>主要分母固定为各组24个构造可达情景；另8个压力情景单列，全部保留。没有p值、总体成功率保证或跨硬件速度结论。</p>';
}
function observationBars(selected,base){
 const rows=[['当前方案',selected,'#ffbc70'],['固定基线',base,'#87adff']];
 return '<svg class="observation-bars" viewBox="0 0 420 170" role="img" aria-label="B组当前方案与固定基线达标数，分母24">'+rows.map(([name,r,color],i)=>'<text x="12" y="'+(45+i*65)+'" fill="#b6c6da" font-size="12">'+name+'</text><rect x="90" y="'+(25+i*65)+'" width="270" height="24" fill="#23344b"/><rect x="90" y="'+(25+i*65)+'" width="'+(270*r.success/24)+'" height="24" fill="'+color+'"/><text x="370" y="'+(43+i*65)+'" fill="'+color+'" font-size="12">'+r.success+'/24</text>').join('')+'<text x="90" y="157" fill="#b6c6da" font-size="11">同一固定门槛与分母，误差指标需另外比较</text></svg>';
}

// Fixed teaching choices replay actual Python probes; never evaluates user code in the browser.
const ReadingLab={ready:false,tab:'source',segment:0,line:0,scenario:'normal',revealed:false,predictions:{normal:'',stationary:'',noisy:''},task:0,answers:{},checked:{},hints:{},shown:{},python:null,status:'',recordStatus:''};
const READING_SCENARIOS={normal:{title:'普通目标、无噪声',caseIndex:0,seedIndex:0,noise:0},stationary:{title:'径向目标、奇异初值',caseIndex:1,seedIndex:3,noise:0},noisy:{title:'普通目标、带噪观测',caseIndex:0,seedIndex:0,noise:1}};
function readingEqual(a,b){
 if(typeof a!==typeof b||a===null||b===null)return a===b;
 if(typeof b==='number')return Number.isFinite(a)&&Math.abs(a-b)<=1e-10;
 if(Array.isArray(b))return Array.isArray(a)&&a.length===b.length&&a.every((v,i)=>readingEqual(v,b[i]));
 if(typeof b==='object'){const ak=Object.keys(a).sort(),bk=Object.keys(b).sort();return JSON.stringify(ak)===JSON.stringify(bk)&&bk.every(k=>readingEqual(a[k],b[k]))}
 return a===b;
}
function readingGrade(rows){return READING_DATA.tests.map(test=>{const row=rows.find(r=>r.id===test.id);return {id:test.id,task:test.task,present:!!row,passed:!!row&&row.error===null&&readingEqual(row.value,test.expected),value:row?.value,error:row?.error||null,expected:test.expected}})}
function validateReadingReport(x){
 if(x?.schema!=='geometry-lab-reading-results/v1'||!Array.isArray(x.results)||x.results.length>13)throw Error('不是本练习的结果格式，最多13项');
 if(!x.runtime||['python','numpy'].some(k=>typeof x.runtime[k]!=='string'||x.runtime[k].length>100)||!/^[0-9a-f]{64}$/i.test(x.runtime.script_sha256))throw Error('缺少运行版本或脚本指纹');
 const ids=new Set();
 const safe=(v,depth=0)=>{if(depth>4)throw Error('结果嵌套过深');if(typeof v==='number'&&!Number.isFinite(v))throw Error('结果含非有限数');if(typeof v==='string'&&v.length>300)throw Error('结果字符串过长');if(v&&typeof v==='object'){const values=Object.values(v);if(values.length>30)throw Error('结果过大');values.forEach(x=>safe(x,depth+1))}};
 x.results.forEach(row=>{if(!row||!READING_DATA.tests.some(t=>t.id===row.id)||ids.has(row.id))throw Error('测试编号未知或重复');ids.add(row.id);if(row.error!==null&&typeof row.error!=='string')throw Error('错误字段需是字符串或null');if(row.error?.length>2000)throw Error('错误信息过长');if(!Object.prototype.hasOwnProperty.call(row,'value'))throw Error('缺少value');safe(row.value)});
 return JSON.parse(JSON.stringify(x));
}
function readingChoiceResults(task,option){return readingGrade(task.option_results[option]).filter(r=>r.task===task.id)}
function readingDisplay(value){return value&&typeof value==='object'&&!Array.isArray(value)?JSON.stringify(value):researchValue(value)}
function readingError(message){const meaning=message.includes('NotImplementedError')?'函数还未补全':message.includes('matmul')?'矩阵乘法维度不匹配':'Python执行返回错误';return meaning+'；原文：'+message}
function readingRecord(){const s=ReadingLab;return {schema:'geometry-lab-reading-notes/v1',answers:s.answers,checked:s.checked,predictions:s.predictions,shown:s.shown,python_report:s.python,source_sha256:READING_DATA.source.sha256,exercise_sha256:READING_DATA.reference_results.runtime.script_sha256}}
function validateReadingRecord(x){
 if(x?.schema!=='geometry-lab-reading-notes/v1'||x.source_sha256!==READING_DATA.source.sha256||x.exercise_sha256!==READING_DATA.reference_results.runtime.script_sha256)throw Error('学习记录版本/源码或练习快照不同');
 const output={answers:{},checked:{},shown:{},predictions:{}};
 for(const k of ['answers','checked','shown']){if(!x[k]||typeof x[k]!=='object'||Array.isArray(x[k]))throw Error('学习记录字段错误');for(const [id,value]of Object.entries(x[k])){const t=READING_DATA.tasks.find(t=>t.id===id);if(!t||k==='answers'&&!t.options.some(o=>o[0]===value)||k!=='answers'&&typeof value!=='boolean')throw Error('练习编号或选项错误');output[k][id]=value}}
 if(!x.predictions||typeof x.predictions!=='object'||Array.isArray(x.predictions))throw Error('预测字段错误');
 for(const [id,value]of Object.entries(x.predictions)){if(!Object.prototype.hasOwnProperty.call(READING_SCENARIOS,id)||!['',...Object.keys(OPTIM_STOP_NAMES)].includes(value))throw Error('预测值不支持');output.predictions[id]=value}
 output.python_report=x.python_report?validateReadingReport(x.python_report):null;return output;
}
