function readingTable(headers,rows){return '<div class="reading-table-wrap"><table class="reading-table"><thead><tr>'+headers.map(x=>'<th>'+esc(String(x))+'</th>').join('')+'</tr></thead><tbody>'+rows.map(r=>'<tr>'+r.map(x=>'<td>'+esc(String(x))+'</td>').join('')+'</tr>').join('')+'</tbody></table></div>'}
