  const panel=$('robotProjectBridge');if(!panel)return;const id=RobotBasics.id;
  panel.addEventListener('toggle',()=>{if(!panel.isConnected||RobotBasics.id!==id)return;RobotProjectBridge.open[id]=panel.open;$('robotProjectBody').innerHTML=panel.open?robotProjectBody():'';if(panel.open)bindRobotProjectBody()});
  if(panel.open)bindRobotProjectBody();
