const RobotArticles={open:{},zoomTrigger:null};
function robotArticleArrow(x1,y1,x2,y2,color='#c2b0ff'){
  const a=Math.atan2(y2-y1,x2-x1),p=(length,offset)=>[x2-length*Math.cos(a)+offset*Math.sin(a),y2-length*Math.sin(a)-offset*Math.cos(a)];
  return '<path d="M'+x1+' '+y1+'L'+x2+' '+y2+'" fill="none" stroke="'+color+'" stroke-width="3"/><polygon points="'+[[x2,y2],p(11,5),p(11,-5)].map(v=>v.join(',')).join(' ')+'" fill="'+color+'"/>';
}
