  const rail=$('taskJourney').querySelector('.course-workflow'),active=rail.querySelector('[aria-pressed="true"]');
  if(rail.scrollWidth>rail.clientWidth){const r=rail.getBoundingClientRect(),b=active.getBoundingClientRect();if(b.left<r.left)rail.scrollLeft+=b.left-r.left;else if(b.right>r.right)rail.scrollLeft+=b.right-r.right;}
  $('journeyStepCount').textContent='任务观察 '+(step+1)+' / 6 · 本次已判断 '+Object.keys(LearningJourney.answers).length+' / 6';$('journeyTitle').textContent=content.title;
