  $('journeyFeedback').textContent=answer===undefined?'':(answer===content.correct?'判断正确。':'再观察一下。')+content.answer;
  $('journeyQuestionSummary').textContent='展开解释';$('journeyAnswer').textContent=content.answer;$('journeyQuestion').hidden=answer!==undefined;
  $('taskJourney').querySelector('[data-journey-move="-1"]').disabled=step===0;$('taskJourney').querySelector('[data-journey-move="1"]').disabled=step===5;
  $('journeyLessonLink').innerHTML=learningPathLink(content.id,'学习这一步：'+LEARNING_PATH.workflow[step].title+' →');
