function filterLearningNavigation(){
  const query=LearningPath.query.toLowerCase();let count=0;
  $('courseNav').querySelectorAll('[data-course-lesson]').forEach(button=>{
    const id=button.dataset.courseLesson,entry=learningPathEntry(id),original=LESSONS.findIndex(lesson=>lesson.id===id),lesson=LESSONS[original];
    const text=[id,original+1,String(original+1).padStart(2,'0'),entry?.node.title,entry?.node.why,entry?.stage.title,lesson?.name,lesson?.en,id==='quiz'?'自测':''].join(' ').toLowerCase();
    button.hidden=!!query&&!text.includes(query);if(!button.hidden)count++;
  });
  for(const link of $('courseNav').querySelectorAll('[data-course-topic]')){
    link.hidden=!!query&&!link.textContent.toLowerCase().includes(query);
    if(!link.hidden)count++;
  }
  $('courseNav').querySelectorAll('.course-nav-extra,[data-course-stage],[data-course-group]').forEach(details=>{
    const found=[...details.querySelectorAll('[data-course-lesson],[data-course-topic]')].some(item=>!item.hidden);
    details.hidden=!found;
    if(query&&found)details.open=true;
  });
  $('courseNavEmpty').hidden=count>0;
}
function syncCourseLocation(topicId){
  const entry=learningPathEntry(activeLearningLesson()),topic=REPRESENTATION_DATA.topics.find(item=>item.id===topicId);
  const group=LEARNING_PATH.directory.find(item=>topic?item.topics.includes(topic.id):item.stages.includes(entry?.stage.id));
  $('courseLocation').textContent=LearningPath.home?'由浅入深的学习路线':group?group.title+' / '+(topic?.title.split('：')[0]||entry.node.title):'自测与易错点';
  for(const link of document.querySelectorAll('[data-course-topic]')){
    if(topic?.id===link.dataset.courseTopic)link.setAttribute('aria-current','page');else link.removeAttribute('aria-current');
  }
  const link=topic&&$('courseNav').querySelector('[data-course-topic="'+topic.id+'"]');
  if(link){
    for(const node of $('courseNav').querySelectorAll('[data-course-lesson][aria-current]')){node.removeAttribute('aria-current');node.classList.remove('active');}
    for(let node=link.parentElement;node&&node!==$('courseNav');node=node.parentElement)if(node.tagName==='DETAILS')node.open=true;
  }
}
