  if(course){$('prev').disabled=!neighbours.previous;$('next').disabled=!neighbours.next;$('prev').textContent=neighbours.previous?(extra?'← 返回主线 · ':'← ')+neighbours.previous.title:'从主线第一节开始';$('next').textContent=neighbours.next?(extra?'继续主线 · ':'')+neighbours.next.title+' →':'已到自测';}
