  strip.addEventListener('click',event=>{const select=event.target.closest('[data-film-select]');if(select){FilmGallery.exhibit=Number(select.dataset.filmSelect);renderFilmExhibit();return;}const button=event.target.closest('[data-film-open]');if(button)openFilmPreview(Number(button.dataset.filmOpen),button);});
