// Appearance and discovery are independent of lesson parameters and personal study records.
const LabExperience={theme:'live',motion:true,focus:false,frame:0,lastFrame:0,startedAt:null,elapsed:0,width:0,height:0,pointer:[0,0],offset:[0,0],reduced:null};
const LabSearch={entries:[],results:[],active:0,trigger:null,navigating:false};
function labSearchNormalize(text){return String(text).normalize('NFKC').toLowerCase().replace(/\s+/g,' ').trim()}
function buildLabSearchIndex(){
  const guides=LAB_SEARCH_CONTENT.guides,main=learningPathMain().map(item=>item.id);
  const lessons=[...main,...LESSONS.map(item=>item.id).filter(id=>!main.includes(id))];
  const entries=lessons.map(id=>{
    const lesson=LESSONS.find(item=>item.id===id),entry=learningPathEntry(id),guide=guides.find(item=>item.kind==='lesson'&&item.id===id);
    return {kind:'lesson',id,title:entry?.node.title||lesson.name,description:guide?.definition||entry?.node.why||lesson?.sub||'',
      terms:[id,...(lesson?[lesson.en,lesson.name]:[]),...(guide?.terms||[])],group:entry?.extra?'按需扩展':'主线课程',context:entry?.stage.title||'实验',index:LESSONS.indexOf(lesson)};
  });
  for(const topic of REPRESENTATION_DATA.topics){
    const group=LEARNING_PATH.directory.find(group=>group.topics.includes(topic.id));
    const context=group.title,kind='representation',id='binding/'+topic.id;
    entries.push({kind,id,title:topic.title,description:topic.question,terms:topic.aliases,group:'课程',context});
    for(const section of REPRESENTATION_DATA.search_sections.filter(item=>item.topic===topic.id)){
      entries.push({kind,id:id+'/'+section.section,title:section.title,description:topic.question,terms:section.terms,group:'课内实验',context});
    }
  }
  for(const topic of mathLearningTopics()){
    const guide=guides.find(item=>item.kind==='math'&&item.id===topic.id);
    entries.push({kind:'math',id:topic.id,title:guide?.title||topic.title,description:guide?.definition||(Array.isArray(topic.meaning)?topic.meaning[0]:topic.meaning),terms:[topic.title,topic.english,topic.shape,...(guide?.terms||[])],group:'数学基础',context:'独立小实验'});
  }
  for(const library of ['numpy','torch'])FOUNDATION_DATA[library].forEach((item,index)=>entries.push({kind:'api',id:library+':'+index,library,index,title:item.name,description:item.meaning,terms:[item.name.replace(/^np\./,'numpy.'),item.contract,item.trap],group:library==='numpy'?'NumPy函数':'PyTorch函数',context:library==='numpy'?'数组与数值':'张量与梯度'}));
  for(const card of ROBOT_PROJECT_CONTENT.cards){const topic=ROBOT_PROJECT_CONTENT.topics.find(item=>item.cards.includes(card.id));if(topic)entries.push({kind:'project',id:'project:'+card.id,card:card.id,lesson:topic.id,title:card.title,description:card.contract,terms:[card.source.code,...card.apis.flat()],group:'Scene2源码',context:learningPathEntry(topic.id).node.title});}
  return entries.map(entry=>({...entry,haystack:labSearchNormalize([entry.title,entry.description,entry.group,...entry.terms].join(' '))}));
}
function rankLabSearch(query,entries=LabSearch.entries){
  const raw=labSearchNormalize(query),q=raw.replace(/^(什么是|如何理解|怎么理解|我想了解|请解释)\s*/,'').replace(/[?？。]+$/,'').trim();
  if(!q)return entries.filter(entry=>entry.kind==='lesson').slice(0,8).map(entry=>({entry,score:0}));
  const tokens=q.split(' '),scored=[];
  const contains=text=>/^[a-z]{1,3}$/.test(q)?new RegExp('(^|[^a-z0-9_])'+q+'($|[^a-z0-9_])').test(text):text.includes(q);
  for(const entry of entries){
    const title=labSearchNormalize(entry.title),terms=entry.terms.map(labSearchNormalize);
    let score=title===q?200:contains(title)?90:terms.includes(q)?120:contains(entry.haystack)?30:tokens.length>1&&tokens.every(token=>entry.haystack.includes(token))?20:0;
    if(entry.kind==='lesson'&&entry.id===q)score+=200;
    if(entry.kind==='representation'&&terms.includes(q))score+=45;
    if(score)scored.push({entry,score});
  }
  return scored.sort((a,b)=>b.score-a.score);
}
function renderLabSearch(){
  const matches=rankLabSearch($('labSearchInput').value);LabSearch.results=matches.slice(0,12).map(item=>item.entry);LabSearch.active=0;
  $('labSearchCount').textContent=$('labSearchInput').value.trim()?'找到 '+matches.length+' 项'+(matches.length>12?'，显示前12项':''):'从这些基础开始，或输入遇到的概念';
  $('labSearchResults').innerHTML=LabSearch.results.length?LabSearch.results.map((entry,index)=>'<button type="button" role="option" tabindex="-1" id="lab-search-option-'+index+'" data-search-result="'+index+'" aria-selected="false"><span class="search-result-icon">'+labIcon(['api','project'].includes(entry.kind)?'code-xml':entry.kind==='math'?'calculator':'book-open')+'</span><span><small>'+esc(entry.group)+' · '+esc(entry.context)+'</small><strong>'+esc(entry.title)+'</strong><span class="search-result-description">'+esc(entry.description)+'</span></span><span class="search-result-enter" aria-hidden="true">↵</span></button>').join(''):'<p class="lab-search-empty">没有找到。试试“坐标系”“np.stack”等概念或函数名，也可以清空关键词查看入门课程。</p>';
  syncLabSearchSelection();
}
function syncLabSearchSelection(){
  const options=$('labSearchResults').querySelectorAll('[data-search-result]');
  options.forEach((button,index)=>button.setAttribute('aria-selected',String(index===LabSearch.active)));
  if(options.length)$('labSearchInput').setAttribute('aria-activedescendant',options[LabSearch.active].id);else $('labSearchInput').removeAttribute('aria-activedescendant');
}
function openLabSearch(){
  LabSearch.trigger=document.activeElement;LabSearch.navigating=false;$('labSearchInput').value='';renderLabSearch();$('labSearch').showModal();$('labSearchInput').focus();
}
function activateLabSearch(index){
  const entry=LabSearch.results[index];if(!entry)return;
  LabSearch.navigating=true;$('labSearch').close();
  if(entry.kind==='lesson'){if(LearningPath.view!=='course')setLearningView('course');openLearningLesson(entry.id);}
  else if(entry.kind==='representation'){if(LearningPath.view!=='course')setLearningView('course');openRepresentationRoute(entry.id);}
  else if(entry.kind==='math')openMathLearning(entry.id,$('labSearchTrigger'));
  else if(entry.kind==='project'){
    RobotProjectBridge.open[entry.lesson]=true;
    if(LearningPath.view!=='course')setLearningView('course');openLearningLesson(entry.lesson);
    requestAnimationFrame(()=>{
      if(LESSONS[current]?.id!==entry.lesson)return;
      const basics=$('robotBasics'),wasClosed=!basics.open;
      basics.open=true;
      basics.querySelector('[data-robot-tab="learn"]').click();
      const reveal=()=>{const card=$('robotProjectBridge')?.querySelector('[data-project-card="'+entry.card+'"]');if(card){card.open=true;card.tabIndex=-1;card.scrollIntoView({block:'start'});card.focus({preventScroll:true});}};
      const ready=()=>{const panel=$('robotProjectBridge');panel.addEventListener('toggle',()=>{if(panel.open)reveal()},{once:true});reveal();};
      if(wasClosed)basics.addEventListener('toggle',ready,{once:true});else ready();
    });
  }
  else{if(LearningPath.home)closeLearningMap();KnowledgeAtlas[entry.library]=entry.index;KnowledgeAtlas.line=0;KnowledgeAtlas.query='';KnowledgeAtlas.open(entry.library);$('learningAtlas').tabIndex=-1;$('learningAtlas').focus({preventScroll:true});}
}
function updateLabLiveStatus(){
  if(LabExperience.theme!=='live')return;
  const video=$('labLiveWallpaper'),state=video.dataset.playback,retry=['blocked','error'].includes(state);
  const note=LabExperience.reduced.matches?'系统减少动态：显示静态封面。':LabExperience.focus?'专注阅读：动态壁纸已暂停。':!LabExperience.motion?'已暂停，保留当前画面。':state==='error'?'视频未能加载，已显示封面；可以重试。':state==='blocked'?'浏览器尚未允许播放，点击“播放动态壁纸”继续。':state==='playing'?'循环动态壁纸正在播放；切到后台会暂停。':'正在准备动态壁纸…';
  $('labMotionNote').textContent=note;
  $('labLiveRetry').hidden=!retry||LabExperience.focus||LabExperience.reduced.matches;
  $('labSkyTitle').textContent=LIVE_WALLPAPER.title;
  $('labSkyTitle').nextElementSibling.textContent=note+' · Esc 返回';
  if(retry&&LabExperience.motion)$('labSkyPause').textContent=state==='error'?'重新加载':'点击播放';
}
function syncLabLiveWallpaper(){
  const video=$('labLiveWallpaper'),active=LabExperience.theme==='live';
  video.hidden=!active;$('labLiveRetry').hidden=true;
  if(!LIVE_WALLPAPER.video.url){video.hidden=true;return;}
  const running=active&&LabExperience.motion&&!LabExperience.focus&&!LabExperience.reduced.matches&&!document.hidden;
  if(!running){video.pause();updateLabLiveStatus();return;}
  if(video.dataset.playback==='error'){updateLabLiveStatus();return;}
  if(!video.hasAttribute('src'))video.src=LIVE_WALLPAPER.video.url;
  if(video.paused){
    video.dataset.playback='loading';
    video.play().catch(error=>{
      if(error.name==='AbortError'||LabExperience.theme!=='live'||!LabExperience.motion||LabExperience.focus||LabExperience.reduced.matches||document.hidden)return;
      video.dataset.playback=video.error?'error':'blocked';updateLabLiveStatus();
    });
  }
  updateLabLiveStatus();
}
function retryLabLiveWallpaper(){
  const video=$('labLiveWallpaper');if(video.error){video.dataset.playback='idle';video.load();}
  LabExperience.motion=true;applyLabAppearance(true);
}
function applyLabAppearance(persist=false){
  document.body.dataset.sky=LabExperience.theme;document.body.classList.toggle('lab-focus',LabExperience.focus);
  document.querySelectorAll('[data-sky-choice]').forEach(button=>button.setAttribute('aria-pressed',String(button.dataset.skyChoice===LabExperience.theme)));
  $('labMotion').checked=LabExperience.motion;$('labMotion').disabled=LabExperience.reduced.matches;$('labFocus').checked=LabExperience.focus;
  $('labMotionNote').textContent=LabExperience.reduced.matches?'系统已启用减少动态效果，当前保持静态。':LabExperience.theme==='film'?'电影原图缓缓漂移，叠加星光与鼠标视差；隐藏页面时暂停。画面可在图集中切换。':'双流星缓缓划过、光尾分离与云光浮动；隐藏页面时暂停。';
  if($('labSkyPause')){$('labSkyPause').textContent=LabExperience.motion?'暂停动态':'继续动态';$('labSkyPause').disabled=LabExperience.reduced.matches||LabExperience.focus;}
  if($('labSkyTitle')){$('labSkyTitle').textContent=LabExperience.theme==='studio'?'黄昏里的研究室':LabExperience.theme==='night'?'星海之上，流星经过':'城市入夜，流星经过';$('labSkyTitle').nextElementSibling.textContent=LabExperience.reduced.matches?'系统减少动态：当前静态天空 · Esc返回':LabExperience.focus?'专注阅读已暂停动态 · Esc返回':'原创动画风格场景 · Esc 回到学习';}
  applyFilmScene();
  syncLabLiveWallpaper();
  cancelAnimationFrame(LabExperience.frame);LabExperience.frame=0;LabExperience.lastFrame=0;
  const context=$('labAtmosphere').getContext('2d');if(context&&(LabExperience.focus||LabExperience.reduced.matches||document.hidden))context.clearRect(0,0,LabExperience.width,LabExperience.height);
  if(context&&LabExperience.motion&&!LabExperience.focus&&!LabExperience.reduced.matches&&!document.hidden)LabExperience.frame=requestAnimationFrame(drawLabAtmosphere);
  else{LabExperience.offset=[0,0];document.body.style.setProperty('--sky-x','0px');document.body.style.setProperty('--sky-y','0px');}
  if(persist)try{localStorage.setItem('geometryLabAppearance.v1',JSON.stringify({theme:LabExperience.theme,scene:FilmGallery.scene,motion:LabExperience.motion,focus:LabExperience.focus}))}catch{toast('当前外观可以使用，但未能保存在本机')}
}
function resizeLabAtmosphere(){
  const canvas=$('labAtmosphere'),ratio=Math.min(2,devicePixelRatio||1);LabExperience.width=innerWidth;LabExperience.height=innerHeight;
  canvas.width=Math.round(innerWidth*ratio);canvas.height=Math.round(innerHeight*ratio);canvas.style.width=innerWidth+'px';canvas.style.height=innerHeight+'px';
  canvas.getContext('2d')?.setTransform(ratio,0,0,ratio,0,0);applyLabAppearance();
}
function labMeteorGeometry(seconds,width,height){
  const phase=seconds%14,u=Math.min(1,phase/9),sky=Math.min(height*.72,width*.62);
  const alpha=Math.max(0,Math.min(1,phase/.8,(9-phase)/1.3)),split=Math.max(0,u-.28);
  const x=width*(.94-.68*u),y=height*.06+sky*(.08+.62*u);
  return [{x,y,alpha,color:'169,226,255'}, {x:x+width*(.018+split*.025),y:y+sky*(.018+split*.13),alpha:alpha*.85,color:'255,180,223'}];
}
function drawLabMeteors(ctx,seconds,width,height){
  const tail=width*.26,rise=Math.min(height*.32,width*.17);
  ctx.save();ctx.globalCompositeOperation='screen';
  for(const head of labMeteorGeometry(seconds,width,height)){
    if(head.alpha===0)continue;
    const {x,y,alpha,color}=head,gradient=ctx.createLinearGradient(x,y,x+tail,y-rise);
    gradient.addColorStop(0,'rgba('+color+','+alpha+')');gradient.addColorStop(.35,'rgba('+color+','+alpha*.38+')');gradient.addColorStop(1,'rgba('+color+',0)');
    for(const line of [10,2, .7]){ctx.lineWidth=line;ctx.globalAlpha=line===10?.17:1;ctx.strokeStyle=gradient;ctx.beginPath();ctx.moveTo(x,y);ctx.quadraticCurveTo(x+tail*.5,y-rise*.62,x+tail,y-rise);ctx.stroke();}
    ctx.globalAlpha=1;const glow=ctx.createRadialGradient(x,y,0,x,y,14);glow.addColorStop(0,'rgba(255,255,255,'+alpha+')');glow.addColorStop(.2,'rgba('+color+','+alpha*.8+')');glow.addColorStop(1,'rgba('+color+',0)');ctx.fillStyle=glow;ctx.beginPath();ctx.arc(x,y,14,0,Math.PI*2);ctx.fill();
    ctx.fillStyle='rgba(255,255,255,'+alpha+')';ctx.beginPath();ctx.arc(x,y,1.8,0,Math.PI*2);ctx.fill();
  }
  ctx.restore();
}
function drawLabAtmosphere(time){
  const e=LabExperience;if(document.hidden||!e.motion||e.focus||e.reduced.matches){e.frame=0;return;}
  e.frame=requestAnimationFrame(drawLabAtmosphere);if(time-e.lastFrame<33)return;e.elapsed+=e.lastFrame?Math.min(.1,(time-e.lastFrame)/1000):0;e.lastFrame=time;
  if(e.startedAt===null)e.startedAt=time;
  const ctx=$('labAtmosphere').getContext('2d'),w=e.width,h=e.height,t=e.elapsed;ctx.clearRect(0,0,w,h);
  const count=w<600?18:42,warm=e.theme==='studio';
  if(!warm){for(let i=0;i<3;i++){const x=w*(.12+i*.37)+Math.sin(t*.035+i)*w*.025,y=h*(.22+i*.08),radius=w*.28;const cloud=ctx.createRadialGradient(x,y,0,x,y,radius);cloud.addColorStop(0,'rgba(219,175,239,'+(.028+.012*Math.sin(t*.08+i))+')');cloud.addColorStop(1,'rgba(219,175,239,0)');ctx.fillStyle=cloud;ctx.fillRect(x-radius,y-radius,radius*2,radius*2);}}
  for(let i=0;i<count;i++){
    const x=((i*.61803398875)%1)*w+Math.sin(t*.12+i)*9,y=(((i*.41421356237)%1)*h-t*(warm?3:1.2)+h*100)%h;
    const alpha=.16+.22*(.5+.5*Math.sin(t*.55+i*2));ctx.fillStyle=warm?'rgba(255,221,174,'+alpha+')':'rgba(207,231,255,'+alpha+')';ctx.beginPath();ctx.arc(x,y,i%4===0?1.6:.8,0,Math.PI*2);ctx.fill();
  }
  if(!warm&&(e.theme!=='live'||!LIVE_WALLPAPER.video.url)&&(e.theme!=='film'||FilmGallery.scene==='stairs'))drawLabMeteors(ctx,t,w,h);
  const drift=[Math.sin(t*.28)*8,Math.sin(t*.17)*5];
  e.offset=e.offset.map((value,index)=>value+(e.pointer[index]+drift[index]-value)*.08);document.body.style.setProperty('--sky-x',e.offset[0].toFixed(2)+'px');document.body.style.setProperty('--sky-y',e.offset[1].toFixed(2)+'px');
}
