const PEDAGOGY_LEVELS=['观察','计算','核对','项目'];
const PEDAGOGY_HEADINGS={transform:'用 W 和 L 读同一个点',urdfload:'从关节角到末端',frames:'从像素到机器人基座'};
const pedOptions=items=>items.map(([value,text])=>'<option value="'+esc(value)+'">'+esc(text)+'</option>').join('');
