function syncProductTrace(frame,frames){
  if(!ProductPreview.enabled)return;
  ProductPreview.trace=frame?productFrameRecord(frame,frames):null;
  if(document.activeElement!==$('productFrameNumber'))$('productFrameNumber').value=Math.floor(state.frame);
  $('productReplayObject').value=state.object??'tool0';
  renderProductTraceStep();
}
function renderProductTraceStep(){
  const node=$('productTraceValues'),d=ProductPreview.trace,step=ProductPreview.traceStep;
  if(!node)return;
  if(!d){node.textContent='未评估 · 该帧没有可用记录。';return;}
  for(const b of $('productWorkbench').querySelectorAll('[data-product-trace]'))b.setAttribute('aria-pressed',String(Number(b.dataset.productTrace)===step));
  const point=p=>p?vec(p,6):'未评估 · 缺当前帧回算输入';
  const residual=(v,status)=>v===null?'未评估':v.toExponential(3)+' · '+(status==='passed'?'回算一致':'回算不一致');
  const rows=[
    [['源记录 · CSV',d.source],['帧 / 审阅时间',d.frame+' / '+fmt(d.reviewTimeSeconds,3)+' s'],['关节角 q / rad',d.qRad?vec(d.qRad,5):'未评估 · 缺该帧关节状态'],
      ['请求 tool0 / 世界 m',d.poses.requested.worldFromTool0?vec(PM.pos(d.poses.requested.worldFromTool0),6):'原包未提供'],
      ['请求含义',d.poses.requested.meaning==='reused_prefix_saved_fk_as_current_request'?'沿用上一轮 FK；不是最初解析目标':d.requestedComparison.status==='compared'?'本轮保存的请求，不是测量位姿':'未核验']],
    [['输入帧',String(d.frame)],['方法','原包 URDF 的正运动学，带场景基座校准'],['回算 tool0 / 世界 m',point(d.calculatedToolPositionM)]],
    [['记录 tool0 / 世界 m',point(d.storedToolPositionM)],['回算 tool0 / 世界 m',point(d.calculatedToolPositionM)],
      ['位置残差 / m',residual(d.positionResidualM,d.checks.position)],
      ['姿态残差 / rad',residual(d.orientationResidualRad,d.checks.orientation)],
      ['相对请求的差',d.requestedComparison.status==='compared'?d.requestedComparison.positionM.toExponential(3)+' m / '+d.requestedComparison.orientationRad.toExponential(3)+' rad · 未验收':'未核验'],
      ['待核验','请求验收、实机 TCP、完整碰撞、动力学与实机跟踪']]
  ][step];
  const markup=productRows(rows);
  if(node.innerHTML!==markup)node.innerHTML=markup;
}

