const defaultView=()=>({yaw:LESSONS[current]?.id==='camera'?.55:-.95,pitch:LESSONS[current]?.id==='camera'?.42:.52,zoom:LESSONS[current]?.id==='camera'?.95:LESSONS[current]?.id==='mujoco'?1:LESSONS[current]?.id==='order'?1.2:1.4,panX:0,panY:0});
let current=0,state={},playing=false,selectedTab='theory',lastTime=0,animTime=0,toastTimer;
const canvas=$('scene'),ctx=canvas.getContext('2d');
const view={yaw:-.95,pitch:.52,zoom:1};let width=1,height=1,drawList=[],projectionInfo=null,labelLayoutState=null;
let center=[0,0,.45],sceneScale=1;
function project(p){const d=G.sub(p,center),right=[-Math.sin(view.yaw),Math.cos(view.yaw),0],up=[-Math.sin(view.pitch)*Math.cos(view.yaw),-Math.sin(view.pitch)*Math.sin(view.yaw),Math.cos(view.pitch)],eye=[Math.cos(view.pitch)*Math.cos(view.yaw),Math.cos(view.pitch)*Math.sin(view.yaw),Math.sin(view.pitch)],k=Math.min(width/5.8,height/3.9)*view.zoom*sceneScale;return [width*.5+(view.panX||0)+k*G.dot(d,right),height*.53+(view.panY||0)-k*G.dot(d,up),G.dot(d,eye)]}
function line(a,b,color=C.dim,w=1,dash=false){drawList.push({kind:'line',points:[a,b],color,w,dash})}
function polygon(points,color,stroke){drawList.push({kind:'polygon',points,color,stroke})}
function dot(p,color=C.gold,r=4){drawList.push({kind:'dot',points:[p],color,r})}
function label(p,text,color='#b9cbe2',dx=5,dy=-7){drawList.push({kind:'label',points:[p],color,text,dx,dy})}
function arrow(a,b,color,w=2,labelText){line(a,b,color,w);drawList.push({kind:'arrow',points:[a,b],color,w});if(labelText)label(b,labelText,color)}
function triad(p,R=G.I(),size=.65,prefix='',faded=false){[C.x,C.y,C.z].forEach((c,i)=>{const q=G.add(p,G.scale(R.map(r=>r[i]),size));arrow(p,q,faded?'#4e627e':c,faded?1:2,prefix+['X','Y','Z'][i])});dot(p,faded?'#4e627e':'#b9c9de',2)}
function cube(p,R=G.I(),s=.65,color=C.gold,wire=false){const v=[];for(let z of [-1,1])for(let y of [-1,1])for(let x of [-1,1])v.push(G.add(p,G.mv(R,[x*s/2,y*s/2,z*s/2])));const faces=[[0,1,3,2],[4,6,7,5],[0,4,5,1],[2,3,7,6],[0,2,6,4],[1,5,7,3]];if(!wire)faces.forEach((f,i)=>polygon(f.map(j=>v[j]),color+['35','52','2e','44','30','48'][i],color+'75'));[[0,1],[0,2],[0,4],[1,3],[1,5],[2,3],[2,6],[3,7],[4,5],[4,6],[5,7],[6,7]].forEach(([i,j])=>line(v[i],v[j],color,wire?1.5:1,wire));}
function circle(c,u,v,r,color,dash=false){let prev;for(let i=0;i<=72;i++){const a=i*Math.PI/36,p=G.add(c,G.add(G.scale(u,r*Math.cos(a)),G.scale(v,r*Math.sin(a))));if(prev)line(prev,p,color,1,dash);prev=p}}
function gripper(p,R,color=C.gold,forward=-1){const at=v=>G.add(p,G.mv(R,v));const a=[[-.17,0,-forward*.12],[.17,0,-forward*.12]],b=[[-.17,0,forward*.12],[.17,0,forward*.12]];line(at(a[0]),at(a[1]),color,5);for(let i=0;i<2;i++)line(at(a[i]),at(b[i]),color,4);line(at([0,0,-forward*.12]),at([0,0,-forward*.31]),color,6);dot(p,color,3)}
function worldGrid(){for(let i=-4;i<=4;i++){const a=i*.5;line([-2,a,0],[2,a,0],i===0?'#384d69':'#25364e',1);line([a,-2,0],[a,2,0],i===0?'#384d69':'#25364e',1)}triad([0,0,0],G.I(),.85,'W·',true)}
function paint(){
  renderSceneOrientation();
  ctx.clearRect(0,0,width,height);drawList.sort((a,b)=>a.points.reduce((s,p)=>s+project(p)[2],0)/a.points.length-b.points.reduce((s,p)=>s+project(p)[2],0)/b.points.length);
  const labels=[];
  for(const o of drawList){
    const p=o.points.map(project);ctx.strokeStyle=o.color;ctx.fillStyle=o.color;ctx.lineWidth=o.w||1;ctx.setLineDash(o.dash?[5,4]:[]);
    if(o.kind==='line'){ctx.beginPath();ctx.moveTo(...p[0].slice(0,2));ctx.lineTo(...p[1].slice(0,2));ctx.stroke()}
    else if(o.kind==='polygon'){ctx.beginPath();p.forEach((q,i)=>i?ctx.lineTo(q[0],q[1]):ctx.moveTo(q[0],q[1]));ctx.closePath();ctx.fill();if(o.stroke){ctx.strokeStyle=o.stroke;ctx.stroke()}}
    else if(o.kind==='dot'){ctx.beginPath();ctx.arc(p[0][0],p[0][1],o.r,0,Math.PI*2);ctx.fill()}
    else if(o.kind==='arrow'){const a=p[0],b=p[1],angle=Math.atan2(b[1]-a[1],b[0]-a[0]),n=7;ctx.beginPath();ctx.moveTo(b[0],b[1]);ctx.lineTo(b[0]-n*Math.cos(angle-.4),b[1]-n*Math.sin(angle-.4));ctx.moveTo(b[0],b[1]);ctx.lineTo(b[0]-n*Math.cos(angle+.4),b[1]-n*Math.sin(angle+.4));ctx.stroke()}
    else labels.push([o,p[0]]);
  }
  ctx.setLineDash([]);ctx.font='13px "Microsoft YaHei",sans-serif';
  const reserved=projectionInfo?[{x:$('projection').offsetLeft,y:$('projection').offsetTop,w:$('projection').offsetWidth,h:$('projection').offsetHeight}]:[];
  for(const id of ['sceneOrientation','viewCaption','legend','viewerReadout','rigidReadoutPreview']){const node=$(id);if(node&&!node.hidden&&node.offsetWidth&&node.offsetHeight)reserved.push({x:node.offsetLeft,y:node.offsetTop,w:node.offsetWidth,h:node.offsetHeight});}
  labelLayoutState=CanvasLabelLayout.place(labels.map(([o,p])=>({...o,x:p[0],y:p[1],w:ctx.measureText(o.text).width,priority:/^(P·|J0·|C·|axis_W|末端|TCP|p_W)/.test(o.text)?2:o.color===C.gold||o.color===C.white?1:o.color==='#4e627e'?-1:0})),width,height,reserved);
  for(const o of labelLayoutState.placed){
    if(o.leader){ctx.globalAlpha=.5;ctx.lineWidth=1;ctx.strokeStyle=o.color;ctx.beginPath();ctx.moveTo(...o.anchor);ctx.lineTo(...o.leader);ctx.stroke();ctx.globalAlpha=1}
    ctx.fillStyle=o.color;ctx.lineWidth=3;ctx.strokeStyle='#111b2be0';ctx.strokeText(o.text,o.x,o.y);ctx.fillText(o.text,o.x,o.y);
  }
  if(projectionInfo)paintImage(projectionInfo);
}
