function setCode(s){$('code').textContent=s}
function render(){if(current===LESSONS.length)return;drawList=[];projectionInfo=null;const l=LESSONS[current],s=state;syncSceneOrientation(l.id);$('lab').classList.toggle('extension-lesson',EXTENSION_LESSONS.some(x=>x.id===l.id));renderInpaintingLab(l.id);syncContactLoop(l.id);projectFocus(l.id);syncRigidMathLesson(l.id);syncRGBD(l.id);syncHandCode(l.id);syncJointCodeLab(l.id);syncScene2Reading(l.id);syncKnowledgeAtlas(l.id);{const guided=renderBasicWalkthrough(l,s);syncTimeLawStudy(l.id);syncInterpolationStudy(l.id);syncProductPreviewLesson(l.id);if(guided)return;}$('rotationFoundations').classList.toggle('hidden',l.id!=='rotation');$('pointDirectionDetails').classList.toggle('hidden',l.id!=='transform');renderNotationGuide(l.id,s);renderLearningPractice(l.id);const mj=l.id==='mujoco';$('mjTools').classList.toggle('hidden',!mj);$('mujocoCanvas').classList.toggle('hidden',!mj);canvas.style.visibility=mj?'hidden':'';if(l.id==='contactloop'){renderContactLoop(s);return}if(l.id==='rigidmath'){renderRigidMath();return}if(l.id==='rgbdbackground'){renderRGBD();return}if(mj){$('projection').style.display='none';$('viewCaption').textContent='MuJoCo · 本地物理 / 原模型单位';$('controlUnits').textContent='m · rad · s';if(renderMujocoLab(l,s))return}if(PROJECT_LESSONS.some(p=>p.id===l.id)){projectGrid();const gridEnd=drawList.length;renderProject(l,s);fitProjectView(drawList.slice(gridEnd));$('projection').style.display='none';paint();return}setProjectSources([]);worldGrid();if(renderExtensionLesson(l,s)){paint();return}let M,p,q,A,B,r;
  switch(l.id){
  case 'rotation':
    renderRotationLesson(s);break;
  case 'order':
    A=G.mm(G.ry(G.rad(s.beta)),G.rz(G.rad(s.alpha)));B=G.mm(G.rz(G.rad(s.alpha)),G.ry(G.rad(s.beta)));for(const [pos,R,col,caption] of [[[-1.2,0,.55],A,C.gold,'A · 绕世界 Y'],[[1.2,0,.55],B,C.purple,'B · 绕自身 Y']]){cube(pos,R,.65,col);triad(pos,R,.8);triad(pos,G.rz(G.rad(s.alpha)),.65,'',true);label(G.add(pos,[0,0,.85]),caption,col,-55,-5)}matrix('R_A =',A);stats([['A 与 B 的相对旋转角',fmt(G.angle(A,B),2)+'°'],['A · ex',vec(G.mv(A,[1,0,0]))],['B · ex',vec(G.mv(B,[1,0,0]))]]);live(G.angle(A,B)<.01?'这组参数恰好得到相同朝向。增大两个角，观察一般情况下的差异。':'两个物体的初始朝向和角度相同，区别只有第二次旋转所用的坐标系。');legend([['世界轴增量',C.gold],['自身轴增量',C.purple]]);setCode(pythonBase+`rz = R.from_euler('z', ${s.alpha}, degrees=True)\nry = R.from_euler('y', ${s.beta}, degrees=True)\nworld_y = ry * rz  # 新增量左乘，固定世界 Y\nbody_y = rz * ry   # 新增量右乘，当前局部 Y\n# SciPy 中 r2 * r1：先 r1，再 r2\nprint(world_y.as_matrix())\nprint(body_y.as_matrix())`);break;
  case 'transform':
    renderPointDirectionLesson(s);break;
  case 'axis':
    p=[s.nx,s.ny,s.nz];if(G.norm(p)<1e-9){matrix('R =',G.I());stats([['状态','INVALID：零轴'],['画面','单位姿态占位，不是有效轴角结果']]);live('轴方向为零，无法归一化。请至少增大一个分量；不生成四元数或有效旋转。',true);cube([0,0,.5],G.I(),.7,C.dim,true);setCode(pythonBase+'axis = np.array([0.0, 0.0, 0.0])\nif np.linalg.norm(axis) < 1e-10:\n    raise ValueError("旋转轴不能是零向量")');break}p=G.unit(p);M=G.rod(p,G.rad(s.theta));q=G.axisQ(p,G.rad(s.theta));r=s.layout==='xyzw'?q:[q[3],...q.slice(0,3)];arrow(G.add([0,0,.5],G.scale(p,-1.2)),G.add([0,0,.5],G.scale(p,1.4)),C.purple,3,'n̂');circle([0,0,.5],G.unit(G.cross(p,Math.abs(p[2])<.9?[0,0,1]:[0,1,0])),G.unit(G.cross(p,G.cross(p,Math.abs(p[2])<.9?[0,0,1]:[0,1,0]))),.85,C.dim,true);cube([0,0,.5],G.I(),.7,C.dim,true);cube([0,0,.5],M,.7);triad([0,0,.5],M,.8);matrix('R =',M);stats([['n̂',vec(p)],['q · '+s.layout,vec(r)],['‖q‖ / det(R)',fmt(G.norm(q),6)+' / '+fmt(G.det(M),6)]]);live('q 与 −q 的矩阵完全相同。切换显示布局只会重排数字，不会改变三维朝向。');legend([['旋转轴',C.purple],['旋转后姿态',C.gold]]);setCode(pythonBase+`axis = np.array(${vec([s.nx,s.ny,s.nz])})\nif np.linalg.norm(axis) < 1e-10:\n    raise ValueError("旋转轴不能是零向量")\naxis /= np.linalg.norm(axis)\nrot = R.from_rotvec(axis * np.deg2rad(${s.theta}))\nq_xyzw = rot.as_quat()\nq_wxyz = q_xyzw[[3, 0, 1, 2]]\nassert np.allclose(R.from_quat(-q_xyzw).as_matrix(), rot.as_matrix())`);break;
  case 'hinge':
    M=G.rx(G.rad(s.theta));const c=[0,0,.35],p0=[.3,s.contact,.35],d0=[0,0,s.gap];p=G.hinge(p0,c,M);q=G.add(p,G.mv(M,d0));const corners=[[-.7,0,.35],[.7,0,.35],[.7,1.1,.35],[-.7,1.1,.35]];polygon(corners,'#647c9e13','#647c9e50');polygon(corners.map(v=>G.hinge(v,c,M)),C.y+'22',C.y+'90');line([-.95,0,.35],[.95,0,.35],C.purple,5);label([-.95,0,.35],'铰链 · 世界 X',C.purple);circle([.3,0,.35],[0,1,0],[0,0,1],s.contact,'#6b93a566',true);dot(c,C.purple,4);dot(p,C.y,6);label(p,'接触材料点',C.y,-92,-13);line(p,q,C.gold,2);gripper(q,M);triad(q,M,.42,'T·');label(q,'TCP',C.gold,5,17);if(s.ghost==='yes'){dot(p0,'#ff7c8277',6);line(p0,p,'#ff7c8277',1,true);label(p0,'固定旧点（错误）',C.x,7,18)}matrix('R_door =',M);stats([['p_contact',vec(p)],['p_TCP',vec(q)],['材料点到铰链轴 / TCP 间距',fmt(G.norm(G.sub(p,[.3,0,.35])))+' / '+fmt(G.norm(G.sub(q,p)))+' m']]);live('门抬起时，绿色点保持在门上同一位置，橙色夹爪的位置偏置与朝向都随门旋转。');legend([['材料点 / 门',C.y],['夹爪 / TCP',C.gold]]);setCode(pythonBase+`c = np.array([0.0, 0.0, 0.35])\np0 = np.array([0.3, ${fmt(s.contact)}, 0.35])\nd0 = np.array([0.0, 0.0, ${fmt(s.gap)}])\nrot = R.from_rotvec(np.array([1., 0., 0.]) * np.deg2rad(${s.theta}))\np_contact = c + rot.apply(p0 - c)\np_tcp = p_contact + rot.apply(d0)\nrot_gripper_0 = R.identity()  # 本例的初始夹爪姿态\nrot_gripper = rot * rot_gripper_0\n# 仅刚体几何关系，不含接触、IK、碰撞检查`);break;
  case 'tcp':
    M=G.euler(0,s.pitch,s.yaw);p=[.3,.15,.95];const direction=G.mv(M,[0,0,1]);q=G.sub(p,G.scale(direction,s.distance));r=G.sub(p,G.mv(M,[0,0,s.length]));const wrong=G.sub(p,[0,0,s.distance]);triad(p,M,.7,'T·');gripper(p,M,C.gold,1);dot(p,C.gold,6);label(p,'目标 TCP',C.gold,8,-12);dot(q,C.y,5);label(q,'正确预抓取点',C.y,-90,18);arrow(q,p,C.y,3);dot(wrong,C.purple,5);line(wrong,p,C.purple,2,true);label(wrong,'世界 −Z 退让（对照）',C.purple,10,18);dot(r,C.white,5);line(r,p,C.white,4);label(r,'法兰 F',C.white,-50,0);cube(r,M,.17,C.white,true);matrix('R_WT =',M);stats([['工具 +Z 在世界中',vec(direction)],['预抓取 p_pre',vec(q)],['法兰 p_flange',vec(r)]]);live('旋转工具后，绿色接近路径与工具 Z 同向。紫色路径始终平行世界 Z，不是同一个指令。');legend([['局部轴接近',C.y],['固定世界轴对照',C.purple]]);setCode(pythonBase+`rot = R.from_euler('xyz', [0, ${s.pitch}, ${s.yaw}], degrees=True)\np_tcp = np.array([0.3, 0.15, 0.95])\na_world = rot.apply([0.0, 0.0, 1.0])\np_pre = p_tcp - ${fmt(s.distance)} * a_world\np_flange = p_tcp - rot.apply([0.0, 0.0, ${fmt(s.length)}])\n# 本例 TCP 与法兰朝向相同；真实工具需使用标定 T_FT\n# T_WT = T_WF @ T_FT，故 T_WF = T_WT @ inv(T_FT)`);break;
  case 'interpolation':
    const t=s.t,b=s.blend,u=b==='linear'?t:b==='cubic'?3*t*t-2*t*t*t:10*t**3-15*t**4+6*t**5;A=G.euler(0,0,s.yaw0);B=G.euler(0,s.pitch1,s.yaw1);M=G.qmat(G.slerp(G.matq(A),G.matq(B),u));const E=G.euler(0,s.pitch1*u,s.yaw0+(s.yaw1-s.yaw0)*u),start=[-1,-.5,.3],end=[1,.5,1.3];p=G.add(G.scale(start,1-u),G.scale(end,u));line(start,end,C.dim,2,true);cube(start,A,.35,C.dim,true);cube(end,B,.35,C.dim,true);label(start,'起点',C.white,-35,20);label(end,'终点',C.white,7,-12);cube(p,M,.62,C.gold);cube(p,E,.77,C.purple,true);triad(p,M,.7);arrow(p,G.add(p,G.scale(M.map(row=>row[0]),.9)),C.gold,3,'X · SLERP');arrow(p,G.add(p,G.scale(E.map(row=>row[0]),.9)),C.purple,2,'X · Euler');dot(p,C.gold,4);matrix('R_slerp =',M);stats([['归一化时间 τ / 路径进度 s',fmt(t)+' / '+fmt(u)],['端点最短相对旋转',fmt(G.angle(A,B),2)+'°'],['SLERP 与 Euler 的朝向差',fmt(G.angle(M,E),2)+'°']]);live(Math.abs(s.yaw1-s.yaw0)>180?'跨越角度边界：紫色逐分量插值可能绕大圈；橙色沿最短旋转弧。':'比较两种朝向路径。即使端点一样，中间的朝向也未必一样。');legend([['SLERP',C.gold],['Euler 插值',C.purple]]);setCode(pythonBase+`from scipy.spatial.transform import Slerp\n\nt = ${t}  # normalized time, not seconds\ns = ${b==='linear'?'t':b==='cubic'?'3*t**2 - 2*t**3':'10*t**3 - 15*t**4 + 6*t**5'}\nrot_keys = R.from_euler('xyz', [[0, 0, ${s.yaw0}], [0, ${s.pitch1}, ${s.yaw1}]], degrees=True)\nrot_now = Slerp([0, 1], rot_keys)(s)\np0 = np.array([-1., -0.5, 0.3])\np1 = np.array([1., 0.5, 1.3])\np_now = (1-s)*p0 + s*p1\n# s(t) 改变时间分配；不能代替碰撞或执行可行性检查`);renderInterpolationStudy({t,u,A,B,M,E,start,end,p});break;
  case 'camera':
    const target=[0,.25,.5],az=G.rad(s.az),el=G.rad(s.el),cam=G.add(target,[3*Math.cos(el)*Math.cos(az),3*Math.cos(el)*Math.sin(az),3*Math.sin(el)]);M=G.camera(cam,target);A=G.inverse(M);const chapterInput=productCameraInput();p=chapterInput?.artifact.outputs.pointW??[s.px,.25,s.pz];q=G.point(A,p);const Rwc=M.slice(0,3).map(v=>v.slice(0,3)),at=v=>G.point(M,v),z=.8,corners2=[[-160*z/s.f,-120*z/s.f,z],[160*z/s.f,-120*z/s.f,z],[160*z/s.f,120*z/s.f,z],[-160*z/s.f,120*z/s.f,z]],cornersW=corners2.map(at);polygon(cornersW,'#7cafff14',C.z);for(const v of cornersW)line(cam,v,C.z,1);cube(cam,Rwc,.18,C.z);triad(cam,Rwc,.55,'C·');label(cam,'相机 C',C.z,8,-20);dot(p,C.gold,6);label(p,'世界点 P',C.gold);line(cam,p,C.gold,1.5,true);dot(target,C.white,3);const uv=q[2]>.0001?[s.f*q[0]/q[2]+160,s.f*q[1]/q[2]+120]:null;projectionInfo={uv,p:q};productCameraReadout(chapterInput,q,uv,M,s.f);pedagogyCaptureCamera(uv,q,M,s.f,chapterInput?.kind??'camera_lesson');matrix('T_CW =',A);stats([['p_C',vec(q)],['像素 (u,v)',uv?vec(uv,1)+' px':'不可投影：Z_C ≤ 0'],['图像状态',!uv?'相机后方':uv[0]>=0&&uv[0]<320&&uv[1]>=0&&uv[1]<240?'图像内':'视野外']]);live('三维视图可自由拖动；相机水平角、仰角和焦距会改变投影。相机 Y 向下、Z 向前。');legend([['相机 / 视锥',C.z],['世界点',C.gold]]);setCode(pythonBase+`# T_WC 是相机在世界中的位姿；以下为当前数值\nT_WC = np.array(${JSON.stringify(M.map(row=>row.map(x=>+fmt(x,8))))})\np_world = np.array(${JSON.stringify([...p,1])})\np_camera = (np.linalg.inv(T_WC) @ p_world)[:3]\nfx = fy = ${s.f}\ncx, cy = 160.0, 120.0\nif p_camera[2] <= 0:\n    raise ValueError("点在相机后方，不做可见投影")\nu = fx * p_camera[0] / p_camera[2] + cx\nv = fy * p_camera[1] / p_camera[2] + cy\n# 还需检测 0 <= u < 320、0 <= v < 240；本例不考虑畸变`);break;
  case 'vectors':
    p=[s.nx,s.ny,s.nz];
    if(G.norm(p)<1e-9){matrix('R =',G.I());stats([['状态','INVALID：零法线'],['画面','无有效接触坐标系']]);live('法线长度为零，无法构造接触基。先检查输入，不要加一个极小数后继续当作有效法线。',true);setCode(pythonBase+'normal = np.array([0., 0., 0.])\nif np.linalg.norm(normal) < 1e-10:\n    raise ValueError("接触法线不能为零")');break}
    p=G.unit(p);M=G.basis(p);
    const tdir=M.map(row=>row[0]),bdir=M.map(row=>row[1]),v=[1,.6,s.vz],vp=G.scale(p,G.dot(v,p)),vt=G.sub(v,vp);
    const vAngle=G.deg(Math.acos(Math.max(-1,Math.min(1,G.dot(v,p)/G.norm(v)))));
    polygon([[-1,-1],[1,-1],[1,1],[-1,1]].map(([a,b])=>G.add(G.scale(tdir,a),G.scale(bdir,b))),'#72d5b212','#72d5b244');
    arrow([0,0,0],p,C.z,3,'n̂');arrow([0,0,0],tdir,C.x,2,'t');arrow([0,0,0],bdir,C.y,2,'b');arrow([0,0,0],v,C.gold,3,'v');arrow([0,0,0],vp,C.purple,3,'v_normal');line(vp,v,C.white,2,true);label(G.add(vp,G.scale(vt,.5)),'v_tangent',C.white);
    matrix('R_contact =',M);stats([['v · n̂（带符号）',fmt(G.dot(v,p))],['v 与 n̂ 的夹角',fmt(vAngle,1)+'°'],['det / 正交误差',fmt(G.det(M),6)+' / '+G.orthoError(M).toExponential(1)]]);
    live(Math.abs(p[2])>.9?'法线接近世界 Z，自动改用 Y 辅助轴构造切线，避免平行叉积为零。':'切向 t、b 和法线 n̂ 组成右手基。改变法线时，注意辅助轴切换处切线可能跳变。');legend([['原向量 v',C.gold],['法向分量',C.purple]]);
    setCode(pythonBase+`normal = np.array(${vec([s.nx,s.ny,s.nz])})\nif np.linalg.norm(normal) < 1e-10:\n    raise ValueError("法线不能为零")\nn = normal / np.linalg.norm(normal)\na = np.array([0., 0., 1.]) if abs(n[2]) < 0.9 else np.array([0., 1., 0.])\nt = np.cross(a, n)\nt /= np.linalg.norm(t)\nb = np.cross(n, t)\nR_contact = np.column_stack([t, b, n])\nv = np.array([1., 0.6, ${fmt(s.vz)}])\nv_normal = np.dot(v, n) * n\nv_tangent = v - v_normal`);break;
  }
  drawNotationGuide(l.id,s);$('projection').style.display=l.id==='camera'?'block':'none';paint();
}
function paintImage({uv,p}){
  const inside=uv&&uv[0]>=0&&uv[0]<320&&uv[1]>=0&&uv[1]<240;
  const output=$('imagePlaneReadout'), text=uv?'像素 '+vec(uv,1)+' px · Z '+fmt(p[2],2)+' m'+(inside?'':' · 图像外'):'未投影 · Z '+fmt(p[2],2)+' m';
  if(output.textContent!==text)output.textContent=text;
  const c=$('imagePlane'),g=c.getContext('2d');g.fillStyle='#101b2b';g.fillRect(0,0,320,240);g.lineWidth=1;g.strokeStyle='#283d59';for(let i=0;i<=320;i+=40){g.beginPath();g.moveTo(i,0);g.lineTo(i,240);g.stroke()}for(let i=0;i<=240;i+=40){g.beginPath();g.moveTo(0,i);g.lineTo(320,i);g.stroke()}g.strokeStyle='#7186a3';g.beginPath();g.moveTo(160,0);g.lineTo(160,240);g.moveTo(0,120);g.lineTo(320,120);g.stroke();g.font='17px Consolas,monospace';g.fillStyle=C.white;g.fillText('u →',260,22);g.fillText('v ↓',6,225);if(inside){g.fillStyle=C.gold;g.beginPath();g.arc(...uv,8,0,Math.PI*2);g.fill()}else{g.fillStyle=C.x;g.font='18px "Microsoft YaHei",sans-serif';g.fillText(p[2]<=0?'点在相机后方':'点超出图像边界',65,108);if(uv){g.fillStyle=C.gold;g.beginPath();g.arc(Math.max(7,Math.min(313,uv[0])),Math.max(7,Math.min(233,uv[1])),6,0,Math.PI*2);g.fill()}}}
function buildControls(){const l=LESSONS[current];$('controls').innerHTML=l.controls.map(c=>c.options?'<div class="control"><label for="c-'+c.key+'">'+c.label+'</label><select id="c-'+c.key+'" data-key="'+c.key+'">'+c.options.map(([v,n])=>'<option value="'+esc(v)+'" '+(v===state[c.key]?'selected':'')+'>'+esc(n)+'</option>').join('')+'</select></div>':'<div class="control"><label for="c-'+c.key+'">'+c.label+'<output class="value" id="v-'+c.key+'">'+displayValue(c,state[c.key])+'</output></label><input id="c-'+c.key+'" data-key="'+c.key+'" type="range" min="'+c.min+'" max="'+c.max+'" step="'+c.step+'" value="'+state[c.key]+'" aria-label="'+c.label+'"></div>').join('');$('controls').querySelectorAll('input,select').forEach(el=>el.addEventListener('input',()=>{stopPlay();state[el.dataset.key]=el.tagName==='SELECT'?el.value:Number(el.value);syncControls();render()}));$('presets').innerHTML=l.presets.map(([name],i)=>'<button data-preset="'+i+'">'+name+'</button>').join('');$('presets').querySelectorAll('button').forEach(el=>el.addEventListener('click',()=>{stopPlay();Object.assign(state,l.presets[+el.dataset.preset][1]);syncControls();render()}));$('controlNote').textContent=l.note;}
function displayValue(c,v){return fmt(v,c.step<.01?3:c.step<1?2:0)+(c.unit||'')}
function syncControls(){for(const c of LESSONS[current].controls){$('c-'+c.key).value=state[c.key];if(!c.options)$('v-'+c.key).textContent=displayValue(c,state[c.key])}}
function stopPlay(){playing=false;$('play').textContent='▶ 播放变化'}
function setLesson(i,reset=false){if(!reset&&!LearningPath.standalone)productReplayCapture();showLearningShell(null);if(LearningPath.ready){LearningPath.hasLesson=true;LearningPath.home=false;document.body.classList.remove('course-home');$('learningMap').hidden=true;$('openLearningMap').removeAttribute('aria-current')}if(i!==current)$('viewerReadout').open=false;current=Math.max(0,Math.min(LESSONS.length,i));stopPlay();Object.assign(view,defaultView());const quiz=current===LESSONS.length;$('lab').style.display=quiz?'none':'block';$('quiz').style.display=quiz?'block':'none';$('nav').querySelectorAll('button').forEach((b,j)=>{b.classList.toggle('active',j===current);if(j===current){b.setAttribute('aria-current','page');if(innerWidth<=850)$('nav').scrollLeft=b.offsetLeft-$('nav').offsetLeft-($('nav').clientWidth-b.clientWidth)/2;else b.scrollIntoView({block:'nearest'})}else b.removeAttribute('aria-current')});$('lessonIndex').textContent=quiz?'CHECK YOUR UNDERSTANDING':String(current+1).padStart(2,'0')+' / '+LESSONS[current].en;$('lessonStep').textContent=quiz?'Q/A':String(current+1).padStart(2,'0');$('title').textContent=quiz?'把直觉，变成可以解释的答案。':LESSONS[current].title;$('subtitle').textContent=quiz?'8 个常见问题。先独立作答，再看解释；不计时、不上传。':LESSONS[current].sub;syncRobotBasics(quiz?'quiz':LESSONS[current].id);syncFormulaLens(quiz?'quiz':LESSONS[current].id);syncRGBD(quiz?'quiz':LESSONS[current].id);syncHandCode(quiz?'quiz':LESSONS[current].id);syncJointCodeLab(quiz?'quiz':LESSONS[current].id);syncScene2Reading(quiz?'quiz':LESSONS[current].id);syncKnowledgeAtlas(quiz?'quiz':LESSONS[current].id);syncContextHints(quiz?'quiz':LESSONS[current].id);syncIKResearch(quiz?'quiz':LESSONS[current].id);syncResearchPractice(quiz?'quiz':LESSONS[current].id);syncMathLearning(quiz?'quiz':LESSONS[current].id);syncOptimizationLab(quiz?'quiz':LESSONS[current].id);syncResearchReading(quiz?'quiz':LESSONS[current].id);if(quiz){syncLearningPath();history.replaceState(null,'','#quiz');queueLabDesign();return;}projectBoardKey='';fitProjectPending=true;prepareUrdfLesson(LESSONS[current].id);prepareMujocoLesson(LESSONS[current].id);state=Object.fromEntries(LESSONS[current].controls.map(c=>[c.key,c.value]));productReplayRestore(LESSONS[current].id,reset);$('theory').innerHTML=LESSONS[current].theory;buildControls();setTab(selectedTab);history.replaceState(null,'','#'+LESSONS[current].id);$('prev').disabled=current===0;$('next').textContent=current===LESSONS.length-1?'开始自测 →':'下一实验 →';syncLearningPath();requestAnimationFrame(()=>{resize();syncLabDesign()});}
function resize(paintOnly=false){const rect=canvas.getBoundingClientRect();if(!rect.width)return;if(width!==rect.width||height!==rect.height){fitProjectPending=true;const b=$('nav').querySelector('.active');if(b&&innerWidth<=850)$('nav').scrollLeft=b.offsetLeft-$('nav').offsetLeft-($('nav').clientWidth-b.clientWidth)/2}width=rect.width;height=rect.height;const dpr=Math.min(window.devicePixelRatio||1,2);canvas.width=Math.round(width*dpr);canvas.height=Math.round(height*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);if(paintOnly===true)paint();else render()}
function setTab(tab){selectedTab=tab;for(const name of ['theory','code','source']){$(name==='theory'?'theory':name+'Panel').classList.toggle('hidden',tab!==name);$(name+'Tab').classList.toggle('selected',tab===name)}$('copyCode').classList.toggle('hidden',tab==='source')}
function toast(text){$('toast').textContent=text;$('toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').style.display='none',2600)}
function animate(now){const dt=Math.min((now-lastTime)/1000,.05);lastTime=now;if(playing&&current<LESSONS.length){animTime+=dt;const id=LESSONS[current].id;if(animateExtensionLesson(id,dt)){}else if(animateMujocoLab(id,dt)){}else if(animateProject(id,dt)){}else if(animateContactLoop(id,dt)){}else if(id==='rotation'){animateRotationLesson(state,dt)}else if(id==='interpolation'){state.t=Math.min(1,state.t+dt*.17);if(state.t>=1)stopPlay()}else if(id==='hinge'){state.theta=Math.round(40+40*Math.sin(animTime*.7))}else{const key={order:'alpha',transform:'yaw',axis:'theta',tcp:'yaw',camera:'az',vectors:'nz'}[id];if(id==='vectors')state[key]=Math.round((.5+.5*Math.sin(animTime))*100)/100;else state[key]=Math.round(((state[key]+dt*40+180)%360-180)*100)/100}syncControls();render()}requestAnimationFrame(animate)}
$('nav').innerHTML=LESSONS.map((l,i)=>'<button data-lesson="'+i+'"><span class="num">'+String(i+1).padStart(2,'0')+'</span>'+l.name+'</button>').join('')+'<button data-lesson="'+LESSONS.length+'"><span class="num">Q/A</span>自测与易错点</button>';$('nav').querySelectorAll('button').forEach(el=>el.addEventListener('click',()=>setLesson(+el.dataset.lesson)));
initLabDesign();$('lessonSearch').addEventListener('input',filterLessonNavigation);filterLessonNavigation();
$('quizGrid').innerHTML=QUESTIONS.map(([q,choices],i)=>'<article class="question"><h3>'+String(i+1).padStart(2,'0')+' · '+q+'</h3>'+choices.map((a,j)=>'<label><input type="radio" name="q'+i+'" value="'+j+'">'+esc(a)+'</label>').join('')+'<div class="answer" id="answer-'+i+'"></div></article>').join('');
$('checkQuiz').addEventListener('click',()=>{let correct=0,answered=0;QUESTIONS.forEach((q,i)=>{const selected=document.querySelector('input[name="q'+i+'"]:checked'),ok=selected&&+selected.value===q[2];if(selected)answered++;if(ok)correct++;const a=$('answer-'+i);a.style.display='block';a.className='answer '+(ok?'correct':'wrong');a.textContent=(ok?'✓ 正确。':selected?'✕ 再想一想。':'— 尚未作答。')+' '+q[3]});$('quizScore').textContent=correct+' / '+QUESTIONS.length+' 正确 · 已作答 '+answered+' 题'});
$('resetQuiz').addEventListener('click',()=>{document.querySelectorAll('.quiz input').forEach(el=>el.checked=false);document.querySelectorAll('.answer').forEach(el=>el.style.display='none');$('quizScore').textContent=''});
$('play').addEventListener('click',()=>{playing=!playing;animTime=0;$('play').textContent=playing?'Ⅱ 暂停变化':'▶ 播放变化'});$('reset').addEventListener('click',()=>{if(LESSONS[current]?.id==='mujoco')resetMujocoExperiment();if(URDF_LESSONS.some(l=>l.id===LESSONS[current]?.id))resetUrdfExperiment();setLesson(current,true)});$('prev').addEventListener('click',()=>stepLearningLesson(-1));$('next').addEventListener('click',()=>stepLearningLesson(1));$('theoryTab').addEventListener('click',()=>setTab('theory'));$('codeTab').addEventListener('click',()=>setTab('code'));$('sourceTab').addEventListener('click',()=>setTab('source'));
$('copyCode').addEventListener('click',async()=>{const code=$('code').textContent;try{if(navigator.clipboard&&window.isSecureContext){await navigator.clipboard.writeText(code)}else{const area=document.createElement('textarea');area.value=code;area.style.position='fixed';area.style.opacity='0';document.body.append(area);area.select();const ok=document.execCommand('copy');area.remove();if(!ok)throw Error('copy unavailable')}toast('已复制当前参数的 Python 示例')}catch{setTab('code');toast('无法自动复制，请选中代码手动复制')}});
$('conventionsButton').addEventListener('click',()=>$('help').showModal());$('closeHelp').addEventListener('click',()=>$('help').close());$('help').addEventListener('click',e=>{if(e.target===$('help')){const r=$('help').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('help').close()}});
document.querySelectorAll('[data-view]').forEach(b=>b.addEventListener('click',()=>{const v=b.dataset.view;if(v==='xy'){view.yaw=-Math.PI/2;view.pitch=Math.PI/2-.001}else if(v==='xz'){view.yaw=-Math.PI/2;view.pitch=.001}else{Object.assign(view,defaultView());fitProjectPending=true}render()}));
let drag=null;for(const canvas of [$('scene'),$('mujocoCanvas')]){canvas.addEventListener('contextmenu',e=>e.preventDefault());canvas.addEventListener('pointerdown',e=>{if(e.button!==0&&e.button!==2)return;e.preventDefault();drag={x:e.clientX,y:e.clientY,pan:e.button===2};canvas.setPointerCapture(e.pointerId)});canvas.addEventListener('pointermove',e=>{if(!drag)return;const dx=e.clientX-drag.x,dy=e.clientY-drag.y;if(drag.pan){view.panX=(view.panX||0)+dx;view.panY=(view.panY||0)+dy}else{view.yaw-=dx*.008;view.pitch=Math.max(-1.45,Math.min(1.55,view.pitch+dy*.008))}drag={x:e.clientX,y:e.clientY,pan:drag.pan};render()});const endDrag=()=>drag=null;canvas.addEventListener('pointerup',endDrag);canvas.addEventListener('pointercancel',endDrag);canvas.addEventListener('lostpointercapture',endDrag);canvas.addEventListener('wheel',e=>{if(!e.ctrlKey&&!e.metaKey)return;e.preventDefault();view.zoom=Math.max(.45,Math.min(2.7,view.zoom*Math.exp(-e.deltaY*.001)));render()},{passive:false});canvas.addEventListener('dblclick',()=>{Object.assign(view,defaultView());fitProjectPending=true;render()});}
$('viewerReadout').addEventListener('toggle',()=>{if($('viewerReadout').offsetWidth)render()});
$('viewerReadout').addEventListener('keydown',e=>{
  if(e.key==='Escape'&&$('viewerReadout').open){
    $('viewerReadout').open=false;$('viewerReadout').querySelector('summary').focus({preventScroll:true});e.stopPropagation();
  }
});
document.addEventListener('keydown',e=>{if(LearningPath.home||e.target.closest('input,select,textarea,button,summary,.math-equation-scroll,#viewerReadout')||$('help').open)return;if(e.key==='ArrowLeft'){e.preventDefault();stepLearningLesson(-1)}if(e.key==='ArrowRight'){e.preventDefault();stepLearningLesson(1)}if(e.code==='Space'&&!LearningPath.standalone&&current<LESSONS.length){e.preventDefault();$('play').click()}});
