window.GeometryLab={math:G,projectMath:PM,extraMath:ExtraMath,urdfMath:UrdfMath,urdfParser:UrdfParser,getUrdfState:()=>({model:URDFLab.model,q:{...URDFLab.q},result:URDFLab.cache?.result,filename:URDFLab.filename}),data:PD,selfTest:G.selfTest,getState:()=>({lesson:activeLearningLesson(),parameters:LearningPath.standalone?{}:{...state},view:{...view},playing}),goTo:id=>{if(id===TOOL_TARGET_ROUTE){openLearningLesson(id);return}if(id==='roadmap'){openLearningMap();return}const n=LESSONS.findIndex(l=>l.id===id);setLesson(id==='quiz'?LESSONS.length:n<0?0:n)}};
console.info('GeometryLab math checks',G.selfTest());
initProductPreview();
const initialHash=location.hash.slice(1);
if(initialHash===TOOL_TARGET_ROUTE)openToolTargetCourse(false);
else if(!openRepresentationRoute(initialHash)){
  const initial=LESSONS.findIndex(l=>l.id===initialHash);
  setLesson(initialHash==='quiz'?LESSONS.length:initial<0?LESSONS.findIndex(l=>l.id==='rgbdbackground'):initial);
  LearningPath.hasLesson=initial>=0||initialHash==='quiz';
  if(!initialHash||initialHash==='roadmap')openLearningMap();
}
